WordHunterWoW_QuestEN[52746] = { title = "The War Cache", description = "First things first. Remember... this is a war.\n\nWe accomplish nothing by simply adding the Zandalari to our ranks. We eventually need to crush the Alliance.\n\nYou and I will be leading operations in Kul Tiras. But first, we need resources.", objectives = "Gather 100 War Resources. War Resources can be obtained from many sources, including quests and treasure chests.", completion = "<Nathanos looks over the gathered resources.>\n\nThis should do it." }
WordHunterWoW_QuestEN[52748] = { title = "Eyes on the Skies", description = "You have made a great deal of progress with Kua'fon. He may not yet possess de power of flight, but he is healthy and growing.\n\nTake de success you have made and build upon it, {name}. Do not let Pa'ku's lesson dishearten you.\n\nContinue to do as you have been. Nurture Kua'fon, build his confidence in his wings. Show him de way forward and he will reward you with a bond stronger than any you have ever known.\n\nWhen his wings are large enough to shade you, we will try again.", objectives = "Tend to Kua'fon until he is fully grown.", completion = "<Kua'fon spreads his magnificent wings.>\n\nSkree!" }
WordHunterWoW_QuestEN[52749] = { title = "The War Campaign", description = "{name}, a moment of your time.\n\nBefore you leave the city, speak with me out on the Banshee's Wail, on the docks. I have information to discuss with you about the war against the Alliance.", objectives = "Report to Nathanos Blightcaller aboard the Banshee's Wail in Zuldazar.", completion = "You're here." }
WordHunterWoW_QuestEN[52750] = { title = "Farmers Who Fight", description = "I was hoping for a squad of Proudmoore Academy's finest, but I guess you'll have to do.\n\nWhat we lack in manpower we make up for in courage! Even the farmers here won't give up their land without a fight.\n\nSend the bravest of them to me. They will fight better alongside our marines than by themselves out in the fields!", objectives = "Recruit 6 Vigil Hill Farmers into the militia.", completion = "We'll get those volunteers paired up with the regulars and give 'em a fighting chance." }
WordHunterWoW_QuestEN[52751] = { title = "Strange Looking Dogs", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[52752] = { title = "Vigilant Lookouts", description = "", objectives = "" }
