WordHunterWoW_QuestEN[52761] = { title = "Siege of Boralus: Blood Money", description = "", objectives = "" }
WordHunterWoW_QuestEN[52762] = { title = "A Local Guide", description = "I've spent a lot of time as a guest of the Harbormaster and I've come to understand a few things about Flynn Fairwind. If anyone can quickly help you to sort out any clues in Freehold, it will be him.\n\nFlynn's been doing work for Cyrus and can be found in the Harbormaster's office. Show him the contract and recruit him to our cause. Hurry, {name}.", objectives = "Find Flynn Fairwind at the Harbormaster's office in Boralus.", progress = "You fight monsters, unite kingdoms and now you're going to save a princess? You really do take on a lot of this 'hero' stuff. I just hope it doesn't catch.", completion = "I'd hoped maybe Lady Jaina's location was in the fine print but no such luck. I can confirm that Ashvane was doing business with the Irontide. So we're off to Freehold. Again.\n\nJoy." }
WordHunterWoW_QuestEN[52763] = { title = "Siege of Boralus: Breaking Their Ranks", description = "", objectives = "" }
WordHunterWoW_QuestEN[52764] = { title = "Journey to the Middle of Nowhere", description = "Our tidesage, Thomas Zelling, claims to have found the wreckage of Marshal Valentine's ship.\n\nTook him long enough.\n\nMarshal Valentine's body is the final piece of our plan, and it lies within that shipwreck. When you're ready, let us depart for his resting place.", objectives = "Speak with Dread-Admiral Tattersail to sail to the Great Sea.", completion = "This is the spot." }
WordHunterWoW_QuestEN[52765] = { title = "Deep Dive", description = "We need you to retrieve Marshal M. Valentine's body at the ocean floor below.\n\nI should warn you: this part of the ocean is going to be very deep, and very dark, and very cold.\n\nSpeak with Hobart at the starboard side of the ship. He's brought all the machinery you'll need to get to the ocean floor.", objectives = "Speak with Hobart Grapplehammer to dive to the ocean floor, then test your headlamp." }
WordHunterWoW_QuestEN[52766] = { title = "Seafloor Shipwreck", description = "<static>\n\n... look for shipwreck ...\n\n<static>\n\n... east ...\n\n<static>", objectives = "Look for a shipwreck somewhere to the east, apparently." }
WordHunterWoW_QuestEN[52767] = { title = "Checking Dog Tags", description = "You are no longer able to hear Hobart's voice over the static.\n\nYou can make out the outlines of several floating bodies nearby. They have significantly decomposed, but their dog tags should still be intact.\n\nHopefully the dog tags can help identify Marshal Valentine.", objectives = "Find and identify the captain of the shipwreck." }
WordHunterWoW_QuestEN[52768] = { title = "The Sunken Graveyard", description = "<static>\n\n...wait ... more shipwrecks ...\n\n<static>\n\n... lots of 'em ... northeast ...\n\n<static>", objectives = "Look for more shipwrecks to the northeast of your current location." }
WordHunterWoW_QuestEN[52769] = { title = "Captain By Captain", description = "Seems like you're on your own.\n\nMore shipwrecks lie along the bottom of the sea. This must have been the location of a major battle.\n\nTime to start checking dog tags to find Marshal Valentine.", objectives = "Identify the captains of the three nearby ships." }
WordHunterWoW_QuestEN[52770] = { title = "Biolumi-Nuisance", description = "<static>\n\n... having trouble hearing you ...\n\n<static>\n\n... electrical interference ... bioluminescent creatures ...\n\n<static>\n\n... getting annoying ...\n\n<static>", objectives = "Kill 10 bioluminescent creatures to fix your communications issues with Hobart." }
WordHunterWoW_QuestEN[52771] = { title = "Siege of Boralus: Breaking Irons", description = "", objectives = "" }
WordHunterWoW_QuestEN[52772] = { title = "The Undersea Ledge", description = "So, now that we can hear each other again, lemme tell you what's been goin' on up here.\n\nApparently we were off by like, a league. Somethin' about undersea currents, somethin' about the tides of time, yadda yadda. I think Zelling is getting rusty.\n\nPoint is, you're not far off now. We're SURE that Marshal Valentine is right to the east of ya, in a shipwreck up on a ledge. Zelling says there's something else big up there too, but he can't tell what it is.", objectives = "Find Marshal Valentine's shipwreck on the undersea ledge nearby." }
WordHunterWoW_QuestEN[52773] = { title = "Water-Breathing Dragon", description = "Huh. A dragon, you say? I suppose that makes sense. I mean, the Horde did utilize red dragons as part of their army during the second war, but... well, we don't talk about that very much anymore.\n\nStill, Valentine is on that ship. You're gonna have to get past that dragon one way or another.", objectives = "Slay Daenistrasz." }
WordHunterWoW_QuestEN[52774] = { title = "Grab and Go", description = "Nothin' left to do but grab that Marshal and bring him back up to the surface, then.\n\nThough I guess you might as well search the shipwreck for anything else of value. You spent all that time gettin' down there, and time is money.", objectives = "Grab Marshal M. Valentine's body, as well as the body of the other sailor aboard his ship.", completion = "<Nathanos looks at the two sailors' bodies, pauses for a moment, and then laughs.>\n\nNot only did you succeed, but you've also brought me the corpse of Lady Proudmoore's firstborn son?! You make my job easy, <name>." }
WordHunterWoW_QuestEN[52775] = { title = "Siege of Boralus: What's Yours is Mine", description = "", objectives = "" }
WordHunterWoW_QuestEN[52776] = { title = "Mission Report: Stonetusk Watch", description = "Your followers have sent a report regarding the assault on Stonetusk Watch.\n\nIt details that victory was hard-fought, but the outpost has been secured.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "Deliver the victory report to Nathanos Blightcaller.", progress = "Do you have news regarding the mission to Stormsong Valley?", completion = "It seems the mission to create an additional foothold in Stormsong Valley was a success. Well done, <name>.\n\nI will send you to oversee the fortifications at once." }
WordHunterWoW_QuestEN[52777] = { title = "Stonetusk Watch", description = "The raid you planned for Stonetusk Watch in Stormsong Valley was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Stonetusk Watch in Stormsong Valley and establish fortifications there.\n\nThe outpost will be essential in our campaign against the Alliance.\n\nGo with honor!", objectives = "Claim Stonetusk Watch for the Horde.", completion = "Well met, <name>. This is a fine location for an outpost! Thanks to your leadership the Horde has yet another foothold in Stormsong Valley!" }
WordHunterWoW_QuestEN[52778] = { title = "Siege of Boralus: Crushing the Horde", description = "", objectives = "" }
WordHunterWoW_QuestEN[52779] = { title = "Crawg in the Bog", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[52780] = { title = "Siege of Boralus: Breaking the Alliance", description = "", objectives = "" }
WordHunterWoW_QuestEN[52782] = { title = "Call to Arms: Stormsong Valley", description = "We've discovered a spike of Horde activity within Stormsong Valley. We cannot allow them to get the upper hand.", objectives = "Slay Horde within Stormsong Valley.", completion = "Great work, <class>." }
WordHunterWoW_QuestEN[52784] = { title = "The Horde Slayer", description = "Wow! Keep it up, soldier! \n\nSlay a bit more Horde and you will go down in the record books among the Alliance. \n\nBut it won't be easy, the Horde have put a bounty on your head, so watch it!\n\nFor the Alliance!", objectives = "While being hunted by the Horde, slay 10 Horde without dying." }
WordHunterWoW_QuestEN[52785] = { title = "Smashing Zalamar", description = "", objectives = "" }
WordHunterWoW_QuestEN[52786] = { title = "The Alliance Slayer", description = "Yes! Keep going, keep slaying those Alliance dogs!\n\nSlay a bit more Alliance and you may set a new record, {class}.\n\nBut it won't be easy, the Alliance have put a bounty on your head, so watch it!\n\nFor the Horde!", objectives = "With a bounty on your head, slay 10 Alliance without dying." }
WordHunterWoW_QuestEN[52787] = { title = "Numbing the Pain", description = "The medics here are doing their best, but they've suffered heavy casualties and are strapped for healing supplies.\n\nWith a few clumps of evermoss I could mix a painkilling tincture to ease the suffering of the injured. Can you forage some from the nearby trees?\n\nI'll help get Flynn stabilized. The last thing these people need is another wounded man howling in pain.", objectives = "Gather 5 Evermoss Clumps.", progress = "Did you find any evermoss?", completion = "That should do." }
WordHunterWoW_QuestEN[52788] = { title = "Leave None Alive", description = "Our initial assault was a success. The Dark Iron dwarves are holding the line. Now it's our turn.\n\nYou and I must cleave a path through these Zandalari and eliminate them. Our forces will handle any that remain.\n\nOur goal is to weaken their forces and find two important targets: the ship's captain and its advisor.\n\nLet's go, {name}. If we fail here, all of our efforts will be thwarted.", objectives = "Kill 10 Zandalari soldiers on board the Gral's Call.", progress = "We don't have time to talk!", completion = "Good work, that should be enough for the others to handle. We have one final target." }
WordHunterWoW_QuestEN[52789] = { title = "Silencing the Advisor", description = "The ship's captain is nowhere to be found. Shandris and Falstad will handle locating him.\n\nWe must go after the ship's advisor. Kelsey's logs indicate her name is Ko'jan. \n\nShe may have methods to reach out to the mainland. We have to move before she tries to use any of them.", objectives = "Kill Advisor Ko'jan.", progress = "Let's get moving.", completion = "It sounds like fighting up above has stopped. I trust Falstad and Shandris have the ship's captain.\n\nLet's see if they managed to capture him alive." }
WordHunterWoW_QuestEN[52790] = { title = "An End to the Killing", description = "Let's return to the upper decks and see what our current status is. Shandris should be there by now.\n\nI know Shandris and Falstad well enough that they will be there with the captain of this ship, dead or alive.", objectives = "Meet Shandris Feathermoon on the deck of Gral's Call.", completion = "<name>! I only just received the message of your success in Zandalar. Well done.\n\nI'm sorry for everything that you've been put through on behalf of this war. We have only one option if we want to stop the Zandalari from aiding the Horde.\n\nWhen the time is right, we will send our fleets to Zandalar. Your hard work will ensure we have a breach in their defenses to begin our invasion.\n\nThank you once more, <name>. We owe a great debt to you and your allies." }
WordHunterWoW_QuestEN[52792] = { title = "Arathi Donations: Akunda's Bite", description = "", objectives = "We be needin' an abundance of herbs to keep dem stockpiles up an' ready.", progress = "We be needin' an abundance of herbs to keep dem stockpiles up an' ready.", completion = "Jus' the kinda stuff I was hopin' for." }
WordHunterWoW_QuestEN[52793] = { title = "Circle the Wagons", description = "Darion and the girls should have been back by now.  \n\nMaybe they had trouble on the road, that old wagon is always breaking down.  I need to be sure they are safe!\n\nCan you check on them for me?", objectives = "Find Darion, Lorraine, and Mallory.", completion = "Thank you.  I can rest easy knowing they are safe." }
WordHunterWoW_QuestEN[52794] = { title = "Lizards and Ledgers", description = "", objectives = "" }
WordHunterWoW_QuestEN[52795] = { title = "A Saur Point", description = "That saurolisk has been a folktale in these hills for years. \"Sourtooth, you can smell his breath from miles away\".  \n\nToday that folktale attacked my family, almost killed my father and sister. It's time for it to die.", objectives = "Slay Sourtooth", progress = "I'm not leaving till Sourtooth is dead!", completion = "No more smelling it's breath in the wind." }
WordHunterWoW_QuestEN[52796] = { title = "Sometimes Less Is More", description = "I don't really hate saurolisk, but there seem to be a lot more around lately. \n\nStormsong's military used to thin out the population, but they didn't show up this year.\n\nMaybe you could do the job they didn't!", objectives = "Eliminate 8 Saurolisk.", completion = "Thank you.  I can rest easy knowing they are safe." }
WordHunterWoW_QuestEN[52798] = { title = "A Few More Charges", description = "", objectives = "" }
WordHunterWoW_QuestEN[52799] = { title = "Pack Leader", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[52800] = { title = "Tol Dagor: The Ashvane Overseer", description = "Tol Dagor stands as a well fortified thorn in this nation's side.\n\nAs you are no doubt aware, Ashvane has taken every opportunity she could to throw any opposition into those cells. Among those in the jail are members of the Alliance that arrived alongside you and Jaina.\n\nWe now have permission and the needed muscle to free them. Meet up with Taelia on the eastern shore of the island, find the overseer, and take his key. With it, we will have access to the weapon vault and cells.", objectives = "Retrieve the Tol Dagor Master Key from Overseer Korgus.", progress = "Well?", completion = "Most of those hostages have seen better days, but they will recover quickly. With Tol Dagor out of the way, Ashvane is quickly running out of places to hide." }
WordHunterWoW_QuestEN[52801] = { title = "Mission Report: Veiled Grotto", description = "Your followers have sent a report regarding the assault on Veiled Grotto.\n\nIt details that victory was hard-fought, but the enemies guarding the outpost have been slain.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", objectives = "Deliver the victory report to Halford Wyrmbane.", progress = "Do you have news regarding the mission to Zuldazar?", completion = "It seems the mission to create an additional foothold in Zuldazar was a success. Well done, <name>.\n\nI will send you to oversee the fortifications at once." }
WordHunterWoW_QuestEN[52802] = { title = "Veiled Grotto", description = "The raid you planned for Veiled Grotto in Zuldazar was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Veiled Grotto in Zuldazar and establish fortifications there.\n\nVeiled Grotto will be an essential outpost in our campaign against the Horde.\n\nFor the Alliance!", objectives = "Claim Veiled Grotto for the Alliance.", completion = "Well done, <name>. This is a fine location for an outpost! Thanks to your leadership the Alliance has yet another foothold in Zuldazar!" }
WordHunterWoW_QuestEN[52803] = { title = "Accidental Dread", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[52804] = { title = "Something Stirs in the Depths", description = "", objectives = "" }
WordHunterWoW_QuestEN[52805] = { title = "Like Pulling Teeth", description = "", objectives = "Kill 25 wendigo." }
WordHunterWoW_QuestEN[52806] = { title = "A Looming Threat", description = "This stalemate is unwise to pursue. Let's regroup at the Blackwood Den.", objectives = "Regroup with Lady Sylvanas Windrunner at the Blackwood Den.", progress = "Death is an inevitability.", completion = "We must wait for Saurfang to return before we proceed." }
