WordHunterWoW_QuestEN[52834] = { title = "Seal of Wartorn Fate: Gold", description = "Do you ever wish to retry your fate?  Perhaps, for a special armor piece, a weapon or a trinket of great power?\n\nFor a price, I will provide you a seal that twists fate and grants an extra result at a past chance. \n\nOnce you possess a seal, it will activate after defeating powerful foes in difficult dungeons and raids.\n\nChoose how you want to pay wisely, for two seals a week is all the power you can manage.", objectives = "Do you ever wish to retry your fate?  Perhaps, for a special armor piece, a weapon or a trinket of great power?\n\nFor a price, I will provide you a seal that twists fate and grants an extra result at a past chance. \n\nOnce you possess a seal, it will activate after defeating powerful foes in difficult dungeons and raids.\n\nChoose how you want to pay wisely, for two seals a week is all the power you can manage.", progress = "Do you ever wish to retry your fate?  Perhaps, for a special armor piece, a weapon or a trinket of great power?\n\nFor a price, I will provide you a seal that twists fate and grants an extra result at a past chance. \n\nOnce you possess a seal, it will activate after defeating powerful foes in difficult dungeons and raids.\n\nChoose how you want to pay wisely, for two seals a week is all the power you can manage.", completion = "A good choice.  Remember, only two seals a week." }
WordHunterWoW_QuestEN[52835] = { title = "Seal of Wartorn Fate: Marks of Honor", description = "Do you ever wish to retry your fate?  Perhaps, for a special armor piece, a weapon or a trinket of great power?\n\nFor a price, I will provide you a seal that twists fate and grants an extra result at a past chance. \n\nOnce you possess a seal, it will activate after defeating powerful foes in difficult dungeons and raids.\n\nChoose how you want to pay wisely, for two seals a week is all the power you can manage.", objectives = "Do you ever wish to retry your fate?  Perhaps, for a special armor piece, a weapon or a trinket of great power?\n\nFor a price, I will provide you a seal that twists fate and grants an extra result at a past chance. \n\nOnce you possess a seal, it will activate after defeating powerful foes in difficult dungeons and raids.\n\nChoose how you want to pay wisely, for two seals a week is all the power you can manage.", progress = "Do you ever wish to retry your fate?  Perhaps, for a special armor piece, a weapon or a trinket of great power?\n\nFor a price, I will provide you a seal that twists fate and grants an extra result at a past chance. \n\nOnce you possess a seal, it will activate after defeating powerful foes in difficult dungeons and raids.\n\nChoose how you want to pay wisely, for two seals a week is all the power you can manage.", completion = "A good choice.  Remember, only two seals a week." }
WordHunterWoW_QuestEN[52837] = { title = "Seal of Wartorn Fate: War Resources", description = "Do you ever wish to retry your fate?  Perhaps, for a special armor piece, a weapon or a trinket of great power?\n\nFor a price, I will provide you a seal that twists fate and grants an extra result at a past chance. \n\nOnce you possess a seal, it will activate after defeating powerful foes in difficult dungeons and raids.\n\nChoose how you want to pay wisely, for two seals a week is all the power you can manage.", objectives = "Do you ever wish to retry your fate?  Perhaps, for a special armor piece, a weapon or a trinket of great power?\n\nFor a price, I will provide you a seal that twists fate and grants an extra result at a past chance. \n\nOnce you possess a seal, it will activate after defeating powerful foes in difficult dungeons and raids.\n\nChoose how you want to pay wisely, for two seals a week is all the power you can manage.", progress = "Do you ever wish to retry your fate?  Perhaps, for a special armor piece, a weapon or a trinket of great power?\n\nFor a price, I will provide you a seal that twists fate and grants an extra result at a past chance. \n\nOnce you possess a seal, it will activate after defeating powerful foes in difficult dungeons and raids.\n\nChoose how you want to pay wisely, for two seals a week is all the power you can manage.", completion = "A good choice.  Remember, only two seals a week." }
WordHunterWoW_QuestEN[52838] = { title = "Seal of Wartorn Fate: Piles of Gold", description = "Tempting fate yet again? The cost has increased and I offer other cheaper ways to pay. \n\nHowever, if you want to pay this fee, who am I to stop you?\n\nChoose how you want to pay wisely, for two seals a week is all the power you can manage.", objectives = "Tempting fate yet again? The cost has increased and I offer other cheaper ways to pay. \n\nHowever, if you want to pay this fee, who am I to stop you?\n\nChoose how you want to pay wisely, for two seals a week is all the power you can manage.", progress = "Tempting fate yet again? The cost has increased and I offer other cheaper ways to pay. \n\nHowever, if you want to pay this fee, who am I to stop you?\n\nChoose how you want to pay wisely, for two seals a week is all the power you can manage.", completion = "A good choice.  Remember, only two seals a week." }
WordHunterWoW_QuestEN[52839] = { title = "Seal of Wartorn Fate: Additional Marks of Honor", description = "Tempting fate yet again? The cost has increased and I offer other cheaper ways to pay. \n\nHowever, if you want to pay this fee, who am I to stop you?\n\nChoose how you want to pay wisely, for two seals a week is all the power you can manage.", objectives = "Tempting fate yet again? The cost has increased and I offer other cheaper ways to pay. \n\nHowever, if you want to pay this fee, who am I to stop you?\n\nChoose how you want to pay wisely, for two seals a week is all the power you can manage.", progress = "Tempting fate yet again? The cost has increased and I offer other cheaper ways to pay. \n\nHowever, if you want to pay this fee, who am I to stop you?\n\nChoose how you want to pay wisely, for two seals a week is all the power you can manage.", completion = "A good choice.  Remember, only two seals a week." }
