WordHunterWoW_QuestEN[52851] = { title = "Mission Report: Mugamba Overlook", description = "Your followers have sent a report regarding the assault on Mugamba Overlook.\n\nIt details that victory was hard-fought, but the enemies guarding the outpost have been slain.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", objectives = "Deliver the victory report to Halford Wyrmbane.", progress = "Do you have news regarding the mission to Zuldazar?", completion = "It seems the mission to create an additional foothold in Zuldazar was a success. Well done, <name>.\n\nI will send you to oversee the fortifications at once." }
WordHunterWoW_QuestEN[52852] = { title = "Mugamba Overlook", description = "The raid you planned for Mugamba Overlook in Zuldazar was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Mugamba Overlook in Zuldazar and establish fortifications there.\n\nMugamba Overlook will be an essential outpost in our campaign against the Horde.\n\nFor the Alliance!", objectives = "Claim Mugamba Overlook for the Alliance.", completion = "This will make a fine outpost. It is well-hidden and nearly impassable by foot. The Horde will never suspect that we've made camp here." }
WordHunterWoW_QuestEN[52855] = { title = "Alchemy is an Inexact Science", description = "Hey, look.\n\nIt worked, right? Mostly. I mean, it DID get bigger. Don't look at me like that! So there are some... weird side effects going on. When has that ever gotten in the way of science before?\n\nOkay, okay, okay!\n\nI have an idea. Go and get me everything on this list. And be quick about it! I think these Zandalari might do something to me if you-- if WE-- don't fix this.\n\n<Alexxi hastily pens a list of ingredients and hands it to you.>\n\nDo me a solid, eh?", objectives = "Gather 1 Crown of Torcali and 8 Glowfly Incandescence for Trader Alexxi in Warbeast Kraal.", progress = "Those claws look really sharp, <name>. Do you have what I need?", completion = "Whew! Maybe this will calm them down." }
WordHunterWoW_QuestEN[52856] = { title = "Snakes on a Terrace", description = "", objectives = "Defeat Grixis Tinypop in a pet battle." }
WordHunterWoW_QuestEN[52857] = { title = "Held For Observation", description = "<Trader Alexxi hurriedly combines the ingredients.>\n\nThat should do it. Go on and get this down your direhorn's gullet.\n\nDon't worry, nothing could possibly go wrong with a concoction made under any kind of duress. Also, do I seem like the kind of goblin who would give you something dangerous?\n\nOn purpose?\n\n... Don't answer that. Hurry, before they stab me.", objectives = "Administer the remedy to your direhorn.", progress = "<The direhorn hiccoughs in distress.>", completion = "<Beastlord L'kala peers mistrustfully at Alexxi, then back at you.>\n\nNone of this was necessary. Go. I need time to determine what is to be done about your direhorn." }
WordHunterWoW_QuestEN[52858] = { title = "Azerite Empowerment", description = "", objectives = "" }
WordHunterWoW_QuestEN[52861] = { title = "Champion: Lilian Voss", description = "", objectives = "I have fought alongside you in this campaign for some time now, <name>.\n\nWe have witnessed firsthand the lengths that the Horde will go to to win. It may not always be pretty, but in the end we have achieved the upper hand.\n\nI am curious to watch what Sylvanas does next. I am also curious to watch you.\n\nYou are an honorable man, <name>. Allow me to continue this fight by your side." }
