WordHunterWoW_QuestEN[52876] = { title = "WANTED: War Gore", description = "By the decree of the Storm's Wake.\n\nScouts have reported that forsaken scientists have created a monster, sewn together from the bodies of our own fallen soldiers.  \n\nThis monstrosity is called, War Gore.\n\nThe individual that destroys this abomination will earn a fitting reward.", objectives = "Find and kill War Gore", completion = "One less threat to safety of Stormsong" }
