WordHunterWoW_QuestEN[52886] = { title = "Mission Report: Verdant Hollow", description = "Your followers have sent a report regarding the assault on Verdant Hollow.\n\nIt details that victory was hard-fought, but the enemies guarding the outpost have been slain.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", objectives = "Deliver the victory report to Halford Wyrmbane.", progress = "Do you have news regarding the mission to Zuldazar?", completion = "It seems the mission to create an additional foothold in Zuldazar was a success. Well done, <name>.\n\nI will send you to oversee the fortifications at once." }
WordHunterWoW_QuestEN[52888] = { title = "Verdant Hollow", description = "The raid you planned for Verdant Hollow in Zuldazar was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Verdant Hollow in Zuldazar and establish fortifications there.\n\nVerdant Hollow will be an essential outpost in our campaign against the Horde.\n\nFor the Alliance!", objectives = "Claim Verdant Hollow for the Alliance.", completion = "This'll be a fine location for an outpost. There are azerite deposits nearby and plenty o' big game fer huntin' as well!" }
