WordHunterWoW_QuestEN[52928] = { title = "Arathi Donations: Coarse Leather", description = "", objectives = "Word came through that our leather supply is running rather low. Any donations you can spare would be greatly appreciated.", progress = "Word came through that our leather supply is running rather low. Any donations you can spare would be greatly appreciated.", completion = "With a donation like this you are truly saving our hide." }
WordHunterWoW_QuestEN[52929] = { title = "Arathi Donations: Monelite Ore", description = "", objectives = "An abundance of ore is the backbone to a steady supply of armor and weaponry.", progress = "An abundance of ore is the backbone to a steady supply of armor and weaponry.", completion = "Heh. A generous amount of ore.\n\nThis'll keep our smiths busy for a while." }
WordHunterWoW_QuestEN[52930] = { title = "Arathi Donations: Gold", description = "Our friends here are accepting all kinds of donations on behalf of the war effort, but if ya ask me, no battle was ever won without proper funding. That's right, bub. I'm talking about money! And lots of it.\n\nIf you got it, we need it!", objectives = "Donate 1000000 Gold to Paymaster Grintooth in the Port of Zandalar.", progress = "A <class> like you's surely gotta have a little extra cash in your stash.\n\nWaddaya say? Lemme help lighten your load a bit?", completion = "Ain't nothin' more valuable than sweet, sweet gold." }
