WordHunterWoW_QuestEN[52941] = { title = "Light in the Darkness", description = "", objectives = "" }
WordHunterWoW_QuestEN[52942] = { title = "Restoring Old Bonds", description = "We must speak to Grommash Hellscream and remind him of his debt to us. Everything rests on this mission, {name}.\n\nI hope your skills in diplomacy are greater than mine.\n\nBe on your guard; we do not know what to expect on the other side.", objectives = "Speak with Oculeth to travel to Draenor and meet with the Mag'har.", completion = "We're not dead yet. I suppose that is a good sign." }
WordHunterWoW_QuestEN[52943] = { title = "Calling Out the Clans", description = "This Overlord Geya'rah has a fire inside her. I may come to like her... if she doesn't kill us.\n\nWe have but one chance. You pay homage to the symbol of each clan, and I will speak of it.\n\nShow respect--or they will show us the executioner's blade.", objectives = "Pay homage to the orc clan symbols.", progress = "I do not have time for this.", completion = "So, you know of our clans." }
WordHunterWoW_QuestEN[52944] = { title = "Call to Arms: Drustvar", description = "We've discovered a spike of Horde activity within Drustvar. We cannot allow them to get the upper hand.", objectives = "Slay Horde within Drustvar.", completion = "Great work, <class>." }
WordHunterWoW_QuestEN[52945] = { title = "Bonds Forged Through Battle", description = "Geya'rah has a fiery spirit... like her mother. Perhaps facing a common foe will ease her wariness.\n\nWe subdued the ogre clans long ago. But every so often, one of their bravest--and stupidest--stirs the embers of rebellion. Today is such a day.\n\nYou and Eitrigg will join Geya'rah in putting down the ogre uprising. Prove yourself in battle and you may earn her respect.", objectives = "Assist Geya'rah in putting down the ogre uprising.", progress = "Don't slow me down.", completion = "We have to deal with an ogre uprising every few seasons." }
WordHunterWoW_QuestEN[52946] = { title = "A Dying World", description = "Champion, Azeroth be dyin' while the armies of the Horde and Alliance be fightin' over a ruined city.\n\nShe needs yer help. Make yer way to me camp in Silithus. Azeroth's got somethin' tae give ye.", objectives = "Meet Magni Bronzebeard in Silithus, located within Kalimdor.", completion = "Ye made it. We don't have any time tae lose." }
WordHunterWoW_QuestEN[52947] = { title = "Ettin Outta Here", description = "", objectives = "" }
WordHunterWoW_QuestEN[52948] = { title = "Call to Arms: Tiragarde Sound", description = "We've discovered a spike of Horde activity within Tiragarde Sound. We cannot allow them to get the upper hand.", objectives = "Slay Horde within Tiragarde Sound.", completion = "Great work, <class>." }
WordHunterWoW_QuestEN[52949] = { title = "Call to Arms: Nazmir", description = "It's time to press the attack within Horde territory, {class}! Travel to Nazmir and slay as many Horde as you find.", objectives = "Slay Horde within Nazmir.", completion = "Great work, <class>." }
WordHunterWoW_QuestEN[52950] = { title = "Call to Arms: Vol'dun", description = "It's time to press the attack within Horde territory, {class}! Travel to Vol'dun and slay as many Horde as you find.", objectives = "Slay Horde within Vol'dun.", completion = "Great work, <class>." }
WordHunterWoW_QuestEN[52951] = { title = "Call to Arms: Zuldazar", description = "It's time to press the attack within Horde territory, {class}! Travel to Zuldazar and slay as many Horde as you find.", objectives = "Slay Horde within Zuldazar.", completion = "Great work, <class>." }
WordHunterWoW_QuestEN[52952] = { title = "Call to Arms: Zuldazar", description = "We're getting reports of increased Alliance activity within Zuldazar. Head over there and clear them out.", objectives = "Slay Alliance within Zuldazar.", completion = "Good work, <class>." }
WordHunterWoW_QuestEN[52953] = { title = "Call to Arms: Vol'dun", description = "We're getting reports of increased Alliance activity within Vol'dun. Head over there and clear them out.", objectives = "Slay Alliance within Vol'dun.", completion = "Good work, <class>." }
WordHunterWoW_QuestEN[52954] = { title = "Call to Arms: Nazmir", description = "We're getting reports of increased Alliance activity within Nazmir. Head over there and clear them out.", objectives = "Slay Alliance within Nazmir.", completion = "Good work, <class>." }
WordHunterWoW_QuestEN[52955] = { title = "Tyranny of the Light", description = "If it is not an uprising of ogres or the promise of starvation, it's the constant threat of the Lightbound.\n\nShould the reports prove true, this is the closest they have dared approach our stronghold in quite some time.\n\nCome or stay, but make your decision quickly.", objectives = "Assist Geya'rah against the Tyranny of the Light.", completion = "To think of those we just lost... it is... No, it is of no use." }
WordHunterWoW_QuestEN[52956] = { title = "Call to Arms: Tiragarde Sound", description = "Its time to hit the Alliance at the source. Travel to Tiragarde Sound and slay every Alliance you find. It shouldn't be hard to find them in their own territory.", objectives = "Slay Alliance within Tiragarde Sound.", completion = "Good work, <class>." }
WordHunterWoW_QuestEN[52957] = { title = "Call to Arms: Stormsong Valley", description = "Its time to hit the Alliance at the source. Travel to Stormsong Valley and slay every Alliance you find. It shouldn't be hard to find them in their own territory.", objectives = "Slay Alliance within Stormsong Valley.", completion = "Good work, <class>." }
WordHunterWoW_QuestEN[52958] = { title = "Call to Arms: Drustvar", description = "Its time to hit the Alliance at the source. Travel to Drustvar and slay every Alliance you find. It shouldn't be hard to find them in their own territory.", objectives = "Slay Alliance within Drustvar.", completion = "Good work, <class>." }
WordHunterWoW_QuestEN[52962] = { title = "Mission Report: Mistvine Ledge", description = "Your followers have sent a report regarding the assault on Mistvine Ledge.\n\nIt details that victory was hard-fought, but the enemies surrounding the outpost have been slain.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", objectives = "Deliver the victory report to Halford Wyrmbane.", progress = "Do you have news regarding the mission to Zuldazar?", completion = "It seems the mission to create an additional foothold in Zuldazar was a success. Well done, <name>.\n\nI will send you to oversee the fortifications at once." }
WordHunterWoW_QuestEN[52963] = { title = "Mistvine Ledge", description = "The raid you planned for Mistvine Ledge in Zuldazar was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Mistvine Ledge in Zuldazar and establish fortifications there.\n\nMistvine Ledge will be an essential outpost in our campaign against the Horde.\n\nFor the Alliance!", objectives = "Claim Mistvine Ledge for the Alliance.", completion = "Greetings, <name>. Mistvine Ledge will surely be one of our most valuable outposts. We have a direct view of the Golden Throne and the jungle canopy provides ample camoflauge." }
WordHunterWoW_QuestEN[52964] = { title = "Pest Problem", description = "", objectives = "" }
WordHunterWoW_QuestEN[52965] = { title = "A Winter Veil Gift", description = "", objectives = "A small tag on this present reads:\n\nHappy holidays, <name>!" }
WordHunterWoW_QuestEN[52967] = { title = "Saurfang Returns", description = "Saurfang! It's about time.\n\nLook around you, hero! What a lovely sight -- the wisps are scattering. One by one, the walls come crashing down. \n\nNow is the time. The World Tree is ours for the taking! Find Saurfang. We shall finish this once and for all.", objectives = "Find Saurfang in Lor'danel.", completion = "Our journey was treacherous, but we never lost sight of our goal." }
WordHunterWoW_QuestEN[52968] = { title = "Time for a Little Blood", description = "", objectives = "" }
WordHunterWoW_QuestEN[52970] = { title = "No Small Mercy", description = "I will not slay innocents. If they do not raise arms against us, we shall spare them.\n\nEnter Lor'danel and capture any civilians you find there. They shall be questioned and then released.", objectives = "Capture 8 Lor'danel citizens.", completion = "We've shown honor to our enemy today." }
WordHunterWoW_QuestEN[52971] = { title = "Seaside Rendezvous", description = "Lor'danel has mustered significant reinforcements on its shore. Enough to drive us back.\n\nOne swift strike and we can end this threat!\n\nYou will break through their lines and slay the two commanders. Without leadership this force will crumble.", objectives = "Kill Caranne Briarbow and Ariel Stagguard", completion = "I congratulate you on your success, but I sense something is not right..." }
WordHunterWoW_QuestEN[52972] = { title = "Favored Grandchild", description = "", objectives = "" }
WordHunterWoW_QuestEN[52973] = { title = "A Threat from the North", description = "The Horde must have scaled the mountains of Felwood in the North. \n\nThe wisp wall is failing, it is only a matter of time before the Horde breaks through. They will attack us from both sides. \n\nWe must weather this attack together.", objectives = "Find Malfurion Stormrage in Lor'danel.", completion = "No matter the odds, we must stay strong." }
WordHunterWoW_QuestEN[52974] = { title = "Rescue Effort", description = "The suddenness of the Horde's attack gave citizens here little time to flee. Many are hiding in Lor'danel, waiting for help. \n\nLocate these civilians and send them to safety. We're counting on you, {name}.", objectives = "Rescue 8 Lor'danel citizens.", completion = "You've saved many lives today, <name>. You have my thanks." }
WordHunterWoW_QuestEN[52975] = { title = "Action This Day", description = "Two of the Horde's strongest warriors have led a charge to try and capture our fleet. We cannot allow this, {name}.\n\nIf they take our ships, they will use them to sail to Darnassus!\n\nSlay the two warriors leading the attack, and the rest of them will give up the fight.", objectives = "Eliminate Gormok Axefall, and Ragash Bloodwish.", completion = "Have you heard from Malfurion recently?" }
WordHunterWoW_QuestEN[52977] = { title = "The Guidance of Our Shan'do", description = "Lor'danel is overrun. The Horde... they -- they just don't relent.\n\nThere is nothing we can do, {name}. We must find our Shan'do and ask for his guidance. \n\nHe is the only one who can save us.", objectives = "Find Malfurion Stormrage in Darkshore.", completion = "<name>! The tree..." }
WordHunterWoW_QuestEN[52978] = { title = "With Prince in Tow", description = "Let's set sail for Zandalar. In case you hadn't noticed, we've been dealing with a bit of Alliance interference while you were gone.", objectives = "Speak with Dread-Admiral Tattersail to return to Zuldazar.", completion = "Once again, excellent work, <name>." }
WordHunterWoW_QuestEN[52979] = { title = "Ritual Cleansing", description = "", objectives = "" }
WordHunterWoW_QuestEN[52981] = { title = "Killer Queen", description = "Lor'danel is now secure, but something is amiss... there has been no sign of Stormrage. \n\nMalfurion would have never let Lor'danel fall without a fight. He must have gone after her.\n\nMy army has approached from the North, and our reinforcements have arrived from the South -- which means that they are not along any of the roads.\n\nSearch the forest with me, {name}. We will find them and be done with this once and for all.", objectives = "Scour the forest of Darkshore to find the Warchief.", progress = "The Horde endures.", completion = "<The flames cast Sylvanas' face in shadow.>" }
WordHunterWoW_QuestEN[52982] = { title = "Mine or Trouble", description = "", objectives = "" }
WordHunterWoW_QuestEN[52983] = { title = "I Want It All", description = "An elemental born of pure Azerite! I do not know what kind of threat this poses, champion... but please, do take care.", objectives = "Defeat the Azerite Fury." }
WordHunterWoW_QuestEN[52984] = { title = "I Want It All", description = "An elemental... of pure Azerite. Slay it, champion, but do not destroy it. Gather as much of its resin as you can!", objectives = "Defeat the Azerite Fury." }
WordHunterWoW_QuestEN[52986] = { title = "A Wicked Vessel", description = "", objectives = "" }
WordHunterWoW_QuestEN[52987] = { title = "Let's Burn!", description = "", objectives = "" }
WordHunterWoW_QuestEN[52988] = { title = "House Cleaning", description = "", objectives = "" }
WordHunterWoW_QuestEN[52990] = { title = "Return to the Harbor", description = "With the scepter in hand, let us return to the portal.\n\nI believe Stone would agree with me when I say that it is best for us to get away from Kul Tiras for a while.", objectives = "Return to Nathanos Blightcaller in Plunder Harbor.", completion = "it seems your mission was a success. Good." }
WordHunterWoW_QuestEN[52991] = { title = "[REMOVED]", description = "", objectives = "" }
WordHunterWoW_QuestEN[53003] = { title = "A Cycle of Hatred", description = "We have raised new champions for the Horde, established footholds on Kul Tiran soil, and stolen one of their precious artifacts.\n\nWe hold greater power and sway over our enemies than we have before.\n\nSylvanas has great plans for our Horde, {name}. I will allow you the pleasure of reporting our victories to her personally.", objectives = "Report to Sylvanas Windrunner in Orgrimmar.", completion = "<name>. Nathanos has been updating me on your progress throughout your efforts.\n\nThe Alliance, and the Kul Tirans, shall tremble before the might of my Horde." }
WordHunterWoW_QuestEN[53006] = { title = "Mission Report: Grimwatt's Crash", description = "Your followers have sent a report regarding the rescue mission to Grimwatt's Crash.\n\nIt details that the supplies were recovered and the enemies surrounding the crash site have been slain.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", objectives = "Deliver the victory report to Halford Wyrmbane.", progress = "Do you have news regarding the mission to Nazmir?", completion = "It seems the mission to Grimwatt's Crash was a success. Well done, <name>.\n\nI think it will make a fine outpost. I'll send you to oversee the fortifications at once." }
WordHunterWoW_QuestEN[53007] = { title = "Grimwatt's Crash", description = "The rescue that you planned for Grimwatt's Crash in Nazmir was successful. Well done.\n\nI believe we should fortify the crash site and turn it into an outpost.\n\nMake your way to Grimwatt's Crash and establish fortifications there.\n\nGrimwatt's Crash will be an essential outpost in our campaign against the Horde.\n\nFor the Alliance!", objectives = "Claim Grimwatt's Crash for the Alliance.", completion = "The crash site was surrounded when we arrived. It's a good thing we made it in time." }
WordHunterWoW_QuestEN[53008] = { title = "Sage Wisdom", description = "", objectives = "" }
WordHunterWoW_QuestEN[53009] = { title = "Hang On In There", description = "An elemental... of pure Azerite. Slay it, champion, but do not destroy it. Gather as much of its resin as you can!", objectives = "Defeat the Azerite Fury." }
WordHunterWoW_QuestEN[53010] = { title = "No Turning Back", description = "An elemental... of pure Azerite. Slay it, champion, but do not destroy it. Gather as much of its resin as you can!", objectives = "Defeat the Azerite Fury." }
WordHunterWoW_QuestEN[53011] = { title = "A Gently Shaken Gift", description = "", objectives = "This present looks like it has been shaken a few times. The tag on it reads:\n\nTo a very special <race> <class>." }
WordHunterWoW_QuestEN[53012] = { title = "Put Away Your Toys", description = "", objectives = "" }
WordHunterWoW_QuestEN[53025] = { title = "The Culling", description = "", objectives = "" }
WordHunterWoW_QuestEN[53027] = { title = "Edge of Glory", description = "", objectives = "" }
WordHunterWoW_QuestEN[53028] = { title = "A Dying World", description = "Champion. Magni Bronzebeard needs your help.\n\nAzeroth is dying. Before this war, a massive demon called Sargeras stabbed the planet with a sword.\n\nOur planet cries out in pain while the Horde and Alliance fight amongst each other.\n\nMagni Bronzebeard believes you can help heal the planet's wounds.\n\nMeet him in Silithus. He has set up camp where Sargeras's sword impacted our world.", objectives = "Meet Magni Bronzebeard in Silithus, located within Kalimdor.", completion = "Ye made it. We don't have any time tae lose." }
WordHunterWoW_QuestEN[53029] = { title = "A Dying World", description = "While the armies of the Horde and Alliance squabble over a ruined city, our world is dying, <name>.\n\nMagni Bronzebeard, the Speaker of Azeroth, needs you at his encampment in Silithus.\n\nYou must hurry. The area is being overrun by elementals driven mad by Azerite!", objectives = "Meet Magni Bronzebeard in Silithus.", completion = "Ye made it! Good. We don't have any time tae lose." }
WordHunterWoW_QuestEN[53030] = { title = "The World Awaits", description = "When the sign of the emissary shines in the night sky, the stars strengthen existing bonds and forge new ones. Friendship is still not cheaply won, and deeds will prove loyalty, but trust comes more readily during these days. Venture across these lands, and give aid where you may, to prove your worth.", objectives = "Complete 20 World Quests in Kul Tiras, Zandalar, Arathi Highlands, Darkshore, or Nazjatar.", progress = "I foresee that you will win many friends this week.", completion = "Well done, <name>." }
WordHunterWoW_QuestEN[53031] = { title = "The Speaker's Imperative", description = "The world's soul is secure... fer now. I can hear Azeroth again, though her voice is still weak.\n\nThe elementals on the surface above have calmed down. Even using just a fraction of its power, the Heart of Azeroth brought stability tae this place.\n\nYe need tae return tae Orgrimmar and inform yer allies what transpired here. Remind them that no matter what happens in their war, our world must be saved.\n\nWe'll speak again soon, <name>. The battle fer Azeroth has only just begun.", objectives = "Speak with Nathanos Blightcaller in Orgrimmar.", completion = "It would seem you were in the right place at the right time, <name>. This Heart of Azeroth the dwarf gave you may prove useful indeed.\n\nBut the war must remain our sole focus. We can spare no forces to aid Magni on his grand crusade.\n\nThe Alliance will stop at nothing to destroy the Horde. Fortunately, the Dark Lady has a plan to make us stronger." }
WordHunterWoW_QuestEN[53032] = { title = "A Burning Path Through Time", description = "The blazing star shines upon the land, searing the earth and parching the landscape. This star is relentless, malevolent almost. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", objectives = "Complete 5 Timewalking dungeons.", completion = "Ah, <name>, you have returned. An otherworldly air hangs heavy about you." }
WordHunterWoW_QuestEN[53033] = { title = "A Frozen Path Through Time", description = "The chill star shines upon the land with its cold light as even the spirits retreat to the shadows. This star is unlike any other in the skies, sapping warmth and life. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", objectives = "Complete 5 Timewalking dungeons.", completion = "Ah, <name>, you have returned. An otherworldly air hangs heavy about you." }
WordHunterWoW_QuestEN[53034] = { title = "A Shattered Path Through Time", description = "The Destroyer's star shines upon the land with its piercing light as even the spirits retreat to the shadows. This star is unlike any other in the skies, laying bare the weaknesses of even the boldest heroes. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", objectives = "Complete 5 Timewalking dungeons.", progress = "I foresee that you will follow the Destroyer's star, and walk the paths it reveals.", completion = "Ah, <name>, you have returned. An otherworldly air hangs heavy about you." }
WordHunterWoW_QuestEN[53035] = { title = "A Shrouded Path Through Time", description = "The shrouded star flickers upon the land with its intermittent light ushering in an eerie mist upon the land. This star and the mists bring deep shadows to the land hiding its secrets and dangers. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", objectives = "Complete 5 Timewalking dungeons.", progress = "I foresee that you will follow the shrouded star, and walk the paths it reveals.", completion = "Ah, <name>, you have returned. An otherworldly air hangs heavy about you." }
WordHunterWoW_QuestEN[53036] = { title = "A Call to Battle", description = "The favorite star of warlords and generals dominates the sky, offering good fortune to tacticians everywhere. Some say that the battle star hones the instincts of commanders to the point of near-prophecy. If ever you were going to test yourself on the field of battle, now is the time.", objectives = "Win 4 Battleground matches.", completion = "I trust your battles went well. And that's not just a turn of phrase. I know they did. I knew they would." }
WordHunterWoW_QuestEN[53037] = { title = "Emissary of War", description = "When the sign of the warrior shines in the night sky, fortune favors the daring. Powerful foes may yield even greater rewards. Venture deep into caverns and strongholds to prove your worth.", objectives = "Complete 4 dungeons on Mythic difficulty.", progress = "I foresee significant amounts of loot in your future.", completion = "Well done, <name>. I knew you could do it." }
WordHunterWoW_QuestEN[53038] = { title = "The Very Best", description = "This alignment of the stars is truly a strange one, causing the tiniest of creatures to gain unnatural aptitude. None of our sages can explain the phenomenon, but cunning tamers have much to gain, especially by testing their skills against those of their peers.", objectives = "Defeat 5 players through Find Battle with a team of level 25 pets.", progress = "I foresee that you will travel across the land, searching far and wide. It's your destiny.", completion = "Well done, <name>. With courage, you have faced every challenge along the way, and battled every day to claim your rightful place." }
WordHunterWoW_QuestEN[53039] = { title = "The Arena Calls", description = "This alignment of the stars is a dire sign, stirring bloodlust and calling warriors to battle to the death in close quarters. Arena masters turn a tidy profit during these days, likely not understanding why their stands are overflowing. Amidst the excitement, great rewards do await those brave, or foolhardy, enough to venture into the arena....", objectives = "Win 10 Arena Skirmish battles.", progress = "I foresee blood in your future, <name>.", completion = "Well done, <name>. I knew you would do it." }
WordHunterWoW_QuestEN[53040] = { title = "Squall Squelching", description = "", objectives = "" }
WordHunterWoW_QuestEN[53041] = { title = "Sampling the Goods", description = "Bridgeport is a major trade hub for this area. Naturally, Ashvane has offices and workshops here.\n\nCheck around town and see if you can learn anything about this new material and how they're using it.\n\nIf you can lift a sample for us to send back to Boralus, even better.\n\nI gotta stay here and keep an eye on someone.", objectives = "Collect the Chemist's Notes and a Raw Azerite Sample.", progress = "<Flynn side-eyes you while trying his best to look casual.>\n\nYou get what we need?", completion = "Good, I'll hang onto them for now.\n\nI think I've found our next lead." }
WordHunterWoW_QuestEN[53042] = { title = "Stormcaller", description = "", objectives = "" }
WordHunterWoW_QuestEN[53043] = { title = "Mission Report: Vulture's Nest", description = "Your followers have sent a report regarding the mission to capture Vulture's Nest in Vol'dun.\n\nIt details that the mission was a success and that the troops holding the outpost have requested reinforcements.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", objectives = "Deliver the victory report to Halford Wyrmbane.", progress = "Do you have news regarding the mission to Vol'dun?", completion = "It seems the mission to Vulture's Nest was a success. Well done, <name>.\n\nI'll send you to oversee the fortifications at once." }
WordHunterWoW_QuestEN[53044] = { title = "Vulture's Nest", description = "The mission to take Vulture's Nest in Vol'dun was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Vulture's Nest and establish fortifications there.\n\nIt will be an essential outpost in our campaign against the Horde.\n\nFor the Alliance!", objectives = "Claim Vulture's Nest for the Alliance.", completion = "This outpost gives us an ideal vantage point for monitorin' the movements o' the sethrak forces below." }
WordHunterWoW_QuestEN[53045] = { title = "Surveying the Wharf", description = "Thresher's Wharf is a bustling fishing hub just across the delta from Fort Daelin. \n\nIt was also in the direct war path of the naga -- who knows what remains now.\n\nIf you could stop in and check in on its leader, Coxswain Hook, you'd have my gratitude. I must focus on tending to the wounded here and preparing for the naga's next assault.", objectives = "Speak to Coxswain Hook in Thresher's Wharf.", completion = "Ah, just what I needed. A fresh set o' ears to hear a tale or two!" }
WordHunterWoW_QuestEN[53050] = { title = "Deeper Into Kul Tiras", description = "It is time for us to further our hold on Kul Tiras.\n\nReturn to the Banshee's Wail. From there we shall plan our next course of action.", objectives = "Meet with Nathanos Blightcaller on the Banshee's Wail in the Port of Zandalar.", completion = "It is time to establish another foothold, <name>. Are you prepared?" }
WordHunterWoW_QuestEN[53052] = { title = "Deeper Into Zandalar", description = "Our advisors have decided that now is the correct time to further our hold on Zandalar.\n\nReturn to the Wind's Redemption posthaste. We shall leave for new lands immediately.", objectives = "Meet with Halford Wyrmbane on the Wind's Redemption in Boralus Harbor.", completion = "Welcome back, <name>. Let's get to work." }
WordHunterWoW_QuestEN[53053] = { title = "To The Mugambala!", description = "The Rastari have proven to be formidable allies in combat, and reports are coming in that help explain how they've honed their battle prowess. \n\nJe'stry the Untamed has a fighting ring setup at the base of Mount Mugambala that could prove useful for getting ready for war.  We've dispatched our troops to take advantage of these training grounds, go and see what High Warlord Volrath has uncovered.", objectives = "Speak with High Warlord Volrath at The Mugambala.", completion = "Welcome to the Dueler's Guild, <name>." }
WordHunterWoW_QuestEN[53054] = { title = "Dueler's Guild", description = "I figured a war-torn {race} such as your self would find benefit in this Dueler's Guild.  Speak with a nearby Rastari Guard to participate in the carnage.", objectives = "Speak with a nearby Rastari Guard.", completion = "Good luck in The Mugambala, <race>." }
WordHunterWoW_QuestEN[53055] = { title = "Pushing Our Influence", description = "Our scouts have identified a location for a final major foothold in Zandalar.\n\nReturn to the Wind's Redemption so we can ship out.", objectives = "Meet with Halford Wyrmbane on the Wind's Redemption in Boralus Harbor.", completion = "It is time to establish our final major foothold in Zandalar, <name>." }
WordHunterWoW_QuestEN[53056] = { title = "Pushing Our Influence", description = "We have identified a location for a final major foothold in Kul Tiras.\n\nReturn to the Banshee's Wail to discuss our new mission.", objectives = "Meet with Nathanos Blightcaller on the Banshee's Wail in the Port of Zandalar.", completion = "It is time to establish our final major foothold in Kul Tiras." }
WordHunterWoW_QuestEN[53061] = { title = "The Azerite Advantage", description = "{name}, we have received intelligence pointing us toward a reliable source of Azerite.\n\nWe must acquire this precious resource before our enemies in the Horde.\n\nReport to the Wind's Redemption as soon as possible to aid in extraction.", objectives = "Meet with Halford Wyrmbane on the Wind's Redemption in Boralus Harbor.", completion = "We appreciate your timeliness, <name>. We must move quickly." }
WordHunterWoW_QuestEN[53062] = { title = "The Azerite Advantage", description = "We have received intelligence pointing us toward a reliable source of Azerite.\n\nWe must move quickly to acquire these resources for the Horde.\n\nReport to the Banshee's Wail to aid in this urgent mission.", objectives = "Meet with Nathanos Blightcaller on the Banshee's Wail in the Port of Zandalar.", completion = "We cannot waste any time." }
WordHunterWoW_QuestEN[53063] = { title = "A Mission of Unity", description = "You have done much for the Alliance during your time here in Kul Tiras, {name}.\n\nToday we must ask more of you. Return to the Wind's Redemption when you have the chance so that we can discuss.", objectives = "Meet with Halford Wyrmbane on the Wind's Redemption in Boralus Harbor.", progress = "The Alliance needs us to bring our new allies into the fold.", completion = "I have another important mission for you, <name>." }
WordHunterWoW_QuestEN[53064] = { title = "A Mission of Unity", description = "You have undertaken great journeys during your time here in Zandalar.\n\nIt is time for your next mission. Report to the Banshee's Wail.", objectives = "Meet with Nathanos Blightcaller on the Banshee's Wail in the Port of Zandalar.", progress = "We must bring the Zandalari into the Horde.", completion = "Are you prepared for your next mission?" }
WordHunterWoW_QuestEN[53065] = { title = "Operation: Grave Digger", description = "Sylvanas has issued us a mission in Drustvar, where we will find our next target.\n\nReport to the Banshee's Wail immediately.", objectives = "Meet with Nathanos Blightcaller on the Banshee's Wail in the Port of Zandalar.", completion = "Good. You didn't dawdle." }
WordHunterWoW_QuestEN[53066] = { title = "Operation: Water Wise", description = "Rexxar has reported back with news of a new... ally.\n\nReport to the Banshee's Wail for your briefing.", objectives = "Meet with Nathanos Blightcaller on the Banshee's Wail in the Port of Zandalar.", completion = "Get ready to set sail for Stormsong Valley." }
WordHunterWoW_QuestEN[53067] = { title = "Operation: Bottom Feeder", description = "It is time for Zelling to prove his worth to the Horde.\n\nReturn to the Banshee's Wail. Today, we sail out to open waters.", objectives = "Meet with Nathanos Blightcaller on the Banshee's Wail in the Port of Zandalar.", completion = "Interested in some deep sea diving?" }
WordHunterWoW_QuestEN[53068] = { title = "Operation: Hook and Line", description = "Thanks to the help of our new allies, we have devised a plan to extract a powerful tidesage artifact from Boralus.\n\nI have already sent Valentine to get us started.\n\nReport to the Banshee's Wail posthaste.", objectives = "Meet with Nathanos Blightcaller on the Banshee's Wail in the Port of Zandalar.", completion = "I hope you are prepared for some light infiltration, <name>." }
WordHunterWoW_QuestEN[53069] = { title = "Operation: Blood Arrow", description = "We have uncovered the location of a high priority target in Nazmir.\n\nReturn to the Wind's Redemption for your briefing.", objectives = "Meet with Halford Wyrmbane on the Wind's Redemption in Boralus Harbor.", completion = "We return to the harsh lands of Nazmir today, <name>. I hope you are prepared." }
WordHunterWoW_QuestEN[53070] = { title = "Operation: Cutpurse", description = "It is time to reconvene for our next mission, though Shandris and I disagree on what exactly that should entail.\n\nMeet us on the Wind's Redemption.", objectives = "Meet with Halford Wyrmbane on the Wind's Redemption in Boralus Harbor.", completion = "I feel we are close to a conclusion, <name>. Perhaps your presence here will help." }
WordHunterWoW_QuestEN[53071] = { title = "Operation: Gryphon's Claw", description = "SI:7 has procured some interesting intel.\n\nI request your presence on the Wind's Redemption immediately to help decide our next course of action.", objectives = "Meet with Halford Wyrmbane on the Wind's Redemption in Boralus Harbor.", completion = "Thank you for arriving with such haste." }
WordHunterWoW_QuestEN[53072] = { title = "Operation: Heartstrike", description = "We've taken out quite a number of high priority targets, {name}. All thanks to your help.\n\nIt is time to strike directly at the heart of the Zandalari empire.\n\nReport to the Wind's Redemption as soon as you are able. We will get started from there.", objectives = "Meet with Halford Wyrmbane on the Wind's Redemption in Boralus Harbor.", completion = "We're going to need to pull out all the stops on this one." }
WordHunterWoW_QuestEN[53073] = { title = "Hook Point Investigation", description = "I'm sure you've heard the constant sound of battle coming from Hook Point.\n\nWe sent scouts over to find out why the fighting never seems to end, and discovered an unexpected training ground.\n\nDaniel Poole at Hook Point is running some sort of fight circuit near the Tradewind Market. Seek out Grand Marshal Tremblade at our War Headquarters and find out what they've learned.", objectives = "Speak with Grand Marshal Tremblade at Hook Point.", completion = "So you've found the Dueler's Guild, <name>." }
WordHunterWoW_QuestEN[53074] = { title = "Reinforcements", description = "The resources you gather can be used to recruit new troops for the war effort.\n\nReturn to me periodically to issue new recruitment orders for your missions.\n\nIf you have available resources, you should use them now to issue your first recruitment order.\n\nThe war effort rages on even as we speak. We have need of fresh recruits.", objectives = "Speak with Mathias Shaw to issue a recruitment order.", progress = "Have you issued the recruitment order?", completion = "Excellent. Your new recruits will be available for missions once they have finished their training." }
WordHunterWoW_QuestEN[53075] = { title = "Dueler's Guild", description = "I figured a war-torn {race} such as your self would benefit from training in the Dueler's Guild.  Speak with a nearby bouncer to participate in the carnage.", objectives = "Speak with a nearby bouncer.", completion = "Good luck in the Dueler's Guild, <race>." }
WordHunterWoW_QuestEN[53076] = { title = "Foundry Meltdown", description = "", objectives = "" }
WordHunterWoW_QuestEN[53078] = { title = "Treasure in the Tides", description = "", objectives = "Loot 8 Shipwreck Supplies in the Wailing Tideway." }
WordHunterWoW_QuestEN[53079] = { title = "Reinforcements", description = "The resources you gather can be used to recruit new troops for the war effort.\n\nReturn to me periodically to issue new recruitment orders for your missions.\n\nIf you have available resources, you should use them now to issue your first recruitment order.\n\nThe war effort rages on even as we speak. We have need of fresh recruits.", objectives = "Speak with Garona Halforcen to issue a recruitment order.", progress = "Have you issued the recruitment order?", completion = "Good. Your new recruits will be available for missions once they have finished their training." }
WordHunterWoW_QuestEN[53080] = { title = "Bumps in the Road", description = "There's been a disruption in ore deliveries from the mine. A small team of our engineers managed to disable a few of the devices causing all this trouble. \n\nIf you can salvage a few of the parts for me to examine I'm sure I'll be able to craft us a few countermeasures.", objectives = "" }
WordHunterWoW_QuestEN[53081] = { title = "Mission Report: Spare Parts", description = "Your followers have sent a report regarding the mission to collect salvage for Stonefist Watch.\n\nIt details that the mission was a success and the necessary materials have been collected.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "Deliver the victory report to Nathanos Blightcaller.", progress = "Do you have news regarding the mission for Stonefist Watch?", completion = "It seems the mission to gather supplies for Stonefist Watch was a success. Well done, <name>." }
WordHunterWoW_QuestEN[53082] = { title = "Spare Parts", description = "An engineer has been assigned to Stonefist Watch to build a scrapping machine.\n\nThe mission to salvage materials for the machine was a success thanks to your leadership.\n\nMake your way to Stonefist Watch in Tiragarde Sound and meet with Grizvek Gearsnap. He has been overseeing the upgrades for the outpost.", objectives = "Speak with Grizvek Gearsnap.", completion = "This machine here will break anything apart! Go ahead, try it out!" }
WordHunterWoW_QuestEN[53095] = { title = "A Flicker of Hope", description = "Champion, I need your help!\n\nWe must evacuate Darnassus before it burns to ash! Many of the city's structures have already caught fire. Douse the flames and rescue the trapped civilians within!\n\nPlease, do all that you can... we must save as many lives as possible.", objectives = "Evacuate the Citizens of Darnassus." }
WordHunterWoW_QuestEN[53096] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[53097] = { title = "Despondent Ablutions", description = "You return. A surprise. Perhaps there is still hope.\n\nIn victory or defeat, you bear the weight of this place. It hangs on you like a mantle. I see your struggle to bear it.\n\nThere is, perhaps, a way to shrug off this burden. An altar, to the northwest. Built by the tidesages, seeking to wash away the corruption.\n\nOffer yourself to the idol. It will exact a price, as do all things. But in communion you may claw back from the brink.", objectives = "Investigate the Purifying Effigy.", progress = "Find the circle, pierce the veil. Only in oblivion can you find it.", completion = "Your mind has rejected madness, and replaced it with determination. For now." }
WordHunterWoW_QuestEN[53098] = { title = "Champion: Shandris Feathermoon", description = "", objectives = "Champion, it has been an honor to fight by your side. Our battle against the Horde is far from over.\n\nShould you ever need my aid, simply call and I shall be there. Only by working together will we stop Sylvanas." }
WordHunterWoW_QuestEN[53099] = { title = "A Mote of Cosmic Truth", description = "We stand on the brink, you and I. The final act looms over us, casting a terrible shadow.\n\nDeep we plumbed, seeking knowledge of the world. Deeper still we delved, until our fate was inevitable. Minds were shattered, my comrades ran screaming into the night. We are all lost, to that terrible Thing...\n\nNow, the malformed syzygy beckons. Complete the ritual and bring about the end.", objectives = "Defeat the Ascendant Nightmare.", completion = "Victory... foolish and meaningless." }
WordHunterWoW_QuestEN[53100] = { title = "Mission Report: Giant Slaying", description = "Your followers have sent a report regarding the mission at Stonetusk Watch.\n\nIt details that the mission was a success and that one of the ettins is being held captive.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "Deliver the victory report to Nathanos Blightcaller.", progress = "Do you have news regarding the mission for Stonetusk Watch?", completion = "It seems the mission at Stonetusk Watch was a success. Well done, <name>." }
WordHunterWoW_QuestEN[53101] = { title = "Nettin' Ettin", description = "An ettin has been captured by our troops at Stonetusk Watch.\n\nApparently, the creature is being trained to work for the Horde as a beast of burden.\n\nMake your way to Stonetusk Watch in Stormsong Valley and meet with Wyna Breezehorn. She has been training the ettin to do her bidding.", objectives = "Speak with Wyna Breezehorn.", completion = "Ettins aren't as hard to train as you might think. Go ahead and take Donk for a ride. It's okay, he's friendly enough!" }
WordHunterWoW_QuestEN[53102] = { title = "Mission Report: Nature Calls", description = "Your followers have sent a report regarding the mission at Swiftwind Post.\n\nIt details that the mission was a success and the druids there have upgraded their druidic knowledge as a result.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "Deliver the victory report to Nathanos Blightcaller.", progress = "Do you have news regarding the mission for Swiftwind Post?", completion = "It seems the mission at Swiftwind Post was a success. Well done, <name>." }
WordHunterWoW_QuestEN[53103] = { title = "Wicker Magic", description = "It seems that the druids at Swiftwind Post have learned much from the ancient Drust rituals you recovered.\n\nThe druids are now able to offer improved services at the outpost.\n\nMake your way to Swiftwind Post in Drustvar and see what they have to offer.", objectives = "Speak with Toska Eaglehorn.", completion = "We've learned much from the Drust's unique form of nature magic. We now have some special boons to offer you, <name>.\n\nThese blessings of nature are yours whenever you visit." }
WordHunterWoW_QuestEN[53105] = { title = "Misplaced Faith", description = "The air is foul with corruption. It must be dealt with.\n\nThe tidesages were fools, and I a fool to trust them. Belief in their god to perform miracles and deliver us from our folly. Nevertheless, their methods did serve to drive back the foul presence from these cliffs.\n\nA simple censer, loaded with select powders and oils. The vapors produce an effect that expels the miasma, if only for a time.\n\nPerhaps their ineffectual gesticulation will finally serve a purpose.", objectives = "Use the Cleansing Thurible to purge 13 sources of corruption.", completion = "The foul odor is dispersed. Perhaps reality can once more take root in this place." }
WordHunterWoW_QuestEN[53106] = { title = "Censership", description = "", objectives = "" }
WordHunterWoW_QuestEN[53107] = { title = "Plunder and Provisions", description = "", objectives = "" }
WordHunterWoW_QuestEN[53108] = { title = "Iconoclasm", description = "", objectives = "" }
WordHunterWoW_QuestEN[53109] = { title = "House Waycrest", description = "You have done much for my home and the people of Drustvar,\n\nTell your allies that House Waycrest will return to Boralus shortly.", objectives = "Return to Taelia in the Harbormaster's Office in Boralus.", completion = "I cannot believe all that has gone on in Drustvar!\n\nI am thankful that House Waycrest will return." }
WordHunterWoW_QuestEN[53110] = { title = "The High Thornspeaker", description = "My teacher, Ulfar, the High Thornspeaker, must be informed of what's been going on here.\n\nI can't leave just yet. There are too many wounded and we'll need to handle the last few remaining constructs.\n\nYou have proven trustworthy, friend. Take a few of these runic cores to Ulfar for me. \n\nArthur will meet you at the head of the path to Ulfar's den.", objectives = "Take the Runic Power Cores to Ulfar.", progress = "What do you have there, mainlander?", completion = "What do you have here, mainlander? Ah, I see. My students met with much stronger threats than we'd expected.\n\nThank you for helping them." }
WordHunterWoW_QuestEN[53112] = { title = "Azeroth's Tear", description = "", objectives = "What do ye have there?", progress = "What do ye have there?", completion = "By the forge! What ye got there is... truly somethin'. A shard of concentrated agony... our world's torment given form. It hurts me tae even look at it.\n\nYet within all that sadness, there is power, too. We can use its energy to help heal the wound. Maybe even bring Azeroth some solace.\n\nThank ye for bringin' it to me, <name>." }
WordHunterWoW_QuestEN[53113] = { title = "Shimmering Shell", description = "", objectives = "Hello! Can I help you?", progress = "Hello! Can I help you?", completion = "What's that? Oh! It's so pretty! I've never seen a shell like this before!\n\nI could make so many different things from it. Oh, think of the jewelry!\n\nThis is so great, thanks!\n\n<Jena hesitates a moment, then gives you a quick lick on the cheek.>" }
WordHunterWoW_QuestEN[53114] = { title = "Golden Beetle", description = "", objectives = "<Krag'wa's bulbous eyes turn towards you.>", progress = "<Krag'wa's bulbous eyes turn towards you.>", completion = "<Krag'wa's eyes widen as you pull out the beetle. Before you can react, his enormous, sticky tongue whips out and snatches it from your hand. In a moment he has gulped down the prize.>\n\n<Krag'wa settles down onto his belly, emits a satisfied belch, and closes his eyes.>" }
WordHunterWoW_QuestEN[53115] = { title = "Island Flotsam", description = "", objectives = "'Eh richmon. Whatchya be bringin' me?", progress = "'Eh richmon. Whatchya be bringin' me?", completion = "<Jani sniffs the air, smelling your wet garbage.>\n\nYa brought ol' Jani a present! What ya got there? Let me see it.\n\n<Jani begins rooting through the pile of trash you have brought.>\n\nOh, yes, and some of this, mmm, mmmhm, yes, oh that's sticky...\n\n<Jani seems pleased with your offering, and is paying no attention to you any longer.>" }
WordHunterWoW_QuestEN[53116] = { title = "Rusted Horde Insignia", description = "", objectives = "Lok'tar, hero.", progress = "Lok'tar, hero.", completion = "Ah, yes, I see.\n\nThis war will not come without loss, hero. This insignia belonged to a member of the Horde who fell in battle. \n\nIt is the way of war, and yet I cannot help but think of the families of these soldiers. \n\nI will do what I can for them, thank you for bringing this to me." }
WordHunterWoW_QuestEN[53117] = { title = "Rusted Alliance Insignia", description = "", objectives = "Yes, champion?", progress = "Yes, champion?", completion = "This war will not be without casualties, it is a shame that so much must be lost to keep what we hold dear.\n\nThis insignia belonged to an Alliance soldier. I will see if I can determine who, and I will speak with their family, should they have one.\n\nLet me know if you find more of these." }
WordHunterWoW_QuestEN[53118] = { title = "Dented Coin", description = "", objectives = "What do you have to report?", progress = "What do you have to report?", completion = "Heh, what's this? Haven't seen a coin like this in a long time.\n\nUsed to use these around the time of the Second War. Supplies were limited, we needed a way to trade with the locals. They used these coins, and then so did we. \n\nStill smells like cannon powder, too. Ah, that takes me back.\n\nWell, what are you doing still standing there? Dismissed!" }
WordHunterWoW_QuestEN[53119] = { title = "Lost Sea Scroll", description = "", objectives = "Yes? What do you have there?", progress = "Yes? What do you have there?", completion = "Oh my, that scroll is old, even amongst the relics of the sea.\n\nThose that would commune with the waves have existed since long before our written history. Relics of the most ancient tide-speakers have all but disappeared from our world, lost to the deeps that spoke to them.\n\nI will put it in a safe place, thank you for bringing this to me." }
WordHunterWoW_QuestEN[53120] = { title = "Exotic Spices", description = "", objectives = "Oh, hello! Did you have something for me?", progress = "Oh, hello! Did you have something for me?", completion = "Oh wow! I've never seen a mix of spices like that before.\n\nThe traders of the Great Sea make their own exotic spice mixes, each one is unique. I'll happily take them off of your hands if you find any more!\n\nThis one smells great! I can't wait to try it on... fish? No, carrots maybe? Hmm..." }
WordHunterWoW_QuestEN[53121] = { title = "Siege of Boralus", description = "", objectives = "It really is a shame you missed it, <name>. Dwarven gryphon-riders got the jump on us, but I don't think they were counting on us packing so many trained killers onto one boat.\n\nEven Zelling got into the fun!\n\nI found this letter on one of the dwarven corpses. Looks like there's tensions between the Kul Tiran leadership and one of their houses, House Ashvane. This might give us a good opportunity to sow some chaos in Boralus." }
WordHunterWoW_QuestEN[53122] = { title = "A Season for Celebration", description = "Well met, {class}.\n\nHallow's End is a time for celebration and reflection, though some have no idea why. The burning of the Wickerman in particular is a mystery to many outside the Forsaken.\n\nTravel to the Ruins of Lordaeron and speak to Darkcaller Yanka. She can tell you more about the Wickerman ceremony.", objectives = "Speak with Darkcaller Yanka in the Ruins of Lordaeron.", completion = "The Wickerman ceremony is a time honored tradition.  It is good to see the Horde joining us in celebration." }
WordHunterWoW_QuestEN[53125] = { title = "Mission Report: Into The Wicker", description = "Your followers have sent a report regarding the mission at Mudfisher Cove.\n\nIt details that the mission was a success and the druids there have upgraded their druidic knowledge as a result.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "Deliver the victory report to Nathanos Blightcaller.", progress = "Do you have news regarding the mission at Fairwind Post?", completion = "It seems the mission to defend Mudfisher Cove was a success. Well done, <name>." }
WordHunterWoW_QuestEN[53126] = { title = "The Wicker Totem", description = "The defense of Mudfisher Cove was successful. Well done, {name}.\n\nA mysterious totem was found in the aftermath of the battle that may prove useful to you during your adventures in Drustvar.\n\nTravel to Mudfisher Cove in Drustvar and see what power this totem contains.", objectives = "Speak with Garn Blackwolf.", completion = "This totem was recovered in the aftermath of the battle. It seems to resonate with some strange magic. Personally, I don't trust it..." }
WordHunterWoW_QuestEN[53127] = { title = "The Lord Admiral's Lament", description = "The footlocker contains a number of Lord Admiral Daelin Proudmoore's personal effects. Among them is a rolled letter, sealed with sea-green wax and stamped with the Proudmoore crest. The parchment tears easily and requires careful handling and it appears that the ink has been largely washed away by tide and time.\n\nPerhaps someone can restore the letter and reveal its contents.", objectives = "Take the Illegible Correspondence to someone in Orgrimmar.", progress = "What's this?", completion = "There were rumors that Daelin searched for his daughter before his demise. If this letter is what I think it is, this is part of the reason we are at war." }
WordHunterWoW_QuestEN[53128] = { title = "The Lord Admiral's Lament", description = "The footlocker contains a number of Lord Admiral Daelin Proudmoore's personal effects. Among them is a rolled letter, sealed with sea-green wax and stamped with the Proudmoore crest. The parchment tears easily and requires careful handling and it appears that the ink has been largely washed away by tide and time.\n\nPerhaps someone can restore the letter and reveal its contents.", objectives = "Take the Illegible Correspondence to Kayla Mills in Stormwind City.", progress = "What's this?", completion = "I can feel history in this scroll, <name>. If this letter contains what I think it does, it is a sad tale indeed.\n\nNow, let me see..." }
WordHunterWoW_QuestEN[53129] = { title = "Bloodied Sentinel's Glaive", description = "The glaive rests inches from the sentinel's outstretched fingertips. Her eyes stare, sightless, at the ashen husk of Teldrassil on the horizon.\n\nPerhaps someone in Orgrimmar can tell you what happened here.", objectives = "Take the Bloodied Sentinel's Glaive to Isabella in Orgrimmar.", progress = "Yes?", completion = "Ah, yes, I think I know why you have brought this to me, <name>. Sit, allow me to explain." }
WordHunterWoW_QuestEN[53130] = { title = "Bloodied Sentinel's Glaive", description = "The glaive rests inches from the sentinel's outstretched fingertips. Her eyes stare, sightless, at the ashen husk of Teldrassil on the horizon.\n\nPerhaps someone in Stormwind can tell you what happened here.", objectives = "Take the Bloodied Sentinel's Glaive to Kayla Mills in Stormwind City.", progress = "Can I help you?", completion = "Aye, I recognize that look. You have seen Teldrassil, or what is left of it. Have a seat, <name>." }
WordHunterWoW_QuestEN[53131] = { title = "Kings' Rest", description = "", objectives = "The Horde aren't just here on a san'layn shuttling mission. There are lots of high-ranking Horde figures here. Something's going on.\n\nOne perk of dealing with important Horde targets is that they tend to be carrying important information. Look at this map I found on one of the bodies. See the big red circle around \"Kings' Rest\"? What is Kings' Rest? Why don't the Alliance know about this?\n\nWe'll have to look into it as soon as we get back on land." }
WordHunterWoW_QuestEN[53146] = { title = "Boulderfist Beatdown", description = "The Boulderfist ogres have plagued Arathi since the Second War, and they still remain.\n\nYou know what must be done.", objectives = "Kill 20 Boulderfist clan ogres in Arathi Highlands.", progress = "Boulderfist ogres still plague Arathi.", completion = "You have thinned the clan's numbers? Well done." }
WordHunterWoW_QuestEN[53148] = { title = "Boulderfist Beatdown", description = "If the Boulderfist ogres will not join the Horde, there is no place for them in Arathi.\n\nYou know what must be done.", objectives = "Kill 20 Boulderfist clan ogres in Arathi Highlands.", completion = "You have thinned the clan's numbers? Well done." }
WordHunterWoW_QuestEN[53149] = { title = "Wiping Out the Witherbark", description = "The Witherbark tribe has a long and bloody history in the highlands of Arathi.\n\nShow them how much bloodier it can get.", objectives = "Kill 20 Witherbark tribe trolls in Arathi Highlands.", progress = "Witherbark drums still echo across the Highlands.", completion = "Have the trolls been defeated? Well done." }
WordHunterWoW_QuestEN[53150] = { title = "Wiping Out the Witherbark", description = "The bloodthirsty Witherbark tribe has always refused to join the Horde... and now that the Horde holds Arathi, we will succeed where the Alliance has failed.\n\nDrive the forest trolls from the Highlands.", objectives = "Kill 20 Witherbark tribe trolls in Arathi Highlands.", completion = "Have the trolls been defeated? Well done." }
WordHunterWoW_QuestEN[53151] = { title = "Mission Report: Wolves For The Den", description = "Your followers have sent a report regarding the mission at Wolf's Den.\n\nIt details that the mission was a success and that a pack of direwolves now guard the outpost.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", objectives = "Deliver the mission report to Nathanos Blightcaller.", progress = "Do you have news regarding the mission to Tiragarde Sound?", completion = "It seems the mission at Wolf's Den in Tiragarde Sound was a success. Well done, <name>." }
WordHunterWoW_QuestEN[53152] = { title = "Wolves for the Den", description = "The mission at Wolf's Den in Tiragarde Sound was a success. Well done, {name}.\n\nA pack of direwolves now patrols the area surrounding the outpost.\n\nTravel to Wolf's Den and see that the training of the wolves is up to our standard.", objectives = "Speak with Mukkral Blackvein.", completion = "Throm-Ka, <name>. Rexxar has tamed a fine pack of wolves. They will serve the outpost well!" }
WordHunterWoW_QuestEN[53153] = { title = "Death to The Defilers", description = "Even with the destruction of Undercity, the Defilers continue to combat our hold on the Arathi Highlands.\n\nThe farmland at Go'Shek will belong to the Alliance once more. Go, and defeat the Forsaken.", objectives = "Kill 20 Defilers at Go'Shek Farm.", progress = "The Defilers still hold Go'Shek Farm.", completion = "You've driven them off? Well done." }
WordHunterWoW_QuestEN[53154] = { title = "The League Will Lose", description = "Even with the fall of Stromgarde, the League of Arathor continues to operate in the Highlands.\n\nThe northern farmland will belong to the Horde. Go, and defeat the humans.", objectives = "Kill 20 League of Arathor at Dabyrie's Farmstead.", completion = "You've driven them off? Well done." }
WordHunterWoW_QuestEN[53155] = { title = "Notched Coin", description = "<This old, worn coin has clearly changed hands many times. The edges are rusty from years in the salty air of the Great Sea, and it features an unusual design.\n\nYou saw a number of these coins scattered around the island, they appear to be quite commonly used.>", objectives = "Bring the Notched Coin to Mili Wanderbrew in Jade Forest.\n\nProvided item:", completion = "Hello, have you come to sample our new brews?\n\nA coin? Oh, yes, I have seen these before, the island tribes use them.\n\nSometimes they visit us and purchase supplies. They live a very different life than us, always traveling from place to place, never settling down.\n\nWhen one group packs up to move on to a new island, it is not uncommon for another tribe to take their place. On and on they go like this.\n\nWhile you are here, we have be fishing up these strange gems. Can you make use of them?" }
WordHunterWoW_QuestEN[53159] = { title = "Arathi Donations: Coarse Leather", description = "It's time we snuff out the competition, don't you agree? With your help we can ensure our allies receive the necessary goods and armor to prepare for the battle to come.\n\nLet's make sure our allies are well prepared.", objectives = "Donate 60 Coarse Leather to Charlane in Boralus Harbor.", progress = "Should you find any additional leather in your hunt, you know where to find me.", completion = "Quite an offering. Thank you." }
WordHunterWoW_QuestEN[53160] = { title = "Ancient Crypt Key", description = "<A magical device found on the mogu island invaders, it contains no more power.\n\nYou are aware of similar devices that were used to activate ancient titan machinery in the mogu vaults of Pandaria.\n\nThis particular one teems with a foreboding presence.\n\nThe Lorewalkers may know more about this device.>", objectives = "Bring the key to Lorewalker Cho in Vale of Eternal Blossoms.\n\nProvided item:", completion = "Oh, hello my friend. We do not get many visitors here any longer, it is good to see you. \n\nWhat is it you have there?\n\nAh, yes, I see. A rare device of mogu origin. We have seen these before, many years ago.\n\nDuring the Age of a Hundred Kings, the mogu found necromancy. Powerful mogu necro-lords ruled their tribes from crypts dug deep beneath the surface.\n\nMany such crypts remain, unearthed or awoken by the wound in the world, I cannot say which.\n\nOh! And I have something for you, as well. Here." }
WordHunterWoW_QuestEN[53161] = { title = "Ring of the Reefs", description = "<A light mist twists and curls around this ring as if caressing it.\n\nHolding this object makes you uneasy, deep within your soul. It feels as if invisible, icy hands from the lands of the dead are pulling at you.\n\nThere is no mistaking Helya's power.\n\nThe Valarjar will want to hear about this.>", objectives = "Solve the riddle.\n\nProvided item:", completion = "Another ring? Hmph. Yes, we have been seeing them more frequently.\n\n<Valdemar grimaces.>\n\nHelya is growing in power.\n\nWhat, small one, are you surprised? Did you think she was defeated?\n\n<Valdemar laughs heartily.>\n\nYou cannot kill death!\n\nI thank you for making me laugh today, little friend.\n\nOdyn has heard about your search for Azerite, we have gathered what we could. \n\nHere, it is yours." }
WordHunterWoW_QuestEN[53162] = { title = "Sins of the Syndicate", description = "As if the Defilers were not trouble enough, Syndicate agents still slither down from the Alterac mountains to drive off honest Alliance farmers.\n\nPunish them.", objectives = "Kill 20 Syndicate members at Dabyrie's Farmstead.", completion = "The Syndicate has been driven back to Alterac? Well done." }
WordHunterWoW_QuestEN[53163] = { title = "Bloodwake Drinking Horn", description = "<A large drinking horn taken from one of the Bloodwake vrykul.\n\nThe sturdy craftsmanship has allowed it to survive many years of hard travel on the Great Sea.\n\nAs you hold the horn, you remember how fervently the vrykul you encountered were after the Azerite, but to what end?\n\nOther vrykul tribes may know more about the Bloodwake and their motivations.>", objectives = "Bring the horn to the wise Vydhar.\n\nProvided item:", completion = "<Vydhar's leaves shake as you approach.>\n\nI sense a good story approaches, what do you seek? Answers, I know, about the Bloodwake.\n\nThere is a fleet, some say thousands of ships large, that floats on the Great Sea, led by the greatest raider to ever live. His name is Jorun, the Bloodwake.\n\nLong ago he left us to seek a life at sea. He lives only to raid, never in one place for long.\n\nPerhaps you, too will see him one day.\n\nThis old one thanks you for visiting. Take these minerals from my roots." }
WordHunterWoW_QuestEN[53164] = { title = "Sonic Stone", description = "<The stone vibrates to your touch. The frequency resonates throughout your body, and you feel refreshed.\n\nThe mantid likely use these stones to allow them to fly great distances across the sea.\n\nTo see them on the island was strange, the mantid took a heavy blow when Shek'zeer was destroyed, they should not be swarming now.\n\nThe denizens of Pandaria may have more information.>", objectives = "Show the stone to Sentinel Commander Qipan in Townlong Steppes.\n\nProvided item:", completion = "Yes? We are quite busy here, as you can see, what is it?\n\nAh, I see you have also encountered the mantid swarm.\n\nOur fears are realized, the new empress has hatched. Princess Zara, no, now Grand Empress Shek'zara, is here.\n\nShe is as hotheaded and impulsive as mantid queens usually are, and has mobilized most of her forces to search for Azerite.\n\nWe know not why.\n\n<Qipan squishes a nearby bug between his fingers.>\n\nBut we do not like it.\n\nHere, Azerite taken from their corpses, take it." }
WordHunterWoW_QuestEN[53165] = { title = "Stopping Antiquities Theft", description = "", objectives = "" }
WordHunterWoW_QuestEN[53167] = { title = "Icetusk Fur Cloak", description = "<The fur on this cloak is worn and tattered, but it is still warm. It has seen many years in the harsh, unforgiving blizzards of the north.\n\nThe icetusk tribe has not been seen on Azeroth until now, someone in Northrend might know more about them.>", objectives = "Show the fur to Tua'kea in Dragonblight.\n\nProvided item:", completion = "Hello friend, my you smell like strange fish, where have you been? Is that too personal of a question?  No matter, how can this one help you?\n\nAh yes, the Icetusk, a most curious tale of a small tribe.\n\nThey resisted the Lich King's promises and set out on huge canoes to find salvation.\n\nAnd yet, all they found was hardship and despair. In dark times, they turned to necromancy, and thus the tribe has lived on, but only barely. A sad tale.\n\nOh! I fished this up this morning, it is yours if you like." }
WordHunterWoW_QuestEN[53168] = { title = "Magical Spyglass", description = "<This spyglass allows you to see far off into the distance, but looking through it for too long gives you a headache.\n\nThe lens appears to have been specifically crafted for someone else's eyes.\n\nGiven the intricate detail on the spyglass, they'd likely provide a hefty reward for its return.>", objectives = "Return the spyglass.\n\nProvided item:", completion = "Now what do you have there? Oh, oh oh OH, what is this!?\n\nMy spyglass!\n\nOh honey, I never thought I'd see you again. Do you know how expensive this thing was? I had to get the lens custom-made because of my right eye and all.\n\nYou didn't look through it, did you?\n\nListen, I don't tear up often, but I just might this time. It really means the world to me.\n\nHere, all the Azerite I got, its yours. It's... worth a lot... oof. That hurts. You take it though, really. Take it. Go ahead. It's fine." }
WordHunterWoW_QuestEN[53169] = { title = "Elemental Core", description = "<A burned-out core from the elementals you encountered.\n\nWhen you concentrate, you can sense that some elemental energy still exists, deep within the core.\n\nThey were clearly after the Azerite, but why?\n\nIt might be time to call in an old favor.>", objectives = "Bring the core to Duke Hydraxis in Azshara.\n\nProvided item:", completion = "Yes? I am no longer in the business of fire prevention.\n\nOh, you have questions about the elemental planes? They are in quite a state at the moment. Though the elements are always tumultuous, things have gotten quite out of hand.\n\nThe presence of this Azerite has ignited the lesser lords, and each seeks to overthrow the current lords and take the plane for themselves.\n\nThey see this new element as a sign of elemental rebirth.\n\nI do not see this. Here, I do not want even the gems I have, take them." }
WordHunterWoW_QuestEN[53170] = { title = "Unscarred Black Scale", description = "<An utterly pristine black dragon scale taken from the dragons you recently encountered.\n\nThe black dragonflight was completely decimated following Deathwing's demise and Wrathion's rise to power.\n\nYet the size indicates a younger dragon.\n\nThere is one person, one dragon, that you know will want to hear of this, but where IS Wrathion?\n\nYou surmise he may be some place familiar, fortified, and abandoned.>", objectives = "Attempt to find Wrathion in Blackrock Mountain.\n\nProvided item:", completion = "Hello, I was told to expect you. Kindly hand over the scale.\n\nWe will, of course, compensate you.\n\nFirst in information. Have you heard of the Dragon Isles? Few have, and fewer have been there.\n\nWe have not found others of the master's kin... forthcoming in information.\n\nShould you uncover anything further in your travels, we will be awaiting a visit, with payment in kind.\n\nAnd second, in this Azerite you are seeking. Here, a hefty sum for your troubles.\n\nUntil we meet again." }
WordHunterWoW_QuestEN[53171] = { title = "Battered Twilight Scale", description = "<The worn scale of a twilight dragon, it has seen many years of fighting.\n\nThe twilight dragons were thought to have been defeated with the fall of Sinestra, how were there so many on the island?\n\nAnd who is leading the flight?>", objectives = "Solve the riddle.\n\nProvided item:", completion = "Shh! Step back! We can't let them see us!\n\nWhat are you doing here? Who sent you?\n\n<Eryna listens as you explain the twilight attack.>\n\nYes, we know. It's those damn stone troggs, nothing stops their digging! They dug far deeper and further than we thought possible.\n\nWhat's more, when I really concentrate, I can feel the heartbeat of thousands of tiny creatures in there. We have no idea how many more eggs remain...\n\nSince you're out here, one of them had these gems on them, take them." }
WordHunterWoW_QuestEN[53172] = { title = "Venture Co. Business Plan", description = "<An enormous volume, and printed in very small print. You can't make it through even a few sentences before the words begin to swim before your eyes.\n\nThe Venture Company's long-term plan appears to be quite complex and nearly impossible to understand.\n\nOne thing is for certain: a competing enterprise would likely pay well to get their hands on this tome.>", objectives = "Confront Lizzarik in Ratchet.\n\nProvided item:", completion = "Yeah? What do ya got there? Oh.\n\nListen, my name's on the back of that thing because I'm what you call an \"investor.\" I put money into a bet that the company's going to succeed or not.\n\nIt's all a little complicated, so don't worry your pretty little head. I didn't do anything wrong, technically! We're just leveraging some existing infrastructure to make a little gold.\n\nIt's harmless.\n\nHey, look, I've got a huge bag of Azerite right here! Why don't you take it with you? Too heavy for me, really." }
WordHunterWoW_QuestEN[53173] = { title = "Sins of the Syndicate", description = "As if the League of Arathor was not trouble enough, Syndicate agents still slither down from the Alterac mountains to drive off honest Horde laborers.\n\nPunish them.", objectives = "Kill 20 Syndicate members at Go'Shek Farm.", completion = "The Syndicate has been driven back to Alterac? Well done." }
WordHunterWoW_QuestEN[53174] = { title = "Murloc Eye", description = "<The murloc eye appears to have no magical properties of its own, but is still quite damp to the touch.\n\nYou have seen naga sorcerers use similar objects in their casting rituals, but rarely do they dismember their murloc slaves for this purpose.\n\nThis is unsettling, even for the naga.>", objectives = "Solve the riddle.\n\nProvided item:", completion = "Oh, hello, are you here about the terrible things happening to the murlocs?\n\nI've been hearing tales of terrifying magical experiments happening in the depths, entire murloc tribes being wiped out.\n\nThere is one area that they won't even go near anymore, the water bubbles ferociously and the heat is unbearable. The fish have all fled, everything has fled, what could be going on there?\n\nOh! They've been bringing me some of this Azerite, I'm not sure why. Do you want it?\n\nThanks for visiting!" }
WordHunterWoW_QuestEN[53175] = { title = "The Warfront Looms", description = "We cannot myopically focus all our efforts on Zandalar. Horde treachery simmers all across the globe.\n\nOne particular hot spot lies in the Arathi Highlands, near the storied citadel of Stromgarde. The Horde has set up an encampment nearby, and intends to capture our territory.\n\nSpeak with Ralston Karn, the recruitment officer for the division in charge of this particular warfront. He could use a good {class} like you.", objectives = "Report to Ralston Karn in Boralus Harbor.", completion = "You're <name>, with the 7th Legion?\n\nWelcome. We've heard about you. Let's get to work." }
WordHunterWoW_QuestEN[53176] = { title = "Glittering Scarab", description = "<A magical trinket found on a tol'vir spellcaster, it appears to augment their casting abilities.\n\nIt seems to be very old, but is nearly pristine in form. \n\nThe tol'vir of Uldum may know more about the sudden appearance of the Amathet.>", objectives = "Bring the scarab to High Commander Kamses in Uldum.\n\nProvided item:", completion = "<The scarab catches Kamses' eye.>\n\nI see you have met the Amathet.\n\nThe wound in the world has unearthed new tombs, and from one they emerged. \n\nThey speak little to us, believing us betrayers of our sacred duties. They believe that they, stewards of the titans, should control the Azerite.\n\nWorse, when they realized that Rajh and the others were slain, they constructed their own, new keepers.\n\nThey must have an active forge.\n\nI will give you what Azerite we have, be careful, they are dangerous." }
WordHunterWoW_QuestEN[53177] = { title = "Broken Compass", description = "<A compass found on a stranded pirate, it no longer functions. \n\nThe metal and craftsmanship indicate an origin in Stormwind.>", objectives = "Find the owner of the compass.\n\nProvided item:", completion = "Hello, are you here to buy herbs?\n\nOh, what's that, a compass? It certainly looks familiar.\n\nThat idiot.\n\nHe was always seeking his fortune somewhere and never finding it. Completely useless here at home, too. Couldn't keep an herb alive to save his life.\n\nYou know what? I'm glad he's lost at sea. Leave him there.\n\nHere, I'll even give you his stash of Azerite, he would hate that.\n\nFinally free to pursue my own interests, now that's a breath of fresh air. I wonder if Kirsty's still available..." }
WordHunterWoW_QuestEN[53178] = { title = "Razorfin Hunting Spear", description = "<This spear is razor sharp, though it has clearly seen many years of hunting in the open sea.\n\nThe shaft has been broken in several places and repaired with what materials were available at the time. From the variety of repair materials, you surmise that the jinyu tribe you recently faced must travel extensively.\n\nThe friendly jinyu of Pandaria might know more about this strange tribe.>", objectives = "Take the spear to Tired Shushen in Krasarang Wilds.\n\nProvided item:", completion = "Ah, yes, I do recognize this spear. You have encountered the Razorfin, then?\n\nThey are unique amongst Jinyu. Long ago the elder of the tribe was granted a vision of a great beast. So terrified was he that he named it \"Onoho,\" or \"Deep Shadow.\"\n\nHe dedicated his tribe to slaying the beast. They travel from island to island, never staying for long, in their endless quest. It is fascinating.\n\nI thank you for your visit. Some Azerite has washed ashore here, please take it, we have little use for it." }
WordHunterWoW_QuestEN[53179] = { title = "Executing Exorcisms", description = "Even in death, the Horde foolishly clings to Alliance territory.\n\nDrive their vengeful ghosts from the ruins of Ar'gorok before their foulness spreads.", objectives = "Kill 20 Vengeful Ghosts in Ar'gorok.", progress = "Vengeful ghosts remain in Ar'gorok.", completion = "You've cleared the ruins of ghosts? Well done." }
WordHunterWoW_QuestEN[53180] = { title = "Vorus'arak's Carapace", description = "<The carapace from the nerubian lord Vorus'arak, it looks ancient.\n\nIt appears that Vorus'arak did not want to shed his shell, and instead wore the same scarred carapace for a very long time.\n\nAll across the carapace, strange markings have been carved. It seems to be a language of some kind.>", objectives = "Bring the carapace to Kilix the Unraveler in Dragonblight.\n\nProvided item:", completion = "What is this? A carapace? Yes, I see, this writing is in my language. \n\nIt speaks of the swarm lord Vorus'arak, he has written of his journeys on his own chitin.\n\nHe tells of the War of the Spider, of his escape through the tunnels with his brood.\n\nVorus was a powerful digger, yet even his great strength flagged, and he was forced to consume much of his own young.\n\nIn the end, they found an island, and survived. Until you arrived.\n\nOur history is important to us, here are some gems for your time." }
WordHunterWoW_QuestEN[53181] = { title = "Druidic Fur", description = "<This fur teems with natural magic. The beasts you fought on the island were clearly not beasts at all, but druids.\n\nAt least they were before.\n\nWhat could have caused them to become feral?\n\nYou did not want to slay them, but they gave you no choice, didn't they?>", objectives = "Bring the fur to Loganaar in Moonglade.\n\nProvided item:", completion = "This fur... has not seem a change in form in quite some time. \n\nYou encountered my kin gone feral, I surmise? That... makes sense.\n\nFollowing the War of the Satyr, there were those among us that thought that the Pack was the only true way. That we were, at our core, wild creatures, and our humanoid forms are merely a guise.\n\nAs a flock they took wing and left us, never to be heard from again. Until now.\n\nI thank you for this information, here is some Azerite I have collected for the Speaker." }
WordHunterWoW_QuestEN[53182] = { title = "Strangling Root", description = "<The root twists and struggles in your grip, attempting to wrap itself around your arm.\n\nThe keepers you encountered must be powerfully attuned to nature to imbue their creations with such longetivity.\n\nRemembering the ferocity with which they fought against you makes you suddenly uneasy.\n\nWhy would these guardians of nature behave this way?\n\nSurely, someone must have the answers.>", objectives = "Take the root to Keeper Remulos in Moonglade.\n\nProvided item:", completion = "This root tells me all that I need to know of your voyage: an island, teeming with the life spirit, and you met keepers there. \n\nI sense you are surprised at their actions.\n\nNot all of us that guard the natural world see your kind as allies. There are many of my kind that seek to preserve the balance above all things. Even if that means your death.\n\nI will not fault you for defending yourself, but I am powerless to subdue them as well.\n\nHowever, my fawns have gathered some Azerite for you." }
WordHunterWoW_QuestEN[53183] = { title = "Wriggling Mass", description = "<The tendril writhes and pulsates in your hand as your mind is assailed by all manner of vicious thoughts.\n\nOne vision in particular surfaces in your mind again and again.\n\nIn your mind's eye, you picture a many-eyed goat laying in a pool of black water. As you approach, its eyes burst open, and in an instant you find yourself looking upward at the goat from deep within the puddle.\n\nAs you sink into the icy darkness, everything goes black.\n\nYou pocket the mass and shake the thoughts from your head.", objectives = "Locate someone who can explain the visions.\n\nProvided item:", completion = "Please, lower your weapon, I mean you no harm. The whispers ceased speaking to me on the day that the wound opened. \n\nI wish to spend my days atoning for what I have done in my life, perhaps I can help you.\n\nYou... I can see it in your eyes, you have seen the vision. \n\nThe goat, the pool, drowning in the icy blackness, does this sound familiar?\n\nI can tell you its meaning. It means we are fast closing in on the end of this world, friend.\n\nTake my Azerite, I have no need of it any longer." }
WordHunterWoW_QuestEN[53184] = { title = "Weathered Pamphlet", description = "<This pamphlet appears to be a mass-produced flier advertising an Azerite-buying service.\n\nYou can make out a few faded but colorful phrases like \"Your fortune awaits in the Great Sea!\" and \"Everyone's getting rich, isn't it your time?\" \n\nThere is no mention of any of the dangers involved.\n\nThere is some information about who to contact at the bottom, however.>", objectives = "Find the pamphlet's originator.\n\nProvided item:", completion = "Are you here about the pamphlet? \n\nWhat's wrong, expecting someone greener? Listen, we've all got to eat. I've got a family at home, and this war's taking all of the food away.\n\nNot my problem if some amateur adventurers with gold in their eyes get in a little trouble? That sounds more like your problem.\n\nNow if you're not going to sell me your Azerite, buzz off. Big G doesn't like it when I talk too much.\n\nUh, did I say G? Pretend I didn't.\n\nHere, just take some of my Azerite and keep quiet, ok?" }
WordHunterWoW_QuestEN[53185] = { title = "Warfront Contribution", description = "A well-trained army will only get us so far, {name}. We also need money, food, and supplies to keep our army funded, fed, and ready to fight.\n\nAlliance coffers fund most of the war effort, but the rest is paid for by the hard work of citizens like you and me. Loosen up those purse strings and do what you can. For the Alliance!", objectives = "Make a donation to the war effort. You can donate gold, War Resources, or crafted equipment. Only some NPCs will accept donations each day.", completion = "The Alliance appreciates your generosity, <name>. You've pushed us that much closer to victory!" }
WordHunterWoW_QuestEN[53186] = { title = "Mission Report: Ambush at Grimwatt's Crash", description = "Your followers have sent a report regarding the mission at Grimwatt''s Crash.\n\nIt details that the mission was a success and the attacking blood trolls were defeated.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", objectives = "Deliver the mission report to Halford Wyrmbane.", progress = "Do you have news regarding the mission for Grimwatt's Crash?", completion = "It seems the mission at Grimwatt's Crash was a success. Well done, <name>." }
WordHunterWoW_QuestEN[53187] = { title = "An Unexpected Guest", description = "The mission to defend Grimwatt's Crash was a success. Well done, {name}.\n\nIn addition to successfully holding the outpost, the troops at Grimwatt's Crash have captured a blood crawg. Noella Davenport is handling the beast's training.\n\nMake your way to Grimwatt's Crash in Nazmir and check-in with Noella on the crawg training.", objectives = "Speak with Noella Davenport.", completion = "Blood crawgs aren't as difficult to train as long as you might think. See for yourself and take \"Spud\" here for a ride!" }
WordHunterWoW_QuestEN[53188] = { title = "Frozen Freestyle", description = "", objectives = "" }
WordHunterWoW_QuestEN[53189] = { title = "Slippery Slopes", description = "", objectives = "" }
WordHunterWoW_QuestEN[53190] = { title = "Executing Exorcisms", description = "Even in death, the Alliance foolishly clings to Horde territory.\n\nDrive their vengeful ghosts from the ruins of Stromgarde before their foulness spreads.", objectives = "Kill 20 Vengeful Ghosts in Stromgarde.", progress = "Vengeful ghosts remain in Stromgarde.", completion = "You've cleared the ruins of ghosts? Well done." }
WordHunterWoW_QuestEN[53192] = { title = "Twice-Exiled", description = "Elementals of all sorts are bursting free of their bonds across the Highlands.\n\nReturn them to the primordial chaos from whence they came.", objectives = "Kill 20 Burning, Cresting, Rumbling, or Thundering Exiles or Guardians in Arathi Highlands.", completion = "The elementals have been banished? Well done." }
WordHunterWoW_QuestEN[53193] = { title = "Twice-Exiled", description = "Elementals of all sorts are bursting free of their bonds across the Highlands.\n\nReturn them to the primordial chaos from whence they came.", objectives = "Kill 20 Burning, Cresting, Rumbling, or Thundering Exiles or Guardians in Arathi Highlands.", progress = "Hostile elementals still befoul the Highlands.", completion = "The elementals have been banished? Well done." }
WordHunterWoW_QuestEN[53194] = { title = "To the Front", description = "I need you to see the Arathi Highlands. The battle has died down for now, but when it flares up again, we'll need you on the front.\n\nYvera Dawnwing maintains a portal directly to Stromgarde. She can help you.", objectives = "Speak with Yvera Dawnwing to teleport to Stromgarde, then report to Captain Roderick Brewston.", completion = "Terrible business, war is. Really.\n\nGlad you could make it, soldier. Let's make this quick." }
WordHunterWoW_QuestEN[53195] = { title = "Arathi Donations: Akunda's Bite", description = "Greetings!\n\nWith the war effort in full swing I'll be your point of contact for herbalism and alchemical donations! It's a pleasure to meet you!\n\nNow, let's see here... Ah, yes. Siren's Pollen. It appears our stockpiles reported a shortage as of late last night. It would be a great help to us all if you were able to donate to our efforts.", objectives = "Gather 20 Siren's Pollen for Chelsea Strand in Boralus Harbor.", progress = "Have some herbs for me?", completion = "The scent of these herbs is unmistakable.\n\nI'll make sure they're put to good use." }
WordHunterWoW_QuestEN[53196] = { title = "Swab This!", description = "", objectives = "" }
WordHunterWoW_QuestEN[53197] = { title = "Touring the Front", description = "The Horde haven't attacked for a while now. Neither have we, honestly. It should be safe to head on out and do some scouting.\n\nCheck in with our foremen at the mine and the lumber mill. It'd be good to know that they haven't off and gotten themselves killed, and the trip should give you a bit of a lay of the land.\n\nSpeaking of which, you might also talk to Grayson Bell, the flight master, who can give you a quick look at our enemy's base. \"Ar'gorok,\" or some other such orcish nonsense.", objectives = "Report to Foreman Tully, Lumbering Leo, and Grayson Bell.", progress = "Cheers!", completion = "Nobody's been slaughtered by the Horde, then? Excellent.\n\nGlad you could make it back safely too, <name>." }
WordHunterWoW_QuestEN[53198] = { title = "Back to Boralus", description = "That should just about do it for now, then. We'll be in touch if the fighting heats back up again. No doubt it'll be any day now.", objectives = "Speak with Yvera Dawnwing to return to Boralus.", completion = "You're all caught up? Excellent.\n\nHolding a firm line in Arathi is critical to the Alliance's continued occupation of Lordaeron. We appreciate your support, both now and in the inevitable upcoming battle." }
WordHunterWoW_QuestEN[53199] = { title = "The Torcanata", description = "", objectives = "" }
WordHunterWoW_QuestEN[53205] = { title = "Arathi Donations: Monelite Ore", description = "Ye look like the kind o' <lad/lass> that ought ta be carryin' loads o' ore around with ya! If my assumption is right about ye, we could use yer help to gather a bit more ore for the war effort.\n\nHave ye any ore ta spare?", objectives = "Gather 20 Monelite Ore to Brandal Darkbeard in Boralus Harbor.", progress = "Ye look like the kind o' lad that ought ta be carryin' loads o' ore around with ye!\n\nGot any ta spare?", completion = "Ah hah! I knew you were the type!\n\nI could tell by the way yer breeches were saggin' a bit low." }
WordHunterWoW_QuestEN[53207] = { title = "The Warfront Looms", description = "Our focus must expand beyond Kul Tiras. The Alliance still presses against our forces in other parts of the globe.\n\nWe are most interested in the Arathi Highlands, near Stromgarde. We've set up an encampment in the area, with the intent of capturing Stromgarde.\n\nSpeak with Throk, the recruitment officer for the division in charge of this particular warfront. He could use a good {class} like you.", objectives = "Report to Throk in Zuldazar.", completion = "You're <name>, with the Honorbound?\n\nWelcome. We've heard about you. Let's get to work." }
WordHunterWoW_QuestEN[53208] = { title = "To the Front", description = "We're at war in the Arathi Highlands. The battle has died down for now, but when it flares up again, we'll need you on the front.\n\nDruza Netherfang maintains a portal directly to Ar'gorok. She can help you.", objectives = "Speak with Druza Netherfang to teleport to Ar'gorok, then report to Wistel Silversnitch.", completion = "War. It would be horrible if it weren't for all the amazing profit opportunities.\n\nYou're <name>, right? Let's get started." }
WordHunterWoW_QuestEN[53209] = { title = "Warfront Contribution", description = "A well-trained army will only get us so far, {name}. We also need money, food, and supplies to keep our army funded, fed, and ready to fight.\n\nShow some pride and give what you can. For the Horde!", objectives = "Make a donation to the war effort. You can donate gold, War Resources, or crafted equipment. Only some NPCs will accept donations each day.", completion = "Lok'tar ogar!" }
WordHunterWoW_QuestEN[53210] = { title = "Touring the Front", description = "The Alliance haven't attacked for a while now. Neither have we, actually. It should be safe to head on out and do some scouting.\n\nCheck in with our foremen at the mine and the lumber mill. It'd be good to know that they haven't gone and gotten themselves killed, and the trip should give you a bit of a lay of the land.\n\nSpeaking of which, you might also talk to Flightgineer Krazzle. He can give you a quick look at Stromgarde, so you can see what we're up against.", objectives = "Report to Foreman Drogg, Graul, and Flightgineer Krazzle.", progress = "Hey hey.", completion = "You're back from your tour? And nobody's been slaughtered by the Alliance? Nice.\n\nGlad you could make it back safely too, <name>." }
WordHunterWoW_QuestEN[53211] = { title = "Arathi Donations: Coastal Healing Potion", description = "I've received word our allies are looking to stash away a few supplementary items for the battle to come. If you happen to stumble across a few Coastal Healing Potions I'd be more than happy to add them to our stores.", objectives = "Gather 10 Coastal Healing Potions for Chelsea Strand in Boralus Harbor.", progress = "I don't suppose you have any healing potions to spare.\n\nI'm trying to maintain a healthy supply for the battle to come.", completion = "Oh, no...\n\n<Chelsea catches a falling potion in the palm of her hand before it hits the ground.>\n\nThat was a close one!\n\nThese wouldn't be very helpful if I dropped them, now would they?\n\nThanks again, <name>." }
WordHunterWoW_QuestEN[53212] = { title = "Back to Zuldazar", description = "That should just about do it for now, then. We'll be in touch if the fighting heats back up again. Should be any day now, honestly.", objectives = "Speak with Druza Netherfang to return to Zuldazar.", completion = "Welcome back.\n\nWe need to hold that line in Arathi, <name>. We'll be calling on you to help us out when the time comes." }
WordHunterWoW_QuestEN[53213] = { title = "Arathi Donations: Coastal Mana Potion", description = "One of our latest shipments of alchemical supplies was raided en route to storage. We're scrambling to get our stock back on track, but I'm worried we won't make our quota.\n\nYou wouldn't happen to know where one can acquire additional mana potions, would you?", objectives = "Bring 10 Coastal Mana Potions to Chelsea Strand in Boralus Harbor.", progress = "I'm looking to acquire a few potions to sustain our allies in a long-fought battle. Have anything of the kind?", completion = "This is just what I was looking for." }
WordHunterWoW_QuestEN[53216] = { title = "Arathi Donations: Shimmerscale", description = "I'll keep it simple: we need more Shimmerscale!\n\nI apologize for being so forward with you, but there's little time to waste.\n\nIf you happen upon this item throughout your travels I'd be more than happy to put it to good use. Outfitting our allies is of the utmost importance in the battle to come, don't you agree?", objectives = "Donate 100 Shimmerscale to Charlane in Boralus Harbor.", progress = "Outfitting our allies is of the utmost importance. This provides us the necessary materials to ensure no one is left unprotected on the battlefield.", completion = "With your help, our stockpiles will be well supplied in no time!" }
WordHunterWoW_QuestEN[53217] = { title = "Arathi Donations: Coarse Leather Barding", description = "It's not just our allies we need to protect in the upcoming battle, but our equine friends as well!\n\nCan you lend a hand and ensure our allies receive the best possible armor for the battle ahead?", objectives = "Gather 5 Coarse Leather Barding for Charlane in Boralus Harbor.", progress = "It's not just our allies needing protection in the battle to come, but our beasts as well.", completion = "These ensure our riders and beasts are well prepared." }
WordHunterWoW_QuestEN[53218] = { title = "Arathi Donations: Monel-Hardened Hoofplates", description = "Battles aren't decided by which side has the best armor, or the sharpest blades, but it sure does help! Matter o' fact is it's not just ye allies needin' help, but our beasts of battle as well.\n\nIf ye can provide any additional hoofplates fer our brave beasts I'll be sure ta have our farriers take good care of 'em.", objectives = "Gather 2 Monel-Hardened Hoofplates for Brandal Darkbeard in Boralus Harbor.", progress = "Battles aren't decided by which side has the best armor, or the sharpest blades, but it sure does help! Matter o' fact is it's not just ye allies who're needin' help, but our beasts of battle as well.\n\nIf ye can provide any additional hoofplates fer our brave beasts I'll be sure ta have our farriers take good care of 'em.", completion = "Quite generous of ye, <name>. I'll be sure they're put ta good use." }
WordHunterWoW_QuestEN[53219] = { title = "Arathi Donations: Monel-Hardened Stirrups", description = "In times like this it's important ta be ready fer battle at a moments notice. Outfittin' our beasts with proper stirrups is a step in the right direction.\n\nIf yer able ta bring me a few I'll be sure they're put ta good use.", objectives = "Gather 2 Monel-Hardened Stirrups for Brandal Darkbeard in Boralus Harbor.", progress = "In times like this it's important ta be ready fer battle at a moments notice. Outfittin' our beasts with proper stirrups is a step in the right direction.\n\nIf yer able ta bring me a few I'll be sure they're put ta good use.", completion = "Excellent work, lad.\n\nI'll get these ta our riders right away." }
WordHunterWoW_QuestEN[53221] = { title = "Mission Report: Missing Supplies", description = "Your followers have sent a report regarding the mission at Vulture's Nest.\n\nIt details that the mission was a success and the lost supply shipment has been recovered.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", objectives = "Deliver the mission report to Halford Wyrmbane.", progress = "Do you have news regarding the mission for Vulture's Nest?", completion = "It seems the mission to recover the supplies was a success. Well done, <name>." }
WordHunterWoW_QuestEN[53222] = { title = "Necessary Supplies", description = "The mission to recover the supplies was a success. Well done, {name}.\n\nThe supply shipment in question was ordered by Buzz Crankchug at Vulture's Nest. You should check in with the outpost in Vol'dun and ensure that all of the missing supplies have been accounted for.\n\nMake your way to Vulture's Nest in Vol'dun and speak with Buzz Crankchug.", objectives = "Speak with Buzz Crankchug.", completion = "Good to see you, <name>! Without your help we would have lost the kegs I ordered! Help yourself to all you can drink, let the brew flow forth!" }
WordHunterWoW_QuestEN[53223] = { title = "Arathi Donations: Grilled Catfish", description = "Greetings, traveler.\n\nI was asked to ensure our food supplies are never left wanting and our fish supplies have been running low lately. Have anything you would care to donate?", objectives = "Gather 5 Grilled Catfish for Senedras in Boralus Harbor.", progress = "I was asked to ensure our food supplies are never left wanting, though lately our fish supplies have been running low.\n\nHave any fish you would care to donate?", completion = "This will do just fine. I'll be sure our allies are well fed before the battle begins." }
WordHunterWoW_QuestEN[53224] = { title = "Arathi Donations: Seasoned Loins", description = "A nice, hearty meat provides the nourishment our allies deserve before shipping off to battle, not to mention it also makes quite a stew, something our troops seem to rather enjoy when the winds are at their best and the chill of night lingers in the air.\n\nIf you bring me some freshly seasoned loins I would be more than happy to deliver it to our supply officers.", objectives = "Gather 20 Seasoned Loins for Senedras in Boralus Harbor.", progress = "A hearty meat provides the nourishment our allies deserve.\n\nIf you bring me some freshly seasoned loins I would be more than happy to deliver it to our supply officers.", completion = "I'll get these to our supply officers right away." }
WordHunterWoW_QuestEN[53225] = { title = "Arathi Donations: Great Sea Catfish", description = "Fish--it's what's for dinner! Or so say our supply officers. And this weeks meals are based around one delicious ingredient--catfish.\n\nIf we're going to keep our allies well fed and full of fish we'll need to gather more stock and begin meal preparations soon. \n\nIf you find yourself swimming in an abundance of catfish I'd be happy to send them along to our stores.", objectives = "Gather 40 Great Sea Catfish for Senedras in Boralus Harbor.", progress = "If we're going to keep our allies well fed and full of fish, we'll need to make sure our stockpile is ready.\n\nIf you find yourself swimming in an abundance of catfish I'd be happy to send them along to our stores.", completion = "Looks like the great fish feast continues.\n\nOur allies will be delighted." }
WordHunterWoW_QuestEN[53226] = { title = "Arathi Donations: Tidespray Linen", description = "", objectives = "Gather 40 Tidespray Linen for Faella in Boralus Harbor.", progress = "There is no such thing as too much linen. It is better to maintain a strong supply than be left wanting.", completion = "How thoughtful of you." }
WordHunterWoW_QuestEN[53227] = { title = "Arathi Donations: Battle Flag: Spirit of Freedom", description = "", objectives = "Gather 2 Battle Flag: Spirit of Freedom for Faella in Boralus Harbor.", progress = "I have a keen eye for quality when it comes to handcrafted items. I'm looking for one item in particular that may be of use to us on the field of battle.", completion = "Splendid work, <name>. Absolutely beautiful." }
WordHunterWoW_QuestEN[53228] = { title = "Arathi Donations: Battle Flag: Phalanx Defense", description = "", objectives = "Gather 2 Battle Flag: Phalanx Defense for Faella in Boralus Harbor.", progress = "Threading and craftsmanship are not all that matter. Our work speaks to the heart of our dedication, providing a beacon of hope on the field of battle.\n\nI am looking for such an item, one that is crafted by a highly skilled tailor. Have you seen anything of the sort?", completion = "What beautiful craftsmanship. I could spend hours looking this over, though I must continue with our preparations.\n\nThank you for this." }
WordHunterWoW_QuestEN[53229] = { title = "Arathi Donations: Enchant Ring - Seal of Critical Strike", description = "", objectives = "Gather 2 Enchant Ring - Seal of Critical Strike for Mae Wagglewand in Boralus Harbor.", progress = "I was just about done filling orders for the next shipment then realized I was out of materials!\n\nDo you think you can help me fill the remaining orders?", completion = "Thanks for helping keep things on track. Where would we be without generous people like you?" }
WordHunterWoW_QuestEN[53230] = { title = "Arathi Donations: Enchant Ring - Seal of Versatility", description = "", objectives = "Gather 2 Enchant Ring - Seal of Versatility for Mae Wagglewand in Boralus Harbor.", progress = "I know it's short notice, but I'm trying to find a few more enchantments to add to our next shipment.", completion = "Nice work! Ya know, you're the reason we're able to prepare so quickly.\n\nThanks a bunch!" }
WordHunterWoW_QuestEN[53231] = { title = "Arathi Donations: Gloom Dust", description = "", objectives = "Gather 20 Enchant Weapon - Stalwart Navigation for Mae Wagglewand in Boralus Harbor.", progress = "I've been able to keep pace with our orders until recently. Now I'm afraid I won't be able to keep up without help.\n\nWould you be willing to donate a few supplies?", completion = "Wow! I knew I could count on you." }
WordHunterWoW_QuestEN[53232] = { title = "Arathi Donations: Incendiary Ammunition", description = "Though our ammunition stockpiles are faring well, it's my duty to find additional resources, especially those that are harder to come by.\n\nToday I'm looking for a specific type of ammunition, one with incendiary properties. I could really use your help tracking a few of these down.", objectives = "Gather 2 Incendiary Ammunition for Norber Togglesprocket in Boralus Harbor.", progress = "Though our ammunition supplies are faring well, it's my duty to maintain a stockpile of additional resources, especially those that are harder to come by.\n\nWould you let me know if you stumble upon munitions with incendiary properties?", completion = "I'll be sure to handle these with care." }
WordHunterWoW_QuestEN[53233] = { title = "Arathi Donations: Frost-Laced Ammunition", description = "Hey there!\n\nTransmission's come down from up top--we need more ammunition! Something with a bit more kick. Something really unexpected!\n\nFrom what I've heard there's a special frost-based ammunition crafted only by the most experienced engineers. If you were to bring me a few I'm sure our munitions officers would be ecstatic!\n\nMaybe they'd even let me keep one to examine!", objectives = "Gather 2 Frost-Laced Ammunition for Norber Togglesprocket in Boralus Harbor.", progress = "I've heard there's a special frost-based ammunition crafted only by the most experienced engineers. If you were to bring me a few of these I'm sure our munitions officers would be ecstatic!", completion = "Wow! These are magnificent! The craftsmanship alone is... \n\nApologies, I get carried away sometimes.\n\nTake care!" }
WordHunterWoW_QuestEN[53234] = { title = "Arathi Donations: F.R.I.E.D.", description = "You never know when you'll need to deliver a big bang on the battlefield, if you know what I mean. Luckily we can plan for the unexpected!\n\nWe've begun to store a special stockpile of explosives for scenarios where we'll need a little something extra to get our point across. I've added one particular item to the list. \n\nIf you have any to spare I'll make sure they're put to good use.", objectives = "Gather 3 F.R.I.E.D. for Norber Togglesprocket in Boralus Harbor.", progress = "We've started a special stockpile of explosives for scenarios where we'll need a little something extra to get our point across. I've added one particular item to the list.\n\nIf you have any to spare I'll make sure they're put to good use.", completion = "What a find!\n\nI'll make sure these are handled with care." }
WordHunterWoW_QuestEN[53235] = { title = "Arathi Donations: War-Scroll of Intellect", description = "Enlightenment guides our path to victory. In battle, we fight as one.\n\nShare your knowledge and skills with me. Generosity is never forgotten.", objectives = "Gather 3 War-Scroll of Intellect for Liao in Boralus Harbor.", progress = "Enlightenment presents opportunity for victory.", completion = "Your gift is most appreciated." }
WordHunterWoW_QuestEN[53236] = { title = "Arathi Donations: War-Scroll of Fortitude", description = "", objectives = "Gather 3 War-Scroll of Fortitude for Liao in Boralus Harbor.", progress = "The opportunity for strength and fortitude present themselves when facing difficult situations.", completion = "May preparation guide us, and bravery shine within." }
WordHunterWoW_QuestEN[53237] = { title = "Arathi Donations: War-Scroll of Battle Shout", description = "", objectives = "Gather 3 War-Scroll of Battle Shout for Liao in Boralus Harbor.", progress = "With preparation comes success.", completion = "My thanks." }
WordHunterWoW_QuestEN[53238] = { title = "Arathi Donations: Versatile Kyanite", description = "", objectives = "Gather 20 Versatile Kyanite for Larold Kyne in Boralus Harbor.", progress = "Our gem supplies are running low. Any you can spare would be greatly appreciated.", completion = "Splendid." }
WordHunterWoW_QuestEN[53239] = { title = "Arathi Donations: Straddling Viridium", description = "", objectives = "Gather 15 Straddling Viridium for Larold Kyne in Boralus Harbor.", progress = "We need more gems!", completion = "Wonderful specimens.\n\nThank you for your support." }
WordHunterWoW_QuestEN[53240] = { title = "Arathi Donations: Deadly Solstone", description = "", objectives = "Gather 20 Deadly Solstone for Larold Kyne in Boralus Harbor.", progress = "Have you seen any of these lately?", completion = "You're quite the gem, aren't you?" }
WordHunterWoW_QuestEN[53241] = { title = "Arathi Donations: Coastal Mana Potion", description = "", objectives = "I know ya be tinkin' I be runnin' out of supplies again. And I ain't here ta argue about you bein' right.\n\nSo if ya can bring me some o' dem mana potions, I be gettin' back ta business and we be preparin' for de battle to come.", progress = "I know ya be tinkin' I be runnin' out of supplies again. And I ain't here ta argue about you bein' right.\n\nSo if ya can bring me some o' dem mana potions, I be gettin' back ta business and we be preparin' for de battle to come.", completion = "I be passin' dese along.\n\nThanks for ya donation." }
WordHunterWoW_QuestEN[53242] = { title = "Arathi Donations: Coastal Healing Potion", description = "", objectives = "A few o' dem healin' potions be a nice addition ta our supply. Bring me a few and I be sure dey be gettin' where dey need ta be.", progress = "A few o' dem healin' potions be a nice addition ta our supply. Bring me a few and I be sure dey be gettin' where dey need ta be.", completion = "I be knowin' I can count on you." }
WordHunterWoW_QuestEN[53243] = { title = "Arathi Donations: Coarse Leather Barding", description = "", objectives = "Our riders are not the only ones requiring protection on the field of battle, but our beasts as well.\n\nIf you were to bring me a supply of barding I will personally see to it that our riders and their beasts are outfitted and ready for the battle to come.", progress = "Our riders are not the only ones requiring protection on the field of battle, but our beasts as well.\n\nIf you were to bring me a supply of barding I will personally see to it that our riders and their beasts are outfitted and ready for the battle to come.", completion = "Thank you, <name>. I will see to it that our allies get the protection they deserve." }
WordHunterWoW_QuestEN[53244] = { title = "Arathi Donations: Shimmerscale", description = "", objectives = "Armor is in short supply. We'll get nowhere fast unless we find an abundance of additional materials.", progress = "Armor is in short supply. We'll get nowhere fast unless we find an abundance of additional materials.", completion = "A delivery like this will keep us busy.\n\nThanks for your help." }
WordHunterWoW_QuestEN[53245] = { title = "Arathi Donations: Monel-Hardened Hoofplates", description = "", objectives = "A few more hoofplates and the next shipment will be ready.\n\nI'll be here if you find any in your travels.", progress = "A few more hoofplates and the next shipment will be ready.\n\nI'll be here if you find any in your travels.", completion = "Good work. I'll get them loaded into our shipment immediately." }
WordHunterWoW_QuestEN[53246] = { title = "Arathi Donations: Monel-Hardened Stirrups", description = "", objectives = "Our riders need new stirrups before they're sent off to battle.", progress = "Our riders need new stirrups before they're sent off to battle.", completion = "Strong craftsmanship. Did you make these yourself?" }
WordHunterWoW_QuestEN[53247] = { title = "Arathi Donations: Battle Flag: Spirit of Freedom", description = "", objectives = "Battle standards are in high demand.", progress = "Battle standards are in high demand.", completion = "Did you make this?\n\nThe embroidery is second to none." }
WordHunterWoW_QuestEN[53248] = { title = "Arathi Donations: Battle Flag: Phalanx Defense", description = "", objectives = "We must provide our allies the means to strengthen their defenses.", progress = "We must provide our allies the means to strengthen their defenses.", completion = "Quite the piece. I'll make sure it is put to good use." }
WordHunterWoW_QuestEN[53249] = { title = "Arathi Donations: Tidespray Linen", description = "", objectives = "It's better to be well prepared than in short supply. If you have any linen to spare, we'll make good use of it.", progress = "It's better to be well prepared than in short supply. If you have any linen to spare, we'll make good use of it.", completion = "Very generous of you, <name>." }
WordHunterWoW_QuestEN[53250] = { title = "Arathi Donations: War-Scroll of Fortitude", description = "", objectives = "Not everyone is born a courageous warrior, but who says you can't temporarily behave as such?", progress = "Not everyone is born a courageous warrior, but who says you can't temporarily behave as such?", completion = "These will do quite nicely." }
WordHunterWoW_QuestEN[53251] = { title = "Arathi Donations: War-Scroll of Battle Shout", description = "", objectives = "This particular scroll has quite a powerful effect. Perhaps you're able to acquire such an item?", progress = "This particular scroll has quite a powerful effect. Perhaps you're able to acquire such an item?", completion = "Yes. This will do." }
WordHunterWoW_QuestEN[53252] = { title = "Arathi Donations: War-Scroll of Intellect", description = "", objectives = "Years of study have allowed us to produce scrolls capable of enhancing one's intellect. Have you seen such an item recently? I would die to get my hands on one.", progress = "Years of study have allowed us to produce scrolls capable of enhancing one's intellect. Have you seen such an item recently? I would die to get my hands on one.", completion = "Fine work." }
WordHunterWoW_QuestEN[53253] = { title = "Arathi Donations: Enchant Ring - Seal of Versatility", description = "", objectives = "Gather 2 Enchant Ring - Seal of Versatility for Uma'wi in the Port of Zandalar.", progress = "If ya got somethin' ta give ta be helpin' out da effort, I be here waitin'.", completion = "Ah, yes. Dis be exactly what I was lookin' for." }
WordHunterWoW_QuestEN[53254] = { title = "Arathi Donations: Enchant Ring - Seal of Critical Strike", description = "", objectives = "Gather 2 Enchant Ring - Seal of Critical Strike for Uma'wi in the Port of Zandalar.", progress = "Armor, blades, spears... we be ready. Only ting missin' is a few more enchantments.", completion = "Very nice." }
WordHunterWoW_QuestEN[53255] = { title = "Arathi Donations: Gloom Dust", description = "", objectives = "Gather 20 Enchant Weapon - Stalwart Navigation for Uma'wi in the Port of Zandalar.", progress = "Special enchantments contain de power ta give our allies a fightin' chance.\n\nYou be findin' any in ya journeys?", completion = "Ya read my mind." }
WordHunterWoW_QuestEN[53256] = { title = "Arathi Donations: Deadly Solstone", description = "", objectives = "Got some gems for me?", progress = "Got some gems for me?", completion = "These are a cut above the rest." }
WordHunterWoW_QuestEN[53257] = { title = "Arathi Donations: Versatile Kyanite", description = "", objectives = "Any interesting finds lately?", progress = "Any interesting finds lately?", completion = "Thank you kindly." }
WordHunterWoW_QuestEN[53258] = { title = "Arathi Donations: Straddling Viridium", description = "", objectives = "I'd love to get my hands on a few gems. Have any to spare?", progress = "I'd love to get my hands on a few gems. Have any to spare?", completion = "Yes. These will do just fine." }
WordHunterWoW_QuestEN[53259] = { title = "Arathi Donations: F.R.I.E.D.", description = "", objectives = "We're well on our way with munitions. Only thing left we could really use is something with a bit more kick, if ya know what I mean.", progress = "We're well on our way with munitions. Only thing left we could really use is something with a bit more kick, if ya know what I mean.", completion = "Kaaaa-boooom! Hah!\n\nI can't wait to see these in action." }
WordHunterWoW_QuestEN[53260] = { title = "Arathi Donations: Incendiary Ammunition", description = "", objectives = "We've got a good amount of munitions in our stockpile, but we're always lookin' for something with a bit more kick.", progress = "We've got a good amount of munitions in our stockpile, but we're always lookin' for something with a bit more kick.", completion = "I can't wait to see these in action!" }
WordHunterWoW_QuestEN[53261] = { title = "Arathi Donations: Frost-Laced Ammunition", description = "", objectives = "Ya know what'll really surprise our enemies? The unexpected.\n\nAnd I know just the thing.", progress = "Ya know what'll really surprise our enemies? The unexpected.\n\nAnd I know just the thing.", completion = "They're never gonna see it comin'!" }
WordHunterWoW_QuestEN[53262] = { title = "Arathi Donations: Seasoned Loins", description = "", objectives = "Have any loins you would like to donate?", progress = "Have any loins you would like to donate?", completion = "Very generous of you." }
WordHunterWoW_QuestEN[53263] = { title = "Arathi Donations: Grilled Catfish", description = "", objectives = "Fish provides great nourishment.", progress = "Fish provides great nourishment.", completion = "This is a wonderful treat." }
WordHunterWoW_QuestEN[53264] = { title = "Arathi Donations: Great Sea Catfish", description = "", objectives = "A belly full of fish is a wonderful feeling.", progress = "A belly full of fish is a wonderful feeling.", completion = "You are very kind, <name>. Thank you." }
WordHunterWoW_QuestEN[53265] = { title = "Arathi Donations: Gold", description = "We've spent a great deal of time and resources preparing for the battle to come. \n\nAs we begin final preparations, we'll be setting aside additional funding to ensure further training and supplies are available at a moment's notice. \n\nWould you like to make a donation?", objectives = "Donate 1000000 Gold to Paymaster Vauldren in Boralus Harbor.", progress = "As we begin final preparations, we'll be setting aside additional funding to ensure further training and supplies are available at a moment's notice.\n\nWould you like to make a donation?", completion = "How generous of you, <name>." }
