WordHunterWoW_QuestEN[53267] = { title = "Mission Report: Dino Research", description = "Your followers have sent a report regarding the mission at Verdant Hollow.\n\nIt details that the mission was a success and a variety of dinasaur specimens have been recovered.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", objectives = "Deliver the mission report to Halford Wyrmbane.", progress = "Do you have news regarding the mission for Verdant Hollow?", completion = "It seems the mission was a success. Well done, <name>." }
WordHunterWoW_QuestEN[53268] = { title = "Dino Research", description = "The mission to gather research specimens was a success. Well done, {name}.\n\nYou should check in with the outpost commander and inspect the specimens yourself.\n\nMake your way to Verdant Hollow in Zuldazar and speak with Argrim Stonedeep.", objectives = "Speak with Argrim Stonedeep.", completion = "Och, yer team did their job alright! Look at these wee dinasaur hatchlings...there's more o' them than us!" }
