WordHunterWoW_QuestEN[53330] = { title = "WANTED: Razorclaw Alpha", description = "The Horde requires your contributions!\n\nWe are in need of materials to craft and repair our arms and armor.\n\nThere are bountiful resources in this land and they are but ours for the taking.\n\nSeek out the largest wolf you can find, slay it, and secure it's pelt so that we may craft a cloak befitting Rexxar!\n\n- Centurion Kaga Warmstone", objectives = "Obtain a Razorclaw Alpha Pelt.", progress = "Have you located a suitable pelt?", completion = "An excellent pelt! Good work <name>." }
WordHunterWoW_QuestEN[53331] = { title = "Show-Off", description = "", objectives = "" }
WordHunterWoW_QuestEN[53332] = { title = "Time for War", description = "You should return to Commander Wyrmbane to begin working with the 7th Legion.", objectives = "Report to Halford Wyrmbane in Boralus.", completion = "<Halford looks over the gathered resources.>\n\nThis should do it." }
WordHunterWoW_QuestEN[53333] = { title = "Time for War", description = "You should return to Nathanos Blightcaller to begin working with The Honorbound.", objectives = "Report to Nathanos Blightcaller in Zuldazar.", completion = "<Nathanos looks over the gathered resources.>\n\nThis should do it." }
WordHunterWoW_QuestEN[53334] = { title = "Arathi Donations: War Resources", description = "", objectives = "We are part of a great effort. Let us stand together in the battle to come.", progress = "We are part of a great effort. Let us stand together in the battle to come.", completion = "Thank you for your contribution." }
WordHunterWoW_QuestEN[53335] = { title = "Arathi Donations: War Resources", description = "", objectives = "Our forces are gathering for the battle to come. Do you wish to help further our efforts?", progress = "Our forces are gathering for the battle to come. Do you wish to help further our efforts?", completion = "A generous donation. I will let the commander know of your contributions." }
WordHunterWoW_QuestEN[53336] = { title = "WANTED: Sabertusk Empress", description = "To any and all brave enough to seek the challenge: \n\nFind and defeat a ferocious Sabertusk Empress, the strongest and most vicious of all sabertusks in Zuldazar. \n\nThey can be found up and down the road from the Village in the Vines. \n\nA reward for any that succeed!", objectives = "Slay a Sabertusk Empress", completion = "Thank ya, champion. That be one less threat to the area." }
WordHunterWoW_QuestEN[53337] = { title = "WANTED: Prime Thumpknuckle", description = "To any and all brave enough to seek the challenge: \n\nFind and defeat a Prime Thumpknuckle, the largest and most dangerous of all the wild gorillas.\n\nThey can be found up and down the road from the Village in the Vines. \n\nA reward for any that succeed!", objectives = "Slay a Prime Thumpknuckle", completion = "You faced down those Thumpknuckles? That's worth a lot to us. Thank ya." }
WordHunterWoW_QuestEN[53338] = { title = "Prove your Worth", description = "See many Alliance out there, {race}? We're getting reports of more and more Alliance showing up here on Zandalar.\n\nDon't forget that this is a W-A-R. Prove your worth, and get out there and slay as many of them as you can.\n\nFor the Horde!", objectives = "Enable War Mode and slay 1 Alliance Player within the world.", completion = "A good first start, here's something from our engineers that may prove useful..." }
WordHunterWoW_QuestEN[53339] = { title = "LFG - BFA - Island Expedition - Heroic Win - Nth", description = "", objectives = "" }
WordHunterWoW_QuestEN[53340] = { title = "LFG - BFA - Island Expedition - Mythic Win - Nth", description = "", objectives = "" }
WordHunterWoW_QuestEN[53341] = { title = "LFG - BFA - Island Expedition - PvP Win - Nth", description = "", objectives = "" }
WordHunterWoW_QuestEN[53342] = { title = "Molten Core", description = "We'll need a fragment o' the core tae repair the Black Anvil an' who knows how much dark iron tae achieve the necessary purity. Thaelin can figure that part out.\n\nIn fact, I think he oughta go with ye tae get yerself a Fragment o' the Molten Core.\n\nIt's too dangerous tae go deep via mole machine, but he's got a hardy tank that can get ye the rest o' the way from the top.\n\nTalk tae me when yer ready.", objectives = "Speak with Moira at the Stormwind Embassy to travel to Molten Core and retrieve a Fragment of the Molten Core.", progress = "Sometimes it's hard tae understand Thaelin's ramblin's, but he's a smart one.", completion = "Good work, <name>. That fragment gets us a long way toward fixin' the Black Anvil." }
WordHunterWoW_QuestEN[53343] = { title = "Censership", description = "", objectives = "" }
WordHunterWoW_QuestEN[53344] = { title = "Iconoclasm", description = "", objectives = "" }
WordHunterWoW_QuestEN[53345] = { title = "Plunder and Provisions", description = "", objectives = "" }
WordHunterWoW_QuestEN[53346] = { title = "Trogg Tromping", description = "", objectives = "" }
WordHunterWoW_QuestEN[53347] = { title = "Bumbles the Bee", description = "Hey {name}, thanks for delivering Mom's letter. I was really starting to worry about her!\n\nDad and I have been having a few problems running the farm after she left on her trip. If you didn't show up when you did, we'd still be in real trouble!\n\nI was hoping you would be willing to help Bumbles out too. He was hurt when his hive was destoyed.\n\nIf we feed him some of Dad's special formula, hopefully he will heal up faster. First we need to find the secret ingredient, try looking around at his other lab.", objectives = "Locate Raimond's Secret Ingredient.", progress = "Were you able to find it? I think it's in a purple bottle.", completion = "Alright! This is exactly what we needed." }
WordHunterWoW_QuestEN[53348] = { title = "WANTED: Thundersnout", description = "Thundersnout is the largest of the boars in the valley. She poses a serious threat to our troop movements in the south.\n\nAs such, Centurion Kaga Warmstone has issued a bounty for proof of her demise.\n\nThundersnout's location is near the Briarback kraul, so beware the local quilboar!", objectives = "Deliver Thundersnout's Snout to Centurion Kaga Warmstone.", progress = "Yes?", completion = "The death of the matriarch means the next generation of boars will be delayed. Nice work." }
WordHunterWoW_QuestEN[53349] = { title = "Conquest's Reward", description = "", objectives = "Your prowess on the field of battle is without peer." }
WordHunterWoW_QuestEN[53351] = { title = "The MOTHERLODE!!: Ironfoe", description = "Mogul Razdunk has always been a jealous sort, wishin' he was Gallywix or better.\n\nBut he's the worst sort o' greedy. He won't stop at anythin' tae achieve his ends, nae matter the cost.\n\nIt was a bold move even fer him tae strike at us in Blackrock Depths.\n\nHe should've knaewn he was goin' too far. Kill that covetous wretch an' bring the hammer back where it belongs.\n\nYou'll find him in Kezan. Somewhere he calls \"The Motherlode,\" likely with too many exclamation points.", objectives = "Recover Ironfoe from Mogul Razdunk.", progress = "I wish I could see look on his face as ye rip the hammer away from his cold hands.", completion = "Serves him right fer stealin' one o' our most sacred artifacts. I hope he squirmed." }
WordHunterWoW_QuestEN[53352] = { title = "Firelands", description = "Alright, the hard part should be behind us, {name}.\n\nNow, we just need tae take that Molten Core fragment ye recovered into Firelands an' charge it up by Ragnaros' old swimmin' pool.\n\nDinna worry! I'm sendin' Anvil-Thane Thurgaden with ye.\n\nJust give me a nudge when ye're ready.", objectives = "Speak with Moira at the Stormwind Embassy to travel to the Firelands and empower the Fragment of the Molten Core.", progress = "I hope ye're nae afraid o' a little bit o' fire.", completion = "High Justice Grimstone calls himself the Herald o' Ragnaros now, does he? That traitor will rue the day he turned his back on the Dark Iron dwarves." }
WordHunterWoW_QuestEN[53353] = { title = "Echo of Warlord Zaela", description = "Warlord Zaela... another name that stains the tongue just to speak it...\n\nShe was instrumental in freeing Garrosh during his trial when she and her Dragonmaw clan attacked the Temple of the White Tiger.\n\nI am ashamed to say that the dragon Kairozdormu was also involved. We will speak of this no more.\n\nThe temple in Kun Lai Summit is our next destination.", objectives = "Defeat the Echo of Warlord Zaela at the Temple of the White Tiger in Kun Lai Summit.", progress = "Some of my kin invite shame upon our name.", completion = "Let us leave this place before it arouses my anger." }
WordHunterWoW_QuestEN[53354] = { title = "Echo of Gul'dan", description = "To attune this shard to the place you wish to go, we must follow some of its history.\n\nThe first location we will visit is the Dark Portal in the Blasted Lands.\n\nIt was there that Gul'dan used a piece of the Vision of Time to travel between realities.\n\nJoin me there when you are ready.", objectives = "Defeat the Echo of Gul'dan at the Dark Portal in Blasted Lands.", progress = "The Vision of Time still holds power, it just needs to be unlocked.", completion = "Gul'dan was a pox upon all lands that he set foot upon. His death was well deserved." }
WordHunterWoW_QuestEN[53355] = { title = "Echo of Garrosh Hellscream", description = "Our final destination will take us to the depths beneath your city of Orgrimmar.\n\nThe way there is barred, but I can get us inside.\n\nMeet me outside the gates of Orgrimmar and we will descend together.", objectives = "Meet Anachronos outside the gates of Orgrimmar, then defeat the Echo of Garrosh within the Siege of Orgrimmar.", completion = "Yes, this thrums with power! This is precisely what I needed." }
WordHunterWoW_QuestEN[53358] = { title = "Test of Hyphen Tech", description = "This is--a test of--our new hyphen--breaking technology which--we are getting--to help sentences--read better. If you--are datamining this--then I am--sorry, but--you are sure--to be disappointed. Okay--FINE--Jaina really is--a dreadlord--oh and so--are Sylvanas--Anduin--and Khadgar--I mean--who ISN'T a--dreadlord, really?", objectives = "This is--a test of--our new hyphen--breaking technology which--we are getting--to help sentences--read better. If you--are datamining this--then I am--sorry, but--you are sure--to be disappointed. Okay--FINE--Jaina really is--a dreadlord--oh and so--are Sylvanas--Anduin--and Khadgar--I mean--who ISN'T a--dreadlord, really?" }
WordHunterWoW_QuestEN[53359] = { title = "Arathi Donations: Steelskin Potion", description = "", objectives = "Some o' da best potions give ya allies a fightin' chance. If ya find any, come an' see me.", progress = "Some o' da best potions give ya allies a fightin' chance. If ya find any, come an' see me.", completion = "Don't ya be worryin'. I be handlin' these with special care." }
WordHunterWoW_QuestEN[53360] = { title = "Arathi Donations: Steelskin Potion", description = "", objectives = "Gather 2 Steelskin Potions for Chelsea Strand in Boralus Harbor.", progress = "Steelskin Potions are a great source of protection.\n\nIf you should find any in your travels, I'd gladly take them off your hands.", completion = "Wonderful! This is exactly what I was looking for." }
WordHunterWoW_QuestEN[53361] = { title = "Arathi Donations: Meaty Haunch", description = "A nice, hearty meat provides the nourishment our allies deserve before shipping off to battle, not to mention it also makes quite a stew, something our troops seem to rather enjoy when the winds are at their best and the chill of night lingers in the air.\n\nIf you bring me some freshly seasoned loins I would be more than happy to deliver it to our supply officers.", objectives = "Gather 2 Seasoned Loins for Senedras in Boralus Harbor.", progress = "Fresh meat goes a long way. If we're to endure the battle, we've got to be prepared.", completion = "This will last for quite some time.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[53362] = { title = "Arathi Donations: Meaty Haunch", description = "", objectives = "Delicious food provides the nourishment needed to endure what is to come.", progress = "Delicious food provides the nourishment needed to endure what is to come.", completion = "Your donation is most appreciated." }
WordHunterWoW_QuestEN[53363] = { title = "Arathi Donations: Drums of the Maelstrom", description = "", objectives = "Donate 2 Drums of the Maelstrom to Charlane in Boralus Harbor.", progress = "In battle, those who are victorious march to the beat of the same drum.\n\nWhat say we provide our allies with a little drumming of our own?", completion = "Finely crafted, taught hide... is this bone? This work is quite masterful.\n\nI'll make sure these are put to good use." }
WordHunterWoW_QuestEN[53364] = { title = "Arathi Donations: Drums of the Maelstrom", description = "", objectives = "Soldiers rely upon each other in battle. What do say we provide them with a little boost on the battlefield?", progress = "Soldiers rely upon each other in battle. What do say we provide them with a little boost on the battlefield?", completion = "The craftsmanship on these drums are extraordinary.\n\nI'll be sure to pass these along. Thank you, <name>." }
WordHunterWoW_QuestEN[53365] = { title = "Arathi Donations: Battle Flag: Rallying Swiftness", description = "", objectives = "Our allies rally beneath our banners on the battlefield. Help us provide them the speed and precision necessary to break the frontline.", progress = "Our allies rally beneath our banners on the battlefield. Help us provide them the speed and precision necessary to break the frontline.", completion = "What beautiful work." }
WordHunterWoW_QuestEN[53366] = { title = "Arathi Donations: Battle Flag: Rallying Swiftness", description = "", objectives = "Gather 2 Battle Flag: Phalanx Defense for Faella in Boralus Harbor.", progress = "The finest threading and craftsmanship create the most beautiful standards.\n\nHave you any to offer?", completion = "Truly magnificent.\n\nOur allies will rally beneath our colors on the battlefield." }
WordHunterWoW_QuestEN[53367] = { title = "Arathi Donations: Organic Discombobulation Grenade", description = "", objectives = "Nothing provides an advantage like the ability to spot your enemies from a great distance. You got anything of the kind?", progress = "Nothing provides an advantage like the ability to spot your enemies from a great distance. You got anything of the kind?", completion = "Wonderful work, <name>. And lighter than I expected. Magnificent." }
WordHunterWoW_QuestEN[53368] = { title = "Arathi Donations: Organic Discombobulation Grenade", description = "", objectives = "Distance, accuracy, quality metal, and top-notch craftsmanship--nothing else will do.\n\nI don't suppose you're able to get your hands on a few of these?", progress = "Distance, accuracy, quality metal, and top-notch craftsmanship--nothing else will do.\n\nI don't suppose you're able to get your hands on a few of these?", completion = "Spectacular! This is just what I was looking for." }
WordHunterWoW_QuestEN[53369] = { title = "Make Loh Go", description = "Hello, {name}! We tortollans grow up hearing the stories of Loh, a tortollan who had many adventures. These stories help to challenge a young tortollan's mind as they try to figure out how Loh would make his way through any given adventure.\n\nCare to give it a try?", objectives = "Learn how to guide Loh." }
WordHunterWoW_QuestEN[53370] = { title = "Battle for Azeroth: Hour of Reckoning", description = "Champions of the Alliance, \n\nAt last the time has come for us to reclaim what is rightfully ours! Our final push to retake Lordaeron Keep shall commence at dawn. \n\nThe Horde and their Warchief must answer for their crimes!", objectives = "Meet Master Mathias Shaw in Stormwind Harbor.", completion = "The Horde will pay for what they've done." }
WordHunterWoW_QuestEN[53371] = { title = "Let's Bee Friends", description = "We just need to collect some slime from the animated honey creatures that are still roaming around the farm.\n\nIf you can bring back a few vials of that, we can put all our ingredients together and give the mixture to Bumbles.\n\nWe should only feed him once a day, or he might get sick like some of the other bees.\n\nWe're gonna have him all healed up in no time!", objectives = "Collect 8 Vials of Honey Slime and mix them with Raimond's Secret Ingredient to make Mildenhall's Growth Formula, then feed it to Bumbles.", progress = "Did you collect enough of the slime?", completion = "He's looking so much better!" }
WordHunterWoW_QuestEN[53372] = { title = "Battle for Azeroth: Hour of Reckoning", description = "Champions of the Horde, the time has come. \n\nThe Alliance seek to overthrow the Undercity and are laying siege to Lordaeron Keep. You are to report High Overlord Saurfang at once.\n\nMake haste, Brill has already fallen and there is no time to spare.", objectives = "Speak to High Overlord Saurfang inside Grommash Hold.", completion = "The Alliance moves against the Undercity, seeking retribution for the burning of Teldrassil.\n\nWe will not allow them to take what is ours, <class>." }
