WordHunterWoW_QuestEN[53405] = { title = "Unlocking the Heart's Potential", description = "I sense the Heart of Azeroth gettin' stronger, <name>. Perhaps we can unlock even more of the amulet's potential.\n\nYer gonna need every bit o' its might. As if there weren't already forces fightin' over Azerite, lately it seems the servants o' the Old Gods have begun tae seek it out as well!\n\nCome. We can use the Azerite ye've gathered tae strengthen the Heart.", objectives = "Speak to Magni Bronzebeard and empower the Heart of Azeroth.", progress = "Hold still, champion, while I empower the Heart of Azeroth.", completion = "We're on the right track, champion. Keep absorbin' Azerite and stoppin' those who seek tae abuse it.\n\nAzeroth seems confused... worried. I don't know what tae make of it, but I fear things are gonna get worse before they get better." }
WordHunterWoW_QuestEN[53406] = { title = "The Chamber of Heart", description = "That amulet ye wear keeps gettin' stronger, <name>. But tae unlock further potential, we need tae go somewhere closer tae Azeroth's world soul.\n\nThe Chamber of Heart!\n\nI know the last time ye saw it, things were lookin' bleak. But meet me there, and I think ye'll agree that we're makin' progress on healin' our world's wounds!", objectives = "Empower the Heart of Azeroth within the Chamber of Heart.", progress = "The Chamber of Heart is the key to that amulet's might.", completion = "Ye pushed the darkness back, <name>. But that ain't the last we'll see of it.\n\nThe mightier the Heart of Azeroth becomes, the bigger the target ye have on yer back.\n\nStay on yer guard, champion. We cannae lose the Heart... and we cannae lose ye." }
WordHunterWoW_QuestEN[53413] = { title = "A Greater Effort", description = "Champion, I write this letter with a steady hand on parchment laid atop the latest shipment of supplies from our recent efforts.\n\nOur allies continue to gather as our soldiers, weapons, and provisions arrive from lands far and wide. \n\nPlease join me at the docks at once. We have much to discuss.", objectives = "" }
WordHunterWoW_QuestEN[53414] = { title = "Warfront: The Battle for Stromgarde", description = "If the Horde thinks it can assault Stromgarde, it is sorely mistaken! We will not let Arathi fall!\n\nPrepare yourself for battle.", objectives = "Defeat the Horde at the Battle for Stromgarde.", progress = "We must do what we can to claim Arathi for the Alliance.", completion = "Well fought, <name>, though I'm afraid it may be premature to let our guard down just yet. I am sure our enemy will not sit idly while we rebuild Stromgarde." }
WordHunterWoW_QuestEN[53415] = { title = "A Greater Effort", description = "Warrior of the Horde, the time has come.\n\nOur forces gather with strength and steel to prepare for the battle to come. Join us in our effort to remove the Alliance from Arathi once and for all.\n\nI await your arrival at the docks.", objectives = "" }
WordHunterWoW_QuestEN[53416] = { title = "Warfront: The Battle for Stromgarde", description = "Our enemies are relentless in their quest to seize Arathi for themselves. We will never allow it to fall into their hands! We must stop them before the keep is rebuilt!\n\nTake up arms. The Alliance is upon us.", objectives = "Defeat the Alliance at the Battle for Stromgarde.", progress = "We will claim Arathi as our own!", completion = "A battle well fought, <name>. You have once again proven yourself a great warrior of the Horde." }
WordHunterWoW_QuestEN[53430] = { title = "Order of Embers Crossbow", description = "<Old and worn, this crossbow resembles those depicted in artwork of the Order of Embers.>", objectives = "<You set the old crossbow in a place of honor.>" }
WordHunterWoW_QuestEN[53431] = { title = "Order of Embers Flask", description = "<Old and worn, this flask resembles those depicted in artwork of the Order of Embers.>", objectives = "<You set the old flask in a place of honor.>" }
WordHunterWoW_QuestEN[53432] = { title = "Order of Embers Knife", description = "<Old and worn, this knife resembles those depicted in artwork of the Order of Embers.>", objectives = "<You set the old knife in a place of honor.>" }
WordHunterWoW_QuestEN[53433] = { title = "Order of Embers Hat", description = "<Old and worn, this hat resembles those depicted in artwork of the Order of Embers.>", objectives = "<You set the old hat in a place of honor.>" }
WordHunterWoW_QuestEN[53434] = { title = "The Vanishing Lord", description = "Whoa there! What business do you have in Drustvar?\n\nLookin' for someone from House Waycrest? Best of luck to ye.  Even us in their guard haven't heard a word from them of late. Why, if it weren't for Marshal Reade takin' command, I doubt there'd even be a Waycrest Guard anymore.\n\nI think ye'd be better off on yer way, but if yer bent on stayin' I'd head over to Fallhaven. The mayor there is probably the only welcomin' soul left around here.\n\nWatch yer back, mainlander. There's dark workings about.", objectives = "Meet with Cyril White in Fallhaven in Drustvar.", completion = "<The effigy is protected by powerful magic. \n\nIt seems it will take more than brute force to break this curse.>" }
WordHunterWoW_QuestEN[53435] = { title = "Azerite for the Horde", description = "Assist the Horde by collecting Azerite on Island Expeditions.", objectives = "Collect Azerite on Island Expeditions.", progress = "Return to me when you have finished aiding de Horde, <name>.", completion = "For de Horde!" }
WordHunterWoW_QuestEN[53436] = { title = "Azerite for the Alliance", description = "Assist the Alliance by collecting Azerite on Island Expeditions.", objectives = "Collect Azerite on Island Expeditions.", progress = "Return to me when you have finished aiding the Alliance, <name>.", completion = "For the Alliance!" }
WordHunterWoW_QuestEN[53437] = { title = "The MOTHERLODE!!: Raw Deal", description = "Nobody, and I mean NOBODY double-crosses me and gets away with it!\n\nThe Venture Co. betrayed us in a deal for Azerite refining techniques. We need pay 'em what we owe 'em.\n\nIf you're not pickin' up what I'm puttin' down, I mean we need to kill that backstabbin' upstart Mogul Razdunk.\n\nYou take care of him; I'll take care of gettin' what we're owed.\n\nI s'pose we oughta tell Blightcaller about this, huh? When he tells us what to do, just smile and nod. We'll handle it our way.", objectives = "Send a permanent--fatal--message to Mogul Razdunk in The MOTHERLODE!!", progress = "I'm mad as a... as a... I'm just MAD, okay?!\n\nLook, I realize Blightcaller told you to get the refining techniques, but I'll take care of that.\n\nYou just kill Razdunk, got it?", completion = "Ya really did me a solid there, <name>. May that green bastid rot in a squalid grave." }
WordHunterWoW_QuestEN[53438] = { title = "WANTED: Wyvern Poachers", description = "Soldiers of the Horde!\n\nA few nights ago some foolish human soundrels snuck off with one of our strongest wyverns.\n\nIf anybody can track down and stop these thieves, a reward awaits!", objectives = "Kill Lindel the Snatcher and Silent Boris.", progress = "Is this about the wanted sign? You better hurry, a good number of hunters are after it as well.", completion = "The wyvern came back mostly unharmed. She will be ready to fly into battle when needed." }
WordHunterWoW_QuestEN[53439] = { title = "Blood in the Tides", description = "We do not have sirens in Zandalar, but our sailors know of dem. In Zandalari, we call dem bwon'tulak - de death singers.\n\nMy ship was run aground and my fellow sailors all murdered by de death singers.\n\nJane saved my life, so now I help to protect dese people.\n\nSirens are a plague on da seas, no matter who ya serve. Run the tides red wit dere blood!", objectives = "Slay 8 Wailing Sirens.", completion = "You have made de seas safer for all. You have my thanks." }
WordHunterWoW_QuestEN[53440] = { title = "WANTED: The Hornet", description = "That's it, I'm putting a bounty on that blasted hornet.\n\nSomebody take that bug down!", objectives = "Kill The Hornet.", completion = "The hornet's dead! Good on ya.\n\nI'd like to not die to a bug." }
WordHunterWoW_QuestEN[53442] = { title = "The Castaways", description = "You don't look like you're from around here. You're lucky the sirens haven't stripped your bones yet.\n\nIf you need to trade supplies or just warm yourself by the fire, there's a camp up the hill behind me.\n\nEveryone there washed up in the tides. Figure we've got folks from at least four or five shipwrecks now. All banded together, just tryin' to survive.\n\nTalk to Stabby Jane. Don't worry about her nickname, she's actually real nice.", objectives = "Speak with Stabby Jane at Castaway Point.", completion = "You from a shipwreck? Or just looking for work?" }
WordHunterWoW_QuestEN[53443] = { title = "My Favorite Things", description = "It's tough out here.\n\nPirates. Deadly monsters. \n\nHungry Sam's seemingly endless battle with indigestion.\n\nNothing sets the nerves at ease like an old keepsake. Somethin' to remind you of home. Somethin' to keep you going.\n\nAsk around the camp. Find out what folks might have lost out there in the tideways. If you can bring any of it back, it'd be a mighty kind gesture.\n\nMe? Oh... I had a locket... \n\nNever mind, it's too small, you'd never find it. It's nothing. Don't worry about it.", objectives = "Ask Friendly Pete, Hungry Sam and Handy Bill about their missing keepsakes, then collect those items from the Wailing Tideway.", progress = "We've all lost something in the tides.\n\nSome more than others.", completion = "I didn't think you'd actually find all this stuff!\n\nWe don't have much, but here's a little something for your troubles." }
WordHunterWoW_QuestEN[53444] = { title = "Glimmering Locket", description = "<A glint of metal catches your eye among the gently bobbing flotsam. Digging into the tangled seaweed, you discover a locket of simple, yet sturdy design.\n\nOpening the locket reveals a hand-drawn picture of a woman with fiery red bangs. \n\nHer arm is around a woman with short-cropped auburn hair, and the two are proudly displaying warm smiles for the artist.>", objectives = "Return the Glimmering Locket to Stabby Jane.", progress = "Hm? What's that you've got there?", completion = "Is that?\n\n<Jane takes the locket and opens it tenderly. Tears begin to well up in her eyes as she closes it and tucks it away in her jacket.>\n\nThank you." }
WordHunterWoW_QuestEN[53445] = { title = "Silencing the Sisters", description = "The sirens in this tideway have drawn countless ships to their doom. Wiping them out would be a boon to all seafaring folk.\n\nBut you can't very well kill all of them. Only a fool would try that.\n\nThe real dangerous ones are the elders. The \"sisters\" as they're known. Bigger, smarter, and stronger than the younger ones. Their voices carry far out to sea and bring in all the big \"catches.\"\n\nI managed to track two of them to a den at the northern end of the tideway, but I can't take them alone.", objectives = "Slay Patheope and Nolpe.", completion = "By quieting their deadly song, you have saved countless lives." }
WordHunterWoW_QuestEN[53446] = { title = "Local Flavor", description = "I'm STARVING.\n\nNot actually starving, like when I first got here, but you know... Emotionally starving.\n\nHaven't had any luck with the oysters lately, and seaweed soup really upsets my guts. If I eat any more of that stuff, I think the other castaways might actually feed me to the sharks.\n\nHow about them tidelurkers? They look pretty juicy. Bet you could steam those up real nice.\n\nCan you get me some? I'm not much of a hunter. But I'll share it with you!", objectives = "Gather 5 Juicy Lurker Tails.", progress = "<Sam's stomach growls audibly.>", completion = "Oh, you're a lifesaver!\n\nHang on just a sec, I'll cook these up in no time!" }
WordHunterWoW_QuestEN[53449] = { title = "Apes of Wrath", description = "Alliance, just what I need. Down for performing a deed?\n\nZandalari are afraid, of new gorillas that raid.\n\nThese gorillas are mocking, these gorillas are talking.\n\nGorillas are dookering, I hear they follow bad king. \n\nIt is important to lead, but this guy fails to succeed.\n\nI shall send Flap-Flap ahead. Make ookin' wikket King dead.", objectives = "Travel to Gorilla Gorge.", completion = "OOK! Just in time!" }
WordHunterWoW_QuestEN[53450] = { title = "King Da'ka", description = "King Da'ka? More like King Dooker.\n\nMy king sent me to talk to this new king. This new king took my things and tried to take my wings.\n\nNegotiations are ooked. Go, sticket to that angry wikket.", objectives = "Slay King Da'ka.", completion = "Good. Gorillas gotta learn: Kings gotta earn. If they not earn, they not learn." }
WordHunterWoW_QuestEN[53451] = { title = "WANTED: Raging Earthguard", description = "I have been receiving formal complaints about some big earth elemental in the middle of our scouting path.\n\nNormally I'd elect to ignore these, but the sooner we get done here, the better. Nobody wants to be stuck in this frozen hill any longer than we need to.\n\nPayment goes to the person who brings it down!", objectives = "Kill the Raging Earthguard west of Norwington Estate.", completion = "Now the complaints should stop. Thanks a lot, pal!" }
WordHunterWoW_QuestEN[53452] = { title = "Gorilla Warfare", description = "Your timing is most fortuitous, stranger. I thank you for your assistance.\n\nThings are not peaceful in Gorilla Gorge. The kaja'mite has given us great intelligence and wit. With intelligence has come war. \n\nMy brethren are those who do not wish to fight. But for our passivity we have been persecuted.\n\nPlease free my comrades. They will be in cages all throughout the gorge and under guard. Make haste!", objectives = "Rescue 6 Pacifist Gorillas.", completion = "Thank you my friend! I saw the bravery with which you granted freedom to my comrades. We shall speak more anon." }
WordHunterWoW_QuestEN[53453] = { title = "To Stomp or Not To Stomp", description = "Like grandpapaook always say: if a wikket gonna huff the swoof from a dookerhole then plug the dookerhole.\n\nThese Da'kani wikkets huffing the green smoke from their dookerholes in the ground. Makes 'em smart and mean. Smart not so bad, mean is bad.\n\nGo into Gorilla Gorge and plug those dookerholes!", objectives = "Collapse Kaja'mite Steam Vents in Gorilla Gorge.", completion = "Haha. Good. Can't have gorillas going all mean-wikket on everyone." }
WordHunterWoW_QuestEN[53454] = { title = "WANTED: Quartermaster Ssylis", description = "Some pirates took off with a supply crate that landed further away from this site then intended.\n\nI don't think there was anything valuable in there, but now the pirates know we're here.\n\nThe leader was one of those big lizard men. The worker that kills him will get double pay for the week!", objectives = "Kill Quartermaster Ssylis in Krakenbane Cove.", completion = "Good work! Hopefully that means we'll be losing less supply drops now." }
WordHunterWoW_QuestEN[53455] = { title = "WANTED: The Crimson Cutthroats", description = "For numerous and sinister crimes against the Lord Admiral: smuggling, forgery, sailing under false colors, looting, poaching, brigandage, sacking, pillaging, vandalism, impersonating Kul Tiran Naval officers, arson, kidnapping, torture, piracy, perjury, theft and ransacking multiple mead shipments.\n\nA reward is placed on the heads of The Crimson Cutthroats to be paid in full upon proof of their demise.", objectives = "Slay the Crimson Cutthroats near Falconhurst.", progress = "Ugh. That lot. Glad someone finally took care of them.", completion = "I tell ya I ain't sad to see that group go.\n\nI know you're not on exactly friendly terms with the Kul Tirans so how's about I front you the reward money and then use my connections to get the reward. Sound good?" }
WordHunterWoW_QuestEN[53456] = { title = "WANTED: The Rime Huntress", description = "Attention Interested Parties! A Moneymaking Opportunity Awaits!!!!!\n\nThere's a big wolf hunting people in the pass. She's taken a liking to the taste of goblin. Nobody got time for being eaten by a wolf, so take out the Rime Huntress and I'll pay you for your trouble.\n\n- Suzie Boltwrench", objectives = "Defeat The Rime Huntress near Highroad Pass.", completion = "Hey you got rid of that big wolf? Nice!\n\nIt'll be nice to know she's not munchin' on any of our miners." }
WordHunterWoW_QuestEN[53457] = { title = "Quartermaster's Bounty", description = "To defeat the enemy, you will need to keep your equipment in peak condition. If you have been unable to acquire more powerful arms, I can requisition from the quartermaster on your behalf.", objectives = "To defeat the enemy, you will need to keep your equipment in peak condition. If you have been unable to acquire more powerful arms, I can requisition from the quartermaster on your behalf.", progress = "To defeat the enemy, you will need to keep your equipment in peak condition. If you have been unable to acquire more powerful arms, I can requisition from the quartermaster on your behalf.", completion = "Victory at any cost." }
WordHunterWoW_QuestEN[53458] = { title = "WANTED: Rindlewoe", description = "A monstrous beast of wood and flesh has been terrorizing the nearby river territories. Knowing more about how the creature fights may yield interesting data!\n\nPlease report any and all findings to Suzie Boltwrench in Krazzlefrazz.", objectives = "Defeat Rindlewoe outside of Fallhaven.", completion = "Hey! You got some great data off that monster.\n\nHere's a little somethin' for being such a great research assistant." }
WordHunterWoW_QuestEN[53459] = { title = "WANTED: Sister Lilias", description = "The Krazzlefrazz Peacekeepers are looking for an able-bodied warrior to eliminate a threat in nearby Corlain.\n\nA witch by the name of Sister Lilias is wanted for the torture and killing of many of our people. Her end would prove a boon to the Horde.\n\nPresent her head to claim your just reward.", objectives = "Collect Sister Lilias' head from Sister Lilias in Corlain.", progress = "Hey, we got some witch problems. Mind taking care of it?", completion = "You got rid of that witch? Great! She was really cutting into our operation here.\n\nHere's the bounty, paid out in full. Pleasure doin' business with ya." }
WordHunterWoW_QuestEN[53461] = { title = "Precious Metals", description = "Hey you! I got a business proposition for ya.The locals here seem to have a thing for silver, and we hit the jackpot with a mine just west of here. \n\nUnfortunately, it's got a bit of a spider problem...\n\nNow, the miners we sent down there are probably goners by now, but there's still some silver left down there. If you can go and fetch it for me, we'll mark it up and make a fortune!\n\nWhat do you say?", objectives = "Collect 10 Silver Nuggets from the Bleak Hills Mine.", progress = "Did you find the silver?", completion = "Way to come through, pal!\n\nOh, some of the miners were still alive? Now that's just crazy talk." }
WordHunterWoW_QuestEN[53462] = { title = "All Wrapped Up", description = "I'm not the only one trapped here in this mine. Grimelock left all of the other miners to the spiders, too.\n\nThere might be some of them still alive out there. Could you help? I'd appreciate it if not all of my friends died.", objectives = "Destroy Writhing Cocoons to rescue 8 Bleak Hills Miners in the Bleak Hills Mine.", completion = "Whew! I'm glad some of us were able to make it out of here.\n\nI'm pretty sure I'm ending up with arachnophobia after this.." }
WordHunterWoW_QuestEN[53463] = { title = "An Eight-Legged Curse", description = "That jerk Grimelock sent us down here to the mines, only to pack up and leave us behind when these spiders showed up! Now I'm stuck here with about a million legs and eyes in all directions.\n\nYou look like the tough sort. Can you clear a path for me? I'll make it worth your while.", objectives = "Kill 20 Bilefang spiders in the Bleak Hills Mine.", completion = "That's a relief!\n\nNow I can head back to Krazzlefrazz and give Grimelock a piece of my mind!" }
WordHunterWoW_QuestEN[53464] = { title = "The Village of Glenbrook", description = "<The book is a register of the inhabitants of Glenbrook.\n\nAll but a few of the names are crossed out.>", objectives = "Discover the fate of the Glenbrook villagers.", completion = "<The body is twisted and mangled nearly beyond recognition.\n\nYou can only assume this is the \"Annie\" mentioned in the register.>" }
WordHunterWoW_QuestEN[53465] = { title = "Tea Party", description = "<You hear footsteps behind you.>", objectives = "Find Abby Lewis." }
WordHunterWoW_QuestEN[53466] = { title = "Vision of Time", description = "You wish to hear how the Mag'har orcs joined the Horde? It may be one of the strangest ways we gained an ally!\n\nIt all began with a plan from Eitrigg. He had a fragment of the Vision of Time that Garrosh Hellscream used to travel to Draenor.\n\nChief Telemancer Oculeth believed there would be a way to go back to Draenor and get the Mag'har orcs to join the Horde.\n\nThis tale begins with a visit to Oculeth in Zuldazar...", objectives = "Meet with Chief Telemancer Oculeth in Zuldazar.", completion = "<name>, it is good to see you. I have been in need of an assistant to attune this fragment for some time now." }
WordHunterWoW_QuestEN[53467] = { title = "Caverns of Time", description = "Were the shard of the Vision of Time not depleted, I could use it to send you on your way. But my specialty is teleportation, not chronomancy.\n\nTime magic was the province of our former leader, Grand Magistrix Elisande. Much of her knowledge died with her.\n\nIt is said Elisande had mastered incantations known only to the bronze dragons. Perhaps they would be willing to aid your cause.", objectives = "Meet with Anachronos in the Caverns of Time.", completion = "Is it time for you to visit me already? Yes, I suppose it is then." }
WordHunterWoW_QuestEN[53476] = { title = "The Great Sea Scrolls", description = "<Dust falls from the scroll case as you retrieve it, revealing an ornate etching. The artwork, rendered with obvious care and skill, depicts a scene from a tortollan pilgrimage.\n\nThe container has spaces for twelve rolled scrolls, only one of which is occupied. A complete set would likely be quite valuable to a tortollan collector.>", objectives = "Collect a set of scrolls depicting the tortollan pilgrimage.", completion = "Oh my! Is that a complete set of the Ruinous Pilgrimage? With a first-generation scroll case to boot?\n\nWhy, I haven't seen one of those in decades! Here, here, I have a nice hat I acquired in a trade from a tall fellow some years ago. Said he was from \"up north\".\n\nDid I ever tell you the stories that my father's mother's father told me about the days of the pilgrimage? It all started with that scoundrel from... hey, where are you going?" }
