WordHunterWoW_QuestEN[53566] = { title = "Dark Iron Dwarves", description = "I can't thank ye enough, {name}. Without yer help, Ironfoe would be lost tae us and the Black Anvil could've ne'er been made whole.\n\nBut even more than that, ye've proven to every Dark Iron in the mountain what it means tae be part o' somethin' bigger. Tae be part o' the Alliance.\n\nThe time has come tae let King Anduin know that my people stand with him.", objectives = "Speak with Aysa Cloudsinger at the Stormwind Embassy to hear the end of this tale.", completion = "By securing the Dark Iron clan's commitment to the Alliance, you have brought renewed strength to our cause. \n\nQueen-Regent Thaurissan and I are both in your debt. Thank you, <name>." }
WordHunterWoW_QuestEN[53583] = { title = "Adapting Our Tactics", description = "For our best chance to win this war, we must continue to learn and adapt new strategies. There are opportunities for advancement all around us, but they require dedication and perseverance.\n\nI've collected a list of potential research opportunities for you to review. Any one of these might feel small on its own, but together they might just be all the advantage we need.\nLet me know which ones you would like us to pursue.", objectives = "Talk to Alleria Windrunner to start researching an upgrade.", progress = "Did you make a decision yet?", completion = "Excellent. We will see to it right away." }
WordHunterWoW_QuestEN[53602] = { title = "Adapting Our Tactics", description = "This war will not be won with strength and might alone. Take in your surroundings while you fight and turn it into an advantage against the enemy.\n\nI have a list of modifications for you to choose from. Any one of these might feel small on its own, but together they might just be all the advantage we need.\n\nLet me know what you would like us to pursue.", objectives = "Talk to Eitrigg to start researching an upgrade.", progress = "What is your decision?", completion = "Excellent. We will see to it right away." }
WordHunterWoW_QuestEN[53604] = { title = "Clearing Them Out", description = "They have amassed an army before us, {name}. But it is no matter. The Horde war machine will not be stopped.\n\nGo into The Master's Glaive and dispatch their warriors. Their sentinels. Any who would raise a blade against my soldiers. \n\nClear out the petty rabble that seeks to delay the inevitable.", objectives = "Slay Night Elf forces in The Master's Glaive.", completion = "We are one step closer to our goals." }
WordHunterWoW_QuestEN[53605] = { title = "A Glaive Misunderstanding", description = "The kaldorei have brought their siege weaponry to the field. They are currently using it to oppose mine.\n\nWe need these demolishers to reach Teldrassil if we hope to stand any chance of capturing it. Go and destroy their glaive throwers as swiftly as you are able.\n\nThey think they will stop my advance here. They are mistaken. Show them the gravity of their error, {name}.", objectives = "Destroy glaive throwers in The Master's Glaive.", completion = "This was an easy victory. Do not expect it to be this simple in the future. Malfurion will return with his forces, but until then let's press on." }
WordHunterWoW_QuestEN[53606] = { title = "Aggressive Inspiration", description = "Nothing rallies the Horde more than their banner standing in the ruin of an enemy stronghold.\n\nGo to Blackwood Den, take the territory there, raise the Horde banners and let none question our dominance over this land.", objectives = "Plant 3 Horde Banners in Blackwood Den.", completion = "This is not a time for subtle gestures." }
WordHunterWoW_QuestEN[53608] = { title = "Fueling the Horde War Machine", description = "You heard the warchief! We got Azerite shooting outta those ruins over there and night elves tryin' to snag it.\n\nGet to those ruins and collect some of the stuff. This whole attack is done for if the night elves get their hands on that Azerite!", objectives = "Collect Azerite from 6 Azerite Deposits.", completion = "That should do it! The night elves won't know what hit 'em." }
WordHunterWoW_QuestEN[53609] = { title = "A Very Clear Message", description = "The Alliance got to the Azerite here before us, the place is crawling with night elves!\n\nKill as many of them as you can see, we gotta make sure none of them deliver even an ounce of Azerite to the Alliance!", objectives = "Kill 10 night elf forces.", completion = "Whew, that was a close call. Those night elves shoulda just ran away when they had the chance!" }
WordHunterWoW_QuestEN[53610] = { title = "Driving Them Out", description = "This is it, {name}. \n\nLor'danel is all that stands in our way before we capture Darnassus and reclaim Kalimdor. \n\nRout the defenders. We cannot risk allowing a single enemy to escape until we have secured control over the World Tree.\n\nI want this place in order by the time the Warchief arrives.", objectives = "Slay 15 Lor'danel defenders.", completion = "This has almost been too easy." }
WordHunterWoW_QuestEN[53616] = { title = "Knives of the Forsaken", description = "Tread carefully. All is not as it seems. The butchers who did this still skulk within Astranaar.\n\nIf you find them, give them what they deserve, {name}.", objectives = "Slay 8 Forsaken Assassins in Astranaar.", progress = "Has justice been served upon Sylvanas's assassins?", completion = "It is no less than those filthy creatures deserved." }
WordHunterWoW_QuestEN[53617] = { title = "Mercy for the Mad", description = "The ruin wrought by the Horde is driving the children of the forest mad.\n\nChief among them are Blackwood furbolgs. They have given into the madness and are a threat to everyone. If left to their madness they could strike us from behind while our forces engage the Horde. \n\nIt pains me to ask this, but please, when you are in the Twilight Vale, put these creatures out of their misery before they endanger anyone else.", objectives = "Slay 10 frenzied Blackwood furbolgs.", completion = "It is a tragedy that so many furbolgs had to perish, but it was necessary. In their madness they could attack our own people leaving us fighting a battle on two fronts." }
WordHunterWoW_QuestEN[53619] = { title = "Azerite Denial", description = "This substance, Azerite, is hurting Onu... and the Horde seem eager to collect it for themselves.\n\nWe must not let that happen. Collect as much Azerite as you can find. Ensure the Horde do not retrieve it.", objectives = "Collect Azerite from 6 Azerite Deposits.", completion = "Excellent work... this Azerite is a powerful substance indeed. We must not allow the Horde to get their hands on it." }
WordHunterWoW_QuestEN[53621] = { title = "No Horde Allowed", description = "The Horde forces in this area are trying to collect as much Azerite as possible. No doubt they intend to weaponize it.\n\nSlay any Horde forces you can find. They must not be allowed to get their hands on this Azerite!", objectives = "Kill 10 Horde soldiers in Nazj'vel.", completion = "We will end the Horde's invasion, here and now. Without this Azerite, they cannot win." }
WordHunterWoW_QuestEN[53622] = { title = "Defending Lor'danel", description = "The Horde have invaded from the North! You must protect Lor'danel, {name}. \n\nHelp our forces push back this attack!\n\nI will try to intercept the Warchief. This is our final chance to stop her. Report to Commander Summermoon in my absence.", objectives = "Take out Horde forces in Lor'danel.", completion = "Your aid is welcome, but I fear the Horde is relentless. Their forces are not slowing down." }
WordHunterWoW_QuestEN[53623] = { title = "Battle for Azeroth Dungeon Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[53627] = { title = "A Gift of Azerite", description = "I think we got a handle on things here. You gotta bring all this Azerite back to Zarvik Blastwix at the main camp!\n\nHe's gonna know just how to use this stuff to really take down the Alliance.", objectives = "Deliver Azerite to Zarvik Blastwix in Blackwood Den.", completion = "Azerite! For me? You shouldn't have! \n\nJust kidding, of course you should have." }
WordHunterWoW_QuestEN[53641] = { title = "LFGDungeons - BFA - Stromgarde (Arathi)", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[53665] = { title = "Ready for Battle", description = "Greetings, {name}.\n\nOur recruits are eager to join you on the battlefield.", objectives = "Speak with Throk to recruit an ally from the Barracks.", progress = "Looking for a few recruits?", completion = "With our allies fighting by your side the battlefield is ours for the taking." }
WordHunterWoW_QuestEN[53666] = { title = "Armor Up!", description = "Ah, {name}. Word spreads quickly around here.\n\nUnfortunately, with all these orders coming in I can't afford to talk right now.\n\nIf you're interested in learning more about the armory Fennick can help you with that. He's just outside.", objectives = "Speak with Fennick to learn what the Armory has to offer.", completion = "What? Old Drom'kal's too busy for ya? I'm not surprised.\n\nAt least now that the armory's up and 'runnin' we can work on gettin' our allies some better gear." }
WordHunterWoW_QuestEN[53667] = { title = "Welcome to the Workshop", description = "You must be the new guy around here. Name's Margie. And that over there, that's Pixy.\n\nWe run a tight crew here at the workshop. So, if you ever need anything, you know where to find us.\n\nNow, I suggest you head on over and check in with Pixy. She can show you what we have to offer.", objectives = "Speak with Pixy Hackwrench to learn what the Workshop has to offer.", progress = "I'm workin' here.", completion = "Well that was quick!\n\nLike I said before, if ya need anything you know where to find us." }
WordHunterWoW_QuestEN[53668] = { title = "Flightgineer's Network", description = "Now that we control High Perch the skies are ours!\n\nI've laid out a few plans for expanding our routes in this here note. If you'd be so kind as to deliver it to our commander, I'm sure they'll be pleased with our progress.\n\nLet me know when you're ready and l'll send ya on your way.", objectives = "Deliver Flightgineer Krazzle's Note to your commander in Ar'gorok.", completion = "Our goblin friend assures me he is able to expand our travel network as long as we hold key positions.\n\nLooks like we've got our work cut out for us." }
WordHunterWoW_QuestEN[53669] = { title = "The Altar's Power", description = "Looks like construction on the Altar of Storms is complete.\n\nI'm sure Meredith would be more than happy to show you what mysterious powers lie within.", objectives = "Speak with Meredith the Crone to learn what the Altar of Storms has to offer.", progress = "Yea?", completion = "Huh. Would ya look at that.\n\nI can feel the energy comin' off that thing from here!" }
WordHunterWoW_QuestEN[53670] = { title = "Beasts of Newstead", description = "Nothing penetrates an enemy's front line like a fierce rider and a well-trained beast. Now that we control Newstead, one of our riders in particular has focused his efforts on training us a few kodos.\n\nGo, check in with Tanauk and find out what these beasts are capable of.", objectives = "Speak with Kodo Rider Tanauk to learn about the beasts he's been training.", progress = "What are you waiting for?", completion = "Powerful beasts, aren't they?" }
WordHunterWoW_QuestEN[53671] = { title = "The Circle's Power", description = "With the Circle of Elements under our control there are opportunities to harness the powers of the elements.\n\nKraga understands these powers quite well. I suggest speaking with her.", objectives = "Speak with Kraga Tidefury to learn what she has to offer.", progress = "Have you found what you were looking for?", completion = "Such power is not to be taken lightly." }
WordHunterWoW_QuestEN[53672] = { title = "Ready for Battle", description = "Welcome to the warfront, {name}.\n\nOur recruits are eager to join you on the battlefield.\n\nA good place to start would be Ralston. I'm sure he's got a few who could learn much fighting by your side.", objectives = "Speak with Ralston Karn to recruit an ally from the Barracks.", progress = "Looking for a few recruits?", completion = "With our allies rallying by your side on the battlefield I have no doubt we will remove the Horde threat from Arathi." }
WordHunterWoW_QuestEN[53673] = { title = "Armor Up!", description = "What've we got 'ere? A fresh, young lad lookin' ta help better prepare our allies fer battle? Well then, Jonathan's always lookin' for a bit o' help ta keep our armory orders in full swing.\n\nI'd offer ta walk ya over, but I've got me hands full here. Ye can find him just over yonder.", objectives = "Speak with Jonathan Flynn to learn what the Armory has to offer.", completion = "Hmm? Ah, yes.\n\nEverything in order? Armory resources looking good, yes?" }
WordHunterWoW_QuestEN[53674] = { title = "The Altar's Power", description = "With contributions in full swing it's no surprise the Altar of Kings was built with such haste.\n\nI suggest wandering over that way. You might be surprised to see what the Altar has to offer.", objectives = "Speak with Altarite Jesse Taylor to learn what the Altar of Kings has to offer.", progress = "Yes?", completion = "My goodness! What an incredible source of power." }
WordHunterWoW_QuestEN[53675] = { title = "Welcome to the Workshop", description = "Welcome to the workshop!\n\nI told Grumble I thought it best for me ta protect him from unnecessary distractions, but I think it may benefit all of us if ye get a peek at what we're doin' 'round here.\n\nWhy don't ye head on over and see what we have ta offer.", objectives = "Speak with Grumble to learn what the Workshop has to offer.", progress = "How can I help ye?", completion = "Ah, wonderful. I take it ye got a good look at our work." }
WordHunterWoW_QuestEN[53676] = { title = "The Circle's Power", description = "The Circle of Elements presents us with an opportunity to harness great power. One of our allies, Justine, has great knowledge into what this might mean for our efforts.\n\nSeek her out. It's time you discovered the power of the elements.", objectives = "Speak with Justine Frost to learn what she has to offer.", progress = "Discover anything?", completion = "The enemy stands little chance." }
WordHunterWoW_QuestEN[53677] = { title = "Beasts of Newstead", description = "Control of Newstead has allowed our forces to advance. It's also provided Vindicator Banra ample room to continue training his elekk for battle.\n\nI suggest you speak with him to learn more about what these magnificent beasts are capable of.", objectives = "Speak with Vindicator Banra to learn about the beasts he's been training.", progress = "Remain vigilant.", completion = "Truly magnificent. Don't you agree?" }
WordHunterWoW_QuestEN[53678] = { title = "Establishing a Connection", description = "Now that we control High Perch the skies are ours!\n\nI've drafted plans for a flight network that provides our allies safe passage. Please, take these notes and deliver them to our commander at once.\n\nI'm happy to provide you with a gryphon that will deliver you to the base when you are ready.", objectives = "Deliver Grayson's Note to your commander in Stromgarde Keep.", completion = "Excellent news. I've been assured retaining control of key battlefield positions allows our gryphons to soar through the skies without interruption to various locations.\n\nWe must press our efforts even further." }
WordHunterWoW_QuestEN[53699] = { title = "Gate Crashers", description = "", objectives = "" }
WordHunterWoW_QuestEN[53701] = { title = "A Drust Cause", description = "Horde armies are pushing into the heart of Drustvar. Hold the line and drive them back to the holes they crawled out of. Kul Tiras is ours!", objectives = "Repel the Horde forces assaulting Drustvar.", progress = "We cannot rest while the Horde assault Drustvar!", completion = "The Horde got what they deserved." }
WordHunterWoW_QuestEN[53704] = { title = "Not Too Sober Citizens Brigade", description = "", objectives = "" }
WordHunterWoW_QuestEN[53706] = { title = "Salvage the Supplies", description = "", objectives = "" }
WordHunterWoW_QuestEN[53707] = { title = "Smoke the Supplies", description = "", objectives = "" }
WordHunterWoW_QuestEN[53711] = { title = "A Sound Defense", description = "Horde forces are attacking Tiragarde Sound. Make them regret every footstep upon our soil!", objectives = "Repel the Hordes forces assaulting Tiragarde Sound.", progress = "The Horde dares to assault us here in Boralus?! Our response must be swift, massive, and merciless!", completion = "Everyone in Boralus cheered when we saw the explosions up on that airship! The Horde will think twice before assaulting Boralus again." }
WordHunterWoW_QuestEN[53712] = { title = "Unfriendly Skies", description = "", objectives = "" }
WordHunterWoW_QuestEN[53713] = { title = "Wet Work: Bridgeport", description = "", objectives = "" }
WordHunterWoW_QuestEN[53714] = { title = "Apothecary Jerrod", description = "", objectives = "" }
WordHunterWoW_QuestEN[53715] = { title = "Firewarden Viton Darkflare", description = "", objectives = "" }
WordHunterWoW_QuestEN[53716] = { title = "Eastpoint Emergency", description = "", objectives = "" }
WordHunterWoW_QuestEN[53717] = { title = "Hold the Highland", description = "", objectives = "" }
WordHunterWoW_QuestEN[53719] = { title = "Allegiance of the Zandalari", description = "It is decided, {name}.\n\nDe Zandalari will join de Horde.\n\nOur path together has been a long and difficult one. We have lost much together. De Horde has sacrificed for de Zandalari, and vice versa. I can do nothing to honor that commitment except pledge our loyalty.\n\nCollect your Warchief and send them to my throne. I will extend de offer myself.", objectives = "Bring the Zandalari into the Horde.", completion = "Without you, none of this would have been possible. You have done well, my champion." }
WordHunterWoW_QuestEN[53720] = { title = "Allegiance of Kul Tiras", description = "It is time for her maiden voyage, {name}.\n\nThis aptly named vessel will carry us and her crew across the vast sea to Stormwind Harbor. There we will meet Anduin and I will seal the pact we made so many moons ago.\n\nKul Tiras will stand with the Alliance so long as I am Lord Admiral.\n\nThank you for your assistance in this endeavor.", objectives = "Sail to Stormwind Harbor and present Anduin with his gift.", completion = "I accept this gesture in the spirit in which it was made, <name>.\n\nThe Kul Tirans have been valuable allies, and now we have a physical manifestation of that bond.\n\nI thank you for your continued support of the Alliance. We continue to grow with your aid." }
WordHunterWoW_QuestEN[53721] = { title = "Heritage of the Zandalari", description = "You have faced many challenges in your time among de Horde. You carried de pride of de Zandalari on your shoulders and triumphed!\n\nReturn to me. I wish to recognize de example you have set for us all.", objectives = "Meet Queen Talanji at the Golden Throne in Zuldazar City.", completion = "Wear dis armor with pride, <name>. You now stand among de greatest champions of de Zandalari." }
WordHunterWoW_QuestEN[53722] = { title = "Heritage of the Kul Tiran", description = "Gossip in Boralus has oft reached my ears of your exceptional conduct, {name}.\n\nMeet me before the keep. I wish to commend your efforts on behalf of Kul Tiras.", objectives = "Meet Katherine Proudmoore in Boralus.", completion = "Wherever the winds take you, know that you take the spirit of Kul Tiras with you.\n\nWear our colors with pride, <name>." }
WordHunterWoW_QuestEN[53724] = { title = "Shadow Hunter Mutumba", description = "", objectives = "" }
WordHunterWoW_QuestEN[53725] = { title = "A People Shattered", description = "While the monument here was intended to honor the fallen members of the Shattered Sun, it quickly took on a second meaning for the sin'dorei.\n\nIt was not far from here that we lost one of our greatest heroes: Anasterian Sunstrider, the last king of Quel'Thalas. He led our final effort against the Scourge and personally crossed blades with Arthas himself. As we remember the sacrifices it took to reclaim this land, we also remember the sacrifices made in its defense.", objectives = "Light the final flame.", progress = "Yes?", completion = "Never forget the lives that were lost here. Both to the Scourge, and to their own misguided kin." }
WordHunterWoW_QuestEN[53726] = { title = "Mechinations", description = "", objectives = "" }
