WordHunterWoW_QuestEN[53733] = { title = "Legion 110 A", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[53734] = { title = "Walk Among Ghosts", description = "Every year, we ask a champion of our people to perform an act of remembrance in honor of those who fell to the Scourge. Lady Liadrin has performed this ritual, as have I, among others. This year, I am honored to give the task to you.\n\n<The Regent Lord hands you an ornate lantern.>\n\nThis lantern carries a flame born of the Sunwell. I would ask that you bring it to locations that were significant to the fall of the Sunwell and of Quel'Thalas, and to light the memories we cannot forget.", objectives = "Meet Lor'themar in Tranquillien.", completion = "This land will never recover from the damage that was done here. But we lost so much more than land that day." }
WordHunterWoW_QuestEN[53735] = { title = "The First to Fall", description = "Arthas cut through the land itself to get to the Sunwell. The Dead Scar is a constant reminder of that desecration. Where it starts is where our first line of defense attempted to hold the Scourge at bay. It is where the first blood was spilled.\n\nIt was a slaughter.\n\nTake the lantern to the base of the Dead Scar, and use its light to reveal the memories of what happened there.", objectives = "Witness the fall of the first defenders.", progress = "Yes?", completion = "<Lor'themar stands quiet for a moment.>\n\nElor bindel felallan morin'aminor." }
WordHunterWoW_QuestEN[53736] = { title = "Lament of the Highborne", description = "The next memory...\n\nForgive me. For many of our people, it was when we realized death was coming for us.\n\nA memorial to a particular defender lies to the west, in the place of her home. The light there has no doubt attracted some of the area's lingering souls. Clear them out, and then relight the flame.", objectives = "Light the second memorial flame.", completion = "Sylvanas and the Farstriders sacrificed more than most of us. Sometimes I must remind myself of that fact, given the current state of affairs." }
WordHunterWoW_QuestEN[53737] = { title = "The Day Hope Died", description = "The Ranger-General fell just east of Fairbreeze Village, where she was holding the line to protect the civilians as they retreated to Silvermoon. If it wasn't for her, our people would number even less than we do now.\n\nShine the lantern upon the battlefield, and witness how her forces ultimately broke under Arthas's personal assault.", objectives = "Witness the fall of the Ranger-General.", progress = "<Lor'themar is silent.>", completion = "In the words of one of the more poetic retellings:\n\nAs her defenders fell, with anguish she cried, \"Shindu fallah na, Sin'dorei.\"\n\nShe was a true Ranger-General until her last breath. May Silvermoon never forget her bravery in life." }
WordHunterWoW_QuestEN[53738] = { title = "Defense of Quel'Danas", description = "With our best defenders defeated and the line broken, Arthas made quick work of Silvermoon's remaining forces and tore through the city.\n\nThis is where we part ways. I must return to Silvermoon before Halduron starts sending rangers to search for me.\n\nThe dragonhawk master in Fairbreeze Village has orders to fly you to Quel'Danas. Someone much more familiar with the events on the island will meet you there.", objectives = "Meet with Lady Liadrin in Quel'Danas.", completion = "Are you ready, <name>?" }
WordHunterWoW_QuestEN[53752] = { title = "Shell Outs", description = "", objectives = "" }
WordHunterWoW_QuestEN[53753] = { title = "Shell Outs", description = "", objectives = "" }
WordHunterWoW_QuestEN[53755] = { title = "Blight and Sound", description = "", objectives = "" }
WordHunterWoW_QuestEN[53759] = { title = "Look Out Below!", description = "", objectives = "" }
WordHunterWoW_QuestEN[53760] = { title = "Unintended Consequences", description = "<Xal'atath speaks once more.>\n\nThe servants of N'Zoth prepare for their master's return. They intend to conjure a scouring storm to wash away all unbelievers.\n\nThe particular ritual they will invoke requires three ancient artifacts. One of void, one of storm, and one of ocean.\n\nEven now, I hear the void relic calling to me. It is being empowered... or corrupted, I am not sure which. I see it upon a cliff, overlooking a vast sea.\n\nCome, {class}. We can find a much better use for such a prize.", objectives = "Find the Void Stone in Drustvar.", progress = "Yes... this form should do nicely.", completion = "Do not be distracted. We have more to do." }
WordHunterWoW_QuestEN[53761] = { title = "The Pirate's Treasure", description = "I sense another relic. A trident thought lost to the depths. It calls to me, {name}. Do you hear it too?\n\nIts song takes form. I see a harbor to the east. An ambitious pirate, greedy and proud. Completely unaware of the power hidden within her hoard of gold.\n\nThe would-be-captain's hubris will not permit her to simply hand over her prize. I fear she must be taught a rather harsh lesson.\n\nBut that is your specialty, is it not?", objectives = "Find the second relic.", progress = "Is the trident in your possession?", completion = "I never doubted you for a moment." }
WordHunterWoW_QuestEN[53762] = { title = "The Tempest Crown", description = "<Xal'atath breathes in deeply and smiles.>\n\nMy strength grows. I can see it clearly now... the third relic we seek. The crown known as Tempest Caller.\n\nHow fitting that after the fall of Atal'Gral, the gluttonous Toatana would be the one to find the artifact. He was always scuttling about the depths, seeking treasures for his collection.\n\nToatana's greed has left him trapped within a cave he can never leave. The crown awaits us there.", objectives = "Retrieve the third relic.", progress = "The crown is far more useful in our hands than in the claws of an oversized bottom-feeder.", completion = "Further proof that you and I can achieve great things together, <name>.\n\nSo many possibilities..." }
WordHunterWoW_QuestEN[53763] = { title = "Twist the Knife", description = "The relics are ours... as it was meant to be.\n\nThere is but one more step needed for the great truths to be revealed.\n\nThe naga sought to summon their storm from a place that echoes with ancient power. Though this site has had countless names over the ages, you mortals know it as the Precipice of Oblivion.\n\nI will go on ahead and begin preparations. Join me there.", objectives = "Meet Xal'atath at the Precipice of Oblivion.", progress = "We are so close now... to the end.", completion = "<Talanji listens to your tale of Xal'atath and N'Zoth.>\n\nZandalar is still reeling from de Old God's infestation in Uldir. If another rises...\n\nDis is troubling news indeed. Only together can we turn back dis tide." }
WordHunterWoW_QuestEN[53765] = { title = "His Eye Upon You", description = "Something dark has taken root within you, {name}. The tendrils of N'Zoth are burrowing into your mind and soul, eager to consume everything you are.\n\nI can perform a rite of cleansing, but only in a place that resonates with the very power that grips you. \n\nMeet me near the Crucible of Storms. The ritual will be perilous and painful, but it is your only chance to be free.\n\nThe Old God has eyes everywhere. I do not wish you to become one of them.", objectives = "Meet Brother Pike near the Crucible of Storms to cleanse your \"gift\".", progress = "There can be no treating with the darkness, <name>.", completion = "It is done. The darkness fades and your mind is once more your own.\n\nYou are free of N'Zoth's influence. Let us hope he does not seek to take hold of you again." }
WordHunterWoW_QuestEN[53766] = { title = "His Eye Upon You", description = "<Talanji seems to regard you with concern.>\n\nDark mojo has fallen upon you, {name}. I can sense de tendrils of N'Zoth delving deep into your mind.\n\nDis evil must be purged... before it claims your very soul!\n\nGo to de Altar of Akunda in de Terrace of de Chosen. Seek out Nailok, one of de priests of Akunda. He is your best chance to be cleansed of de wicked curse dat grips you.", objectives = "Seek out Nailok at the Altar of Akunda in the Terrace of the Chosen.", progress = "Are you ready to be free?", completion = "Dat was some baaaaaad mojo gripping your mind, hero. But Akunda's power proved even stronger!" }
WordHunterWoW_QuestEN[53768] = { title = "Furious Fracas", description = "", objectives = "" }
WordHunterWoW_QuestEN[53769] = { title = "Furious Fracas", description = "", objectives = "" }
WordHunterWoW_QuestEN[53771] = { title = "Gurin Stonebinder", description = "", objectives = "" }
WordHunterWoW_QuestEN[53772] = { title = "Zagg Brokeneye", description = "", objectives = "" }
WordHunterWoW_QuestEN[53773] = { title = "Naga Attack!", description = "", objectives = "" }
WordHunterWoW_QuestEN[53774] = { title = "Wisdom of the Warchief", description = "Champion. For a brief moment after the battle with G'huun, the spirit of our old warchief, Vol'jin, appeared in view of all in Zuldazar.\n\nI had a hundred questions to ask my old friend, but his spirit faded before I could muster my voice.\n\nI have asked Talanji to perform her seance once more, so that I might speak with the spirit of Vol'jin.\n\nWill you collect the Glaive of Vol'jin from its resting place at the base of the pyramid and then join us at Zanchul?", objectives = "Meet Princess Talanji in the Hall of High Priests at Zanchul.", progress = "Have you brought the glaive?", completion = "Baine has been an excellent advisor in dese trying times. It is my honor to aid him in his search for answers." }
WordHunterWoW_QuestEN[53775] = { title = "Shades of Disruption", description = "Vol'jin's spirit is a slippery one. I have asked Master Gadrin and Spiritwalker Ebonhorn to aid us in calling him forth.\n\nDis ritual will not be easy, and I ask you to be on your guard should anything other than Vol'jin appear.", objectives = "Assist in the ritual to summon Vol'jin's spirit.", completion = "Ya know you be askin' a good question when someone be tryin' to have you killed for askin' it." }
WordHunterWoW_QuestEN[53776] = { title = "To the Broken Shore", description = "Da Broken Shore be where I fell in battle. We were overrun, demons everywhere. Sylvanas was doing what she could, but Thrall was down and I had fallen. It was horror.\n\nAnd now I need ya to take me back dere. Take me glaive to da battlefield, call to me, and I will come. Perhaps if I be in da spot where me blood was spilled, we might shine some light on dis mystery.", objectives = "Take the Glaive of Vol'jin to Spiritwalker Ebonhorn at the Broken Shore.", completion = "I may be ancient by your standards, but I lack the raw power Talanji wields. You may wish to stand back, as this will be the first time I have attempted to conjure a spirit that was this powerful." }
WordHunterWoW_QuestEN[53777] = { title = "Where He Died", description = "Dis time, I need to bring ya to my side.\n\nWe gonna walk da shadows between life and death, see if we can't uncover some clues.\n\nBe careful, {name}, and be armed. Not everything on dis side wants us to find answers.\n\nPrepare yourself, den speak with me when ya be ready.", objectives = "Walk the shadows with Vol'jin.", progress = "I not be scared away so easily. What dey gonna do, kill me again?", completion = "Dis be leavin' me with much to ponder." }
WordHunterWoW_QuestEN[53778] = { title = "Where He Fell", description = "Dis be da spot, mon. Dis be where da Legion led our forces into a trap and drove a blade into me belly.\n\nSylvanas pulled me from da ruin of da battlefield. She saved da Horde dat day. Come, let us walk around dis place and see what we can learn from da echoes of da past.", objectives = "Search the Screaming Cliffs with the Spirit of Vol'jin.", completion = "Somethin' was definitely helpin' our enemies dat day. But who or what could dat have been?\n\nDa loa were silent and their powers were gone, as if I'd lost their favor.\n\nWith so much death, I be havin' one person in mind who might be behind it." }
WordHunterWoW_QuestEN[53779] = { title = "The Lies of a Loa", description = "Hidden memories, spirits attackin' us for investigating, and a long road of bodies in da wake of me makin' Sylvanas warchief.\n\nI be thinkin' it time ya speak with Ol' Bwonsamdi. Odd as it sounds, dis don't seem like his style. Dat don't mean he not be behind it.\n\nYa best work with Talanji. From what little I been seein', da death loa got a soft spot for her highness. You can confront Bwonsamdi at his necropolis in Nazmir. Just... be respectful.", objectives = "Meet Talanji at the Necropolis in Nazmir.", completion = "We must be very careful. Bwonsamdi may be fond of humor, but his wrath toward those who disrespect him is de stuff of legends." }
WordHunterWoW_QuestEN[53780] = { title = "Jailor of the Damned", description = "I be havin' many rivals when it comes to claimin' souls. But it takes some serious mojo to do to Vol'jin what ya describe. Dat kind of power smells of old magic.\n\nIcecrown. It be more dan a pretty throne. It be an anchor dat holds dis world to da next, ya might say.\n\nI gonna open a death gate, and ya can go through and ask da Lich King if he be treadin' on Ol' Bwonsamdi's ground.", objectives = "Confront the Lich King.", progress = "Mind ya step. Ya be dancin' between powers dat may do more dan just kill ya.", completion = "Ha ha. Ya should be careful when dealin' with da forces of death." }
WordHunterWoW_QuestEN[53781] = { title = "Eyir", description = "Not many got da stones or da mojo to take what be mine. Ol' Bwonsamdi always be gettin' his share.\n\nDa way Talanji be tellin' it, Vol'jin's spirit may be gettin' help from some other power. And dere be few who love to mess with souls like Eyir. A meddlin' one she be, with her wings and her valor.\n\nYa best be seein' her in person. She be found in her vault at Skold-Ashil. And ya best not mention me name, or she might be sendin' ya back to me faster dan any death gate.", objectives = "Meet Talanji at Skold-Ashil in Stormheim.", completion = "Dis is a strange land. De spirits feel different here." }
WordHunterWoW_QuestEN[53782] = { title = "Mysteries of Death", description = "Hmph. Well, da Lich King and dat bossy val'kyr not be me only rivals. But dey were da ones most likely ta be behind all dis. Someone be playin' with very ancient mojo.\n\nTell Vol'jin's spirit dat da answers he be lookin' for not be found in da world of da living. He gonna need to go beyond da veil ta learn what needs knowin'.\n\nDere be some places on dat side only he can go.", objectives = "Speak with the Spirit of Vol'jin.", completion = "So, to da Other Side den. Where I be goin', da livin' not be followin'. If it be in me power, I gonna send word of what I find. \n\nMind yaself in da days to come. If I be readin' Baine's words right, I tink da Horde gonna have a mighty need of a hero like you soon enough." }
WordHunterWoW_QuestEN[53783] = { title = "In the Dunes", description = "This schematic you found is encrypted. My tools are no good on it, not without risking the integrity of the data.\n\nHowever, I do know a guy who can definitely crack this cookie: Mr. Dataguru Gryzix.\n\nIf I remember correctly, he's been vacationing on a beach in Vol'dun since the war broke out. Something about not getting the recognition he deserves. \n\nAnyways, I am sure you can convince him to help you.", objectives = "Find Dataguru Gryzix at The Forgotten Marsh in Vol'dun.\n\nProvided item:", completion = "Ugh, what do you want?" }
WordHunterWoW_QuestEN[53784] = { title = "Siege Engineer Krackleboom", description = "", objectives = "" }
WordHunterWoW_QuestEN[53787] = { title = "Modular Construction", description = "The Abandoned Junkheap is home to some seriously deadly gnomish constructs. These constructs contain Mecha-Cores which could come in handy for crafting the Ub3r-Spanner. Legend has it that it could forge creations unlike anything we've ever seen!\n\nYou look like the adventurous type, {name}. Can you go scrap up some mechs?\n\nDon't forget your Arclight Spanner!", objectives = "Kill mechanical constructs in the Abandoned Junkheap and salvage 8 Mecha-Cores with an Arclight Spanner." }
WordHunterWoW_QuestEN[53791] = { title = "The Pride of the Sin'dorei", description = "{name}, Lor'themar Theron has requested your presence in Silvermoon.\n\nHe's asking for your assistance with a ceremony of great importance.", objectives = "Speak with Lor'themar in Silvermoon City.", completion = "Ah, <name>, just in time." }
WordHunterWoW_QuestEN[53800] = { title = "Battle for Darkshore", description = "", objectives = "" }
WordHunterWoW_QuestEN[53801] = { title = "Battle for Darkshore", description = "", objectives = "" }
WordHunterWoW_QuestEN[53802] = { title = "Sethrak Persuasion", description = "Let me see the schematic...\n\nYeah, yeah, alright. I can help you.\n\nI am going to need a few things to power my decoder.\n\nI need a way to channel electricity from the air around us. What better than to steal...I mean borrow some lightning rods from the sethrak that have been trying to steal my tech for weeks now!\n\nI'm sure you'll have to do some \"convincing\", but you seem like a pretty convincing {race}.", objectives = "Collect Faithless Lightning Rods in the Scalefang Outpost.", progress = "I need those rods to do my work, <name>.", completion = "Perfect, this should be enough to power my decoder.\n\nNow we're cooking with lightning!" }
WordHunterWoW_QuestEN[53804] = { title = "Dinomancer Zakuru", description = "", objectives = "" }
WordHunterWoW_QuestEN[53805] = { title = "A Friend in Needle", description = "You can see me?\n\nOh, thank goodness! I thought I was lost in the folds of time...again!\n\nBut for one to see through the folds of time's fabric... you must be a very talented tailor, indeed.\n\nWould you bring me some cloth, then, tailor? I believe I'll be able to place just when I am with your help and right myself.", objectives = "Collect 5 Tidespray Linen and 5 Deep Sea Satin.", progress = "When in Azeroth am I...?", completion = "You're back! That was fast...or, was it?" }
WordHunterWoW_QuestEN[53806] = { title = "Heavy is the Head", description = "Okay, I am going to need one more thing from you.\n\nThe sethrak leader, Warlord Surgios, has been a real pain for me.\n\nHe stole my mind enhancer. I can't do my work without it.  It will make me be able to think much more clearly, and make less...deadly mistakes.", objectives = "Collect the Goblin \"Mind Enhancer\" from Warlord Surgios in the Scalefang Outpost.", progress = "Do you have my mind enhancer?", completion = "Haha! Take that Surgios! \n\nLook how cool this thing is! You can see why its so precious now." }
WordHunterWoW_QuestEN[53807] = { title = "A Stitch in Time", description = "Hm...I don't know that I've ever been to this time, before.\n\nI suppose I should explain myself. My name is Delormi, and I'm the last remaining member of the Synchronous Tailors.\n\nWe make sure the fabric of time stays, well, mended. But I've found a number of new tears cropping up.\n\nIn fact, I believe that's why I've arrived here in this time. Perhaps you could assist me in tracking them down and repairing them?", objectives = "Assist Delormi in repairing the Tears in Time.", progress = "Something strange is happening. These tears have become too frequent as of late.", completion = "And that takes care of those, although...Something's still wrong..." }
WordHunterWoW_QuestEN[53808] = { title = "Crawl To Victory", description = "", objectives = "" }
WordHunterWoW_QuestEN[53810] = { title = "The Severed Thread", description = "Do you see that? There's a corpse just ahead.\n\nTo think the caverns have been so badly overrun...\n\nWe should look at the bodies. Maybe there will be something of use to us.", objectives = "Investigate the corpses in the Caverns of Time.", completion = "An ominous portent, isn't it?" }
WordHunterWoW_QuestEN[53811] = { title = "Children's Week", description = "Thank you for coming by to celebrate Children's Week, {class}. You are going to make one little boy very happy!\n\nTake this whistle. With it, you will be able to call for the child you have agreed to take care of this week. It will serve no use after Children's Week ends, as is custom.\n\nWhen you are ready, use the whistle and meet your new ward! I know he is ecstatic to meet you.", objectives = "Use the Kul Tiran Orphan Whistle to call for the ward that you will be looking after during Children's Week.\n\nProvided item:", completion = "Whoa, are you a <class>? That's amazing! My name's Liam!\n\nI'm so, so excited to leave the city. I haven't been outside the gates since I was really little.\n\nMiss Westerson says that we should think about what we want to be when we grow up, but how can I choose when there are so many cool things you can be?!\n\nCan you take me to meet people I've heard stories of? I think meeting grown ups like you might help me decide!" }
WordHunterWoW_QuestEN[53812] = { title = "A Carefully Laid Trap", description = "", objectives = "" }
WordHunterWoW_QuestEN[53813] = { title = "Rolling Up the Sleeves", description = "The Caverns of Time? Strange... I spent many timelines in this very place.\n\nWhat's special about here-- now?\n\nWe'll have to discern as much later on. It looks like we aren't the only ones who've been affected by these rifts...\n\nLet's do the Bronze Dragonflight a favor and clear out these anomalies.", objectives = "Kill 12 Chronal Anomalies.", completion = "It seems no matter when one is, there's always something to fight..." }
WordHunterWoW_QuestEN[53814] = { title = "First Sergeant Steelfang", description = "", objectives = "" }
WordHunterWoW_QuestEN[53815] = { title = "Whatever Happened to Saffy Flivvers?", description = "When Azerite was discovered, my friend Saffy was sent to investigate what it could do. There was an attack and we all thought she'd died. Then it turns out she was forced to work in some kind of goblin think tank in Tanaris! But before we could get her out, the whole place exploded.\n\nNow, my bosses have written her off as dead. But she wasn't dead the first time so I'm not sure she is now. I've been told not to go looking for her, but you could take a look.\n\nFind Saffy, or what's left of her?", objectives = "Search for signs of Sapphronetta Flivvers in Tanaris", completion = "<You find the charred pieces of some mechanical contraption. A parrot, maybe? It isn't Saffy Flivvers, but it's evidence of her work. Perhaps there are more clues to be found in the area.>" }
WordHunterWoW_QuestEN[53816] = { title = "Some Reassembly Required", description = "<The word \"Feathers\" has been etched onto the broken mechanical creature -- the sort of thing the person you are looking for might have created. Collecting the pieces and recreating the mechanical construct will surely give you a clue as to their fate. \n\nThe area is crawling with Venture Co. scavengers and goons. Their pockets are probably filled with mechanical bits you could use to fix Feathers.>", objectives = "Collect Mechanical Parts from Venture Co. personnel.", progress = "<You seem to have collected all the pieces.>", completion = "<The pieces go together with some judicious use of applied force and acerbic verbal encouragement. Hopefully the extra pieces you have on hand weren't critical.\n\nThe mechanical parrot now hovers unevenly over the sand.>" }
WordHunterWoW_QuestEN[53817] = { title = "Whatever Happened to Grizzek Fizzwrench?", description = "When this whole Azerite mess began I had a goblin named Grizzek Fizzwrench do some research for me. He was bad for business and had to be removed from the picture. I thought it was a done deal, only now I'm hearing maybe he's not so dead.\n\nI need you to hunt this guy down and see what happened. If he's alive, eliminate him and I'll add the standard mercenary fee to your reward.", objectives = "Search for signs of Grizzek Fizzwrench in Tanaris.", completion = "<You find the charred pieces of some mechanical contraption. A parrot maybe? It isn't Grizzek Fizzwrench, but it's evidence of his work. Perhaps there are more clues to be found in the area.>" }
WordHunterWoW_QuestEN[53818] = { title = "Re-parrot", description = "<Though very damaged, and filled with insects, you can tell Feathers seems to have some sort of recall program. \n\nFixing the mechanical bird and following it back to the source may bring you to the person you seek.\n\nYou were able to put the thing back together. How hard could debugging a mechanical parrot be?>", objectives = "Debug Feathers' recall program.", completion = "<Debugging Feathers involved actual bugs. Gross. But the mechanical creature seems to be moving better.>\n\nHello! Systems operating within normal parameters! Hello!\n\n<Feathers looks at you, awaiting input.>" }
WordHunterWoW_QuestEN[53819] = { title = "Return to the Nest", description = "<You decide to activate the recall subroutine. Perhaps the parrot will lead you to the person you are looking for.>", objectives = "Activate the recall subroutine.", completion = "Feathers! You put him back together!\n\nThat's wonderful but... If you could find us then so can others." }
WordHunterWoW_QuestEN[53820] = { title = "She's in a Happier Place", description = "Aww, Kelsey...she's been such a good friend. I meant to let her know I was alive eventually, but I got distracted.\n\nAzerite, the war, the near-death experience... We've been really busy. Being presumed dead has some advantages, though. We've done a lot of research and we just need a better lab-\n\nOkay. New plan.  Tell Kelsey we'll be in touch, but only Kelsey. Tell everyone else I'm dead - for now. If you keep quiet about Grizzek, you- you can have Feathers.\n\nDo we have a deal?", objectives = "Return to Kelsey Steelspark in Boralus.", completion = "She's alive?! That's great! I can't wait to catch up and see what she's been working on. I wasn't always a fan of Grizzek's -- he could really grind Saffy's gears! But if they're together again, then it's a packaged deal. Hmmmmm.\n\n<Kelsey looks thoughtful for a moment before a sly grin spreads across her face>\n\nI have an idea or two. You don't worry about a thing, <name>. Enjoy the parrot!" }
WordHunterWoW_QuestEN[53821] = { title = "He's Dead, Jastor", description = "Hey, uh, so I got a good thing goin' on here, and I really don't want Gallywix to know I'm alive.\n\nI'll make you a deal. You spin some story about how you only found tiny pieces of me spread across Tanaris and that I am totally dead, and... And you can keep the bird.\n\nDeal?", objectives = "Return to Gazlowe in Zandalar Harbor.", completion = "Nice work convincing Gallywix, <name>. If I didn't know any better I'd have thought Grizzek was actually dead.\n\nHe's alive right? Right.\n\nAnyway, here's your bonus pay. Let's just keep this between us, okay?" }
WordHunterWoW_QuestEN[53823] = { title = "A Queen's Entourage", description = "Princess Talanji was very clear in her orders.\n\nYou, {name}, are to join her at de steps of Zanchul. She wishes to have you at her side while she undergoes de rite of queens and kings. I hope you can comprehend what an honor that is.\n\nDe queen-to-be will explain what it is you are to do.\n\nNow go, and Pa'ku's winds make you swift.", objectives = "Meet Princess Talanji at the Zocalo.", completion = "There you are. I am glad you could make it, <name>.\n\n\n\nI am eager to show you how my people celebrate such an occasion." }
WordHunterWoW_QuestEN[53824] = { title = "The Rite of Kings and Queens", description = "Now that you are here, we can begin this sacred rite.\n\nTake your place beside Talanji, {name}. She has chosen you for an important task. I will explain while we make our way to Zanchul.", objectives = "Ride in procession with Princess Talanji.", progress = "Your have more than earned such an honor, <name>.", completion = "Such an occasion warrants a great deal of ceremony, <name>. Do not worry- there is plenty for you to do while Talanji prepares for what is to come." }
WordHunterWoW_QuestEN[53825] = { title = "The New Zanchuli Council", description = "These are sobering developments {name}.\n\nI wish to speak to my priests about what has transpired. I would like you to continue into de depths of Zanchul and up de steps into de Council Chambers. There you will find de new council I have assembled.\n\nGreet them, and make note of my choices. I hope you will find them adequate.", objectives = "Greet the Zanchuli Council.", progress = "What do you think of my choices, <name>?", completion = "I arm myself with de knowledge and wisdom of others in ways my father did not. I hope it is enough." }
WordHunterWoW_QuestEN[53826] = { title = "The Instigator Among Us", description = "This situation can be swiftly dealt with if we take out de one that incited this violence.\n\nI heard reports of an enforcer rousing de vagrants and drudges against de shopkeepers and guards in de Zocalo.\n\nOne of my own would not do this without cause. See if you can determine de reason for this sudden change.\n\nI am told her name is Malzon. I hope for her sake that she surrenders.", objectives = "Confront Enforcer Malzon in the Zocalo.", completion = "If I understand de situation correctly, her concerns did not arise by chance. Be wary, <name>." }
WordHunterWoW_QuestEN[53827] = { title = "The Council Has Spoken", description = "Now that you see who I have chosen for my council, it is time to receive their blessing.\n\nIt is a symbolic demonstration of support, but I believe there is power in words as well as deeds. When they declare themselves to me, de eyes of de loa are also upon them.\n\nI hope they like what they see, {name}. I know I do.", objectives = "Receive the Zanchuli Council's blessing.", completion = "I will not dwell now on de White Widow's words, but I am not dismissing her criticisms out of hand. I only wish she had chosen to speak to me instead of attacking from de shadows.\n\nWe could have worked together to solve de many problems of de Zandalari." }
WordHunterWoW_QuestEN[53828] = { title = "Gaze of the Loa", description = "My council has given their blessing and we have dealt with an enemy. All that remains is to face de judgment of my loa.\n\nI do not know what this part will be like. My father never spoke of it, at least not to me.\n\nWalk with me. I will explain what is expected of you through this final trial.", objectives = "Follow Talanji.", completion = "I trust you will restain yourself where you can, <name>. It is important that I overcome these trials on my own." }
WordHunterWoW_QuestEN[53830] = { title = "Queen of the Zandalari", description = "De loa have seen fit to grant me de crown. My council accepts me. My priests have given their blessing. My people have expressed their displeasure, but I am determined to right those wrongs.\n\nIt is time to accept de responsibility of leadership. I will address them and speak on our future. I would be honored if you would take a place at my side while I do so.", objectives = "Witness Talanji's ascension to Queen of the Zandalari.", completion = "I am resolved to bring our people together, <name>." }
WordHunterWoW_QuestEN[53831] = { title = "A Royal Occasion", description = "You wish to hear how the Zandalari joined the Horde? My people have had a... difficult history with the Zandalari.\n\nHowever, I believe we dealt with the Zandalari of the past. The now Queen Talanji is much different from her father.\n\nI'm rambling, my apologies. Our tale begins after the Alliance sacked the city of Zuldazar and killed King Rastakhan.\n\nThe Horde had been invited by the then Princess Talanji to witness her coronation in Zuldazar...", objectives = "Meet the Zandalari emissary at The Great Seal in Dazar'alor.", completion = "There you are. De ceremonies are about to begin. De princess has requested your attendance at de steps of Zanchul." }
WordHunterWoW_QuestEN[53832] = { title = "Counter-Sabotage", description = "", objectives = "" }
WordHunterWoW_QuestEN[53833] = { title = "Vengeful Venture", description = "<You pick up the note and deduce that the Venture Co. are the killers of Dataguru Gryzix. You search his corpse, and find that his decoder and the Ub3r-Spanner schematic have been stolen.\n\nYou need to retrieve his decoder and the schematic and bring them back to Shuga Blastcaps to have any hope of crafting the Ub3r-Spanner.\n\nThat mech you have following you should prove itself useful.>", objectives = "Locate the Venture Co. camp, then retrieve Gryzix's Decoder and the Encrypted Ub3r-Spanner schematic.", progress = "What's up, <name>? Did Gryzix handle that schematic for you?", completion = "He's dead? Poor sap, he was a damn fine engineer.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[53835] = { title = "Something Valuable, Perhaps?", description = "<The tablet is too worn to be read. While some of the characters are legible, reading the tablet will be impossible without assistance.\n\nYou can discern only a single word: Aegrim.>", objectives = "Bring the tablet to Brann Bronzebeard in the Hall of Explorers in Ironforge.", completion = "You know I love a good artifact!" }
WordHunterWoW_QuestEN[53836] = { title = "Ancient Armor, Ancient Mystery", description = "By my beard! Do you know what this is?! It's an ancient tablet that describes how to forge the Bulwark of the Mountain King!\n\nThe last one to wear that armor was Aegrim Bronzebeard, my ancestor and thane of the Bronzebeard clan.\n\nTalk to Advisor Belgrum. He'll know more about Aegrim's past, and might be able to shine some light on the legends of his armor.", objectives = "Speak to Advisor Belgrum in Old Ironforge.", completion = "You were wise to come to me. I think I can help!" }
WordHunterWoW_QuestEN[53837] = { title = "Watch Yer Back", description = "Aegrim, you say? Bulwark of the Mountain King? Well, if we are going to start anywhere, it has to be Aegrim's study. The entrance lies below us in the depths of Old Ironforge.\n\nThe only trouble is the troggs in our way. How about you take the lead?", objectives = "Kill 8 Trogg Invaders and Roc'maw the Burrower in Old Ironforge.", completion = "The guards will tend to sealing the tunnels. We have important work to do." }
WordHunterWoW_QuestEN[53838] = { title = "Keep Yer Feet On The Ground", description = "{name}! The Explorers League is setting up a new exhibit in the Hall of Explorer.\n\nA team of dwarves went in search of new artifacts to display in it.\n\nThey headed off to Gol'Bolar Quarry in Dun Morogh, but haven't returned. Would you mind checking in on them?", objectives = "Search Gol'Bolar Quarry for the missing excavation crew.", completion = "<The team seems to have been guarding this dwarven tablet.>" }
WordHunterWoW_QuestEN[53839] = { title = "Aegrim's Study", description = "This leads to Aegrim's study. I still have some scrolls to sort, so I will leave you to search the study at your leisure.\n\nI'm sure Brann would be most interested in any of your findings.", objectives = "Search Aegrim's study for the Bulwark of the Mountain King.", completion = "<The armor stand is empty.>" }
WordHunterWoW_QuestEN[53840] = { title = "Interest Yah In A Pint?", description = "The armor may be shattered, but there's still hope. With the fragments you found, we might be able to forge it anew.\n\nThis is far outside my area of expertise, but there may be someone who can help. We should speak with Grumnus Steelshaper. He retired to Thelsamar in Loch Modan.\n\nGo on ahead, I'll meet you there.", objectives = "Find Grumnus Steelshaper in Loch Modan.", completion = "Brann filled me in on what happened. This tablet will certainly help guide us." }
WordHunterWoW_QuestEN[53841] = { title = "Shards of the Past", description = "<The armor that once was here has mysteriously shattered. Pieces of the ancient armor are scattered around the room.>", objectives = "Collect the shattered pieces of armor.", progress = "What do ye have here?", completion = "The armor is shattered? Hmmm..." }
WordHunterWoW_QuestEN[53842] = { title = "Earthen Blessing", description = "Ignis will help with smelting the metal, but the heat from the forge will cook you in yer boots!\n\nOur ancestors, the dwarves who forged Aegrim's armor, could sustain their stoneform for far longer than we can today. That's how they could forge the bulwark in the first place.\n\nLuckily, my friend Bouldercrag can help us with that. He'll need some materials for the ritual.", objectives = "Find the Remnant of the Earthen Ritual in Old Ironforge.", progress = "Do you have it?", completion = "This will suffice." }
WordHunterWoW_QuestEN[53843] = { title = "The Ub3rlode", description = "Looks like Gryzix's suspicions were correct. Not only is it the Venture Co, but it's Mogul Razdunk himself! \n\nWe now owe it to not only ourselves as engineers, but the Horde proper to secure the recipe before he can craft it! \n\nGo to Kezan, <name>. Stop Mogul!You will receive:", objectives = "Complete The MOTHERLODE!! on Heroic Difficulty and obtain the recipe from Mogul Razdunk." }
WordHunterWoW_QuestEN[53844] = { title = "Recruiting the Furnace Master", description = "Grumnus says we're going to need some help smelting this metal. I just happen to know someone who's perfect for the job.\n\nWe're heading to Ulduar!\n\nYears ago, we fought against a construct named Ignis the Furnace Master. I've heard tell that the titan keepers brought him back, and Ulduar's furnace is alive once more.", objectives = "Recruit Ignis the Furnace Master to help smelt the metal.", progress = "It's been a long time since I've been in Ulduar.", completion = "With Ignis's help, we're one step closer to reforging this armor!" }
WordHunterWoW_QuestEN[53845] = { title = "Forging the Armor", description = "It's time to begin. Bouldercrag, Ignis, and I are here to assist you.\n\nYou'll be the first dwarf to forge the Bulwark of the Mountain King in generations. This ol' blacksmith is honored to be able to witness this.\n\nAre ye ready?", objectives = "Forge the Bulwark of the Mountain King.", progress = "Is it done?", completion = "I never thought I'd see the day." }
WordHunterWoW_QuestEN[53846] = { title = "Legacy of the Bronzebeard", description = "You must present this armor to Muradin at once! This is an historic day for the dwarven people.\n\nThis isn't just a suit of armor, it's a symbol of our heritage.", objectives = "Present the Bulwark of the Mountain King to Muradin Bronzebeard in the High Seat.", completion = "<name>, you have long been a champion for the dwarven people. Your acts of valor and bravery will be sung in these halls for ages.\n\nI can see no other <race> more deserving to wear this armor than you." }
WordHunterWoW_QuestEN[53847] = { title = "On Whispered Winds", description = "{name},\n\nI have need of you.\n\nMaiev and Shandris are en route to Stormwind to petition King Wrynn for aid in retaking Darkshore.\n\nYou have proven a loyal ally to my people in times past. I ask that you join their audience with the king and lend your voice to our cause.\n\nI suspect we shall meet again soon.\n\n-Tyrande", objectives = "Meet Maiev Shadowsong and Shandris Feathermoon in Stormwind Keep.", completion = "I suspected Tyrande might reach out to you once she heard of our intentions." }
WordHunterWoW_QuestEN[53848] = { title = "Tooling Around Vol'dun", description = "Okay, {name}. We got almost everything we need. Almost.\n\nYou see, I lost my toolbox. I must have dropped it while running from the sethrak a couple days ago. Can ya fetch it for me? I'm not a very good engineer without my tools!\n\nAnd take a mech with ya. I've spied some mysterious dwarven and troll figures lurking around...  better not be the Venture Co. One whiff of the schematic being here and we got trouble.\n\nYou'll need the mind enhancer for it to follow you. Just put it on and you'll be good to go!", objectives = "Put on the Goblin \"Mind Enhancer,\" then retrieve Gryzix's toolbox.", progress = "<Gryzix appears to be dead.>", completion = "<You place the toolbox on the ground, next to his corpse.>" }
WordHunterWoW_QuestEN[53849] = { title = "Waning Hope", description = "The kaldorei have been steadfast members of the Alliance since the end of the Third War. We have fought on distant shores and even on different worlds without protest.\n\nIt is curious that in our moment of need, their resources are stretched too thin to lend so much as a single blade.\n\nWrynn has already denied Tyrande aid. Witness it for yourself.", objectives = "View Tyrande's audience with Anduin Wrynn.", progress = "This will not stand.", completion = "Nothing a human king says will deter Tyrande now, but he still has the chance to act." }
WordHunterWoW_QuestEN[53850] = { title = "Our War Continues", description = "The work to stop the Alliance is far from over, {name}. But thanks to you, we have the methods necessary to break them.\n\nThe Abyssal Scepter has been delivered to King Rastakhan, earning us more of his favor.\n\nThere is a matter of greater importance that I would speak to you about... but not here.\n\nMeet me aboard the Banshee's Wail within Zuldazar.", objectives = "Speak with Sylvanas Windrunner aboard the Banshee's Wail in Zuldazar.", completion = "Derek Proudmoore's corpse will serve us well. In the meantime, we have more work to do." }
WordHunterWoW_QuestEN[53851] = { title = "Our War Continues", description = "The work to stop the Alliance is far from over, {name}. \n\nKing Rastakhan now possesses the Abyssal Scepter that you recovered from the Kul Tirans. He has placed it... in his treasury. \n\nThe Dark Lady wishes to speak with you regarding the corpse you found at the bottom of the ocean. Derek Proudmoore.", objectives = "Speak with Sylvanas Windrunner aboard the Banshee's Wail.", completion = "Our plans are in motion to bring down the Alliance and their allies.\n\nWe have much to do." }
WordHunterWoW_QuestEN[53852] = { title = "Azerite Denied", description = "The Kul Tirans and Alliance are amassing a vast amount of their Azerite and Azerite weapons within Tiragarde Sound.\n\nThey have a new supply of the resource, thanks to the Kul Tirans' conquest over Lady Ashvane and her company.\n\nWe must strike at their supplies of Azerite and destroy these weapons, or else we will be behind in this war.\n\nYou and Zelling will travel to Tiragarde Sound and meet with Rexxar. Lead the assault on their Azerite supply.\n\nAnd do not return until you are victorious.", objectives = "Meet Rexxar in Tiragarde Sound.", completion = "<Rexxar nods.>\n\nYou're here. Our strongest warriors are eager to attack the estate.\n\nLet's not keep them waiting." }
WordHunterWoW_QuestEN[53853] = { title = "The Setting Sun", description = "Remember the Sunwell.\n\nWe ride into battle with those words for a reason. We lost so much that day...\n\nI lost so much that day.\n\nShine the lantern on the southern side of the island, where the Dead Scar meets the sea. There you will see how the fall of the Sunwell began. And with it, the last act of the High Elves.", objectives = "Witness the fall of Anasterian.", progress = "Is it done, champion?", completion = "One final task remains." }
WordHunterWoW_QuestEN[53856] = { title = "The Fury of the Horde", description = "The Norwington Estate has a large cache of Azerite, along with the Alliance's latest Azerite weapons.\n\nWe need to steal these weapons and all of their Azerite. Every weapon stolen is a Horde life saved.\n\nWhen you are ready to strike, let me know. I shall signal our warriors to begin the assault.\n\nThe Alliance and Kul Tirans will see the true might of the Horde!", objectives = "Command the Horde army to attack Norwington Manor.", progress = "The Alliance will see our might.", completion = "Our forces have the Kul Tirans pushed back. The hunt begins!" }
WordHunterWoW_QuestEN[53857] = { title = "Cap'n Gorok", description = "", objectives = "" }
WordHunterWoW_QuestEN[53858] = { title = "Step Into Her Shoes", description = "Another one of those rifts. Normally I'd repair it, but given the circumstances I wish to see where it leads.\n\nIt isn't often I commune with versions of myself from other threads of time. But one particular self has been a dear friend for some time.\n\nI feel myself growing weaker. If she perishes...\n\nWe don't have much time. We need to enter this rift now.", objectives = "Enter the Time Rift with Timeweaver Delormi.", progress = "We must hurry--I fear the worst, otherwise.", completion = "What...what's happening?!" }
WordHunterWoW_QuestEN[53859] = { title = "The Mountain Folk", description = "All Kul Tirans are really tough, but the Roughnecks are the roughest and toughest of them all!\n\nThey can wrestle gryphons with their bare hands! They can knock down a yeti with a single punch!\n\nI wanna meet a Roughneck and prove that I can be really strong like them! Can you take me to their camp? I've heard it's up in the mountains by Anglepoint.", objectives = "Take Liam to meet the Roughnecks at the Roughneck Camp in Tiragarde Sound. Make sure to call for him if he is not present when you get there.", progress = "I'm gonna be big and strong and eat raw goat with my teeth!", completion = "Did you hear that?! He said I could be a Roughneck!\n\nI'm gonna eat a lot of food so I can be big and strong like he is!" }
WordHunterWoW_QuestEN[53861] = { title = "Yo Ho, Yo Ho!", description = "The orphan matron is always telling us what to do! Study your books, practice your words, behave in public...\n\nWhat if I want to be a pirate when I grow up? A scourge of the high seas! Finding buried treasure, dueling my enemies on the mast, wearing cool hats!\n\nPirates never come into Boralus, so I've only ever heard stories. I wanna meet a real one! Can you take me to Freehold? I'll practice my pirate voice on the way.\n\nYARRRRR!", objectives = "Take Liam to meet a pirate outside of Freehold in Tiragarde Sound. Make sure to call for him if he is not present when you get there.", progress = "Yo ho, yo ho!", completion = "Look at my new hat! What a nice pirate man." }
WordHunterWoW_QuestEN[53862] = { title = "The Squid Shrine", description = "Sometimes tidesages come to the orphanage and tell us about the sea and how they can talk to it.\n\nI wanna talk to water!\n\nWe've gone on field trips to their monastery here in Boralus, but I heard their home in Stormsong is much more impressive. Can you take me to go see it? I heard there's a great view from the Brineworks!", objectives = "Take Liam to see Shrine of the Storms from the beach near Mariner's Strand in Stormsong Valley. Make sure to call for him if he is not present when you get there.", progress = "The tidesages always say that the water talks to them. How does it talk without a mouth?", completion = "That tidesage was so mysterious! Do you know him?\n\nI wanna be mysterious like him! He could make water tornadoes! He even said the water talked to him! How cool is that?!\n\n... I'm all wet now." }
WordHunterWoW_QuestEN[53863] = { title = "Bird Friends", description = "My best friend at the orphanage is named Billy. He's just a kid like me, though. I heard that some people in Drustvar have FALCONS as their best friend.\n\nHow cool is that?!\n\nCan we go meet a falconer? Pretty please? I want to have a bird friend too.\n\nI hear there's a big statue in Arom's Stand of some dead guy who was friends with birds. Maybe we can find a falconer there!", objectives = "Take Liam to see the statue of Arom Waycrest at Arom's Stand in Drustvar. Make sure to call for him if he is not present when you get there.", progress = "I wish I had feathers like a bird!", completion = "Hmm...\n\nI think the first step to being a friend to birds is to stop chasing seagulls and start feeding them instead!" }
WordHunterWoW_QuestEN[53864] = { title = "Shapeshifters!", description = "Being a human is alright and all, but what if I could be a BEAR?\n\nDruids can be bears. And cats! And who knows what else!\n\nI've heard rumors of druids in the mountains of Drustvar. It would be so cool to meet one. I wanna see them turn into animals! Maybe they can teach me, too!", objectives = "Take Liam to meet a druid at Ulfar's Den in Drustvar. Make sure to call for him if he is not present when you get there.", progress = "Roar! Growl! Bear sounds!", completion = "Can you take me back here sometime? That game sounds pretty fun!" }
WordHunterWoW_QuestEN[53865] = { title = "Return to the Orphanage", description = "This has been the best Children's Week ever!\n\nI was scared to grow up, but now I'm really excited! There are so many cool things I can be!\n\nBut how can I choose?\n\nI think it's time for you to take me back to the orphanage, {name}. I'll think about what I want to be when I grow up on the way.", objectives = "Bring Liam back to the orphanage in Boralus. Make sure to call for him if he is not present when you get there.", progress = "What a great trip!", completion = "I've had so much fun with you, <name>! Thanks for bringing me all over Kul Tiras!" }
WordHunterWoW_QuestEN[53866] = { title = "If The Shoe Fits...", description = "That thing is killing her...it's killing *me*!\n\nWe need to stop it!\n\nPlease, I need your help to save my self!", objectives = "Stop the Shade of Delormi from killing Magistrix Delormi.", progress = "Please, we need your help!", completion = "This can't be...why is this happening?!" }
WordHunterWoW_QuestEN[53867] = { title = "Engineer Bolthold", description = "", objectives = "" }
WordHunterWoW_QuestEN[53868] = { title = "Saving Nine", description = "I saw her in there, destroying another part of my timeline.\n\nWith every thread she severs, I lose myself more and more...\n\nPerhaps I will perish, but I won't let her ruin the fabric of time.\n\nI need you to join me one last time. \n\nI can only end this with your support.", objectives = "Enter the Time Rift.", progress = "We can't fail. Not with what's at stake.", completion = "This is the end, tailor. I will suffer this no longer." }
WordHunterWoW_QuestEN[53869] = { title = "Killing Time", description = "Now, {name}, stand with me.\n\nI am weak. So many threads have been severed.\n\nI'll use what power I have left to mend the rift.\n\nPlease...make sure the fabric of time is safe from her.", objectives = "Kill the Infinite Shade of Delormi.", progress = "Please...I need your help!", completion = "So it's done, then. The final thread is severed." }
WordHunterWoW_QuestEN[53870] = { title = "Guests at Grommash Hold", description = "{name}, I've received word that a vulpera caravan has arrived at Grommash Hold. They wish to address the Horde and have requested your presence.\n\nI'm afraid it is not the best time for guests, so please see them as soon as you are able.", objectives = "Meet your guests within Grommash Hold.", completion = "I'm glad you've come, <name>. \n\nYou should be the first to hear what we have to say." }
WordHunterWoW_QuestEN[53874] = { title = "End Their Vigil", description = "", objectives = "" }
WordHunterWoW_QuestEN[53875] = { title = "Fogsail for a Day", description = "", objectives = "" }
WordHunterWoW_QuestEN[53877] = { title = "Eastpoint Encounter", description = "", objectives = "" }
WordHunterWoW_QuestEN[53878] = { title = "Emergency Extrication", description = "", objectives = "" }
WordHunterWoW_QuestEN[53879] = { title = "Cleaning Out the Estate", description = "We must keep moving forward. Our goal is to weaken the Alliance, destroy their weapons, and steal their Azerite.\n\nThe three of us will carve a path of destruction through our enemies. Let us go!", objectives = "Weaken the Norwington Estate defenders.", progress = "Do not give in to the Alliance!", completion = "The Alliance and Kul Tirans are no match for our forces!" }
WordHunterWoW_QuestEN[53880] = { title = "Machines of War and Azerite", description = "The Norwington Estate... I remember taking walks here with my wife and children.\n\nSorry, this isn't the time for remembering an old life.\n\nThe Alliance have Azerite bombs and rifles scattered throughout the estate. I believe our goal is to recover them.\n\nIf only the Alliance hadn't chosen to use the estate as a testing ground... this was meant to be a place of peace.", objectives = "Recover 4 Azerite bombs and 3 Azerite rifles.", progress = "Is it done?", completion = "I wish the Kul Tirans did not try to bring the Norwington Estate into this madness... but here we are." }
WordHunterWoW_QuestEN[53881] = { title = "Cut from the Same Cloth", description = "My Infinite self was right. I can no longer mend time.\n\nToo many of my threads have been purged. I can feel no others.\n\nI'm alone now. And my thread is gone. But not you.\n\nTake this recipe. You've proven yourself a talented tailor in your own time, and a savior in so many more.\n\nThe fabric of time needs your hands to mend it. I trust you with that responsibility.\n\nTalk to me when you're ready. I'll take you back to when this all began.", objectives = "Ask Timeweaver Delormi to return you to your time." }
WordHunterWoW_QuestEN[53882] = { title = "Writing on the Wall", description = "Long has the southern wall separated Quel'Thalas from the once great kingdom of Lordaeron. We did not believe that anyone could breach it. That overconfidence was our undoing. \n\nWhen the Scourge arrived, the gate was not conquered by force. It was willingly opened by a traitor.\n\nThough caught unaware, every Farstrider, soldier, and magister in the area rushed to the defense of our homeland. Very few of them returned home. The gates now stand as a memorial in their name.", objectives = "Light the first memorial's flame.", progress = "Take the time you need.", completion = "And now to walk their path." }
WordHunterWoW_QuestEN[53883] = { title = "Shores of Zuldazar", description = "Alliance forces are attacking Zuldazar. Make them regret every step taken on our soil!", objectives = "Repel the Alliance forces assaulting Zuldazar.", progress = "The Alliance dares to assault us in Zuldazar?! We must crush these fools so cruelly and so swiftly that they never consider this again.", completion = "Attacking Zuldazar was unusually arrogant, even for the Alliance.\n\nThank you for personally showing them how poor of a choice that was. Our Zandalari allies will be reassured of our commitment to them, and inspired by our show of force in their defense." }
WordHunterWoW_QuestEN[53885] = { title = "Isolated Victory", description = "Alliance forces are pushing deeper into Vol'dun. We can not allow this aggression to go unchecked!", objectives = "Repel the Alliance forces assaulting Vol'dun.", progress = "The vulpera appreciate the Horde's protection here. I didn't realize the Alliance could be so... relentless.", completion = "On behalf of all the denizens of Vol'dun, thank you for your help in pushing back the Alliance invaders.\n\nThe people here have suffered enough threats without the Alliance adding to the list.\n\nWe will not forget the Horde's sacrifice here, nor yours." }
WordHunterWoW_QuestEN[53886] = { title = "Self Guided Tour", description = "", objectives = "" }
WordHunterWoW_QuestEN[53887] = { title = "War Marches On", description = "I hope the Horde will think twice about attacking Kul Tiras in the future, but given the actions of its leadership, it is a faint hope at best. Still, what matters most is my people are safe now.\n\nThe fleet and marines should be here soon to help the Outriggers clear out what remains of the Horde forces. Please return to High Commander Wyrmbane and let him know I will join everyone as soon as I am able.\n\nThank you for your swift actions today, {name}.", objectives = "Return to Halford Wyrmbane on the Wind's Redemption.", completion = "A successful operation, indeed. I'm glad we have Lady Jaina back among the members of the Alliance. We've done our best together but the added power of the Kul Tiran fleet, and their new Lord Admiral, may be just what we need to push this campaign forward." }
WordHunterWoW_QuestEN[53888] = { title = "To Anglepoint", description = "An attack on Anglepoint Wharf can only mean one thing: the Horde seeks to destroy the seagate there. \n\nThis is my home. These are my people. I cannot turn my attention to our operations in Zandalar until we've routed the Horde.\n\nThe military will take a little time to mobilize, but in the meantime you and I can face these monsters. If we can't stop them, we can slow them down.\n\nWar has come to my shores once more. I will not stand aside.", objectives = "Accompany Jaina Proudmoore to Anglepoint Wharf and assist her there.", progress = "The Horde has overrun the area. We cannot let this continue.", completion = "As I suspected, they're trying to establish a foothold and take out the seawall." }
WordHunterWoW_QuestEN[53889] = { title = "A Declaration of Intent", description = "Our caravan is ready to explore the world beyond the sands, but Nisha's blade can't be our only defense against the dangers we know await us. \n\nThis is why we've come. \n\nTo declare our intent to join the Horde.", objectives = "Witness Kiro's declaration to join the Horde.", completion = "I am disappointed with his answer, but not surprised. \n\nOur strength is often overlooked." }
WordHunterWoW_QuestEN[53890] = { title = "New Allies, New Problems", description = "Baine certainly has his hands full. Taking on new allies means taking on new problems. \n\nLet us find out what troubles those within the Horde and see what we can do to help. \n\nPerhaps when Baine isn't so overwhelmed, he'll be able see our true value.", objectives = "Find out what troubles Commander Dresh, Bladeguard Sonji, and First Arcanist Thalyssra.", progress = "Let us find out what troubles those within the Horde and see what we can do to help.", completion = "Good work, <name>. Sometimes others just want to be heard." }
WordHunterWoW_QuestEN[53891] = { title = "No Problem Too Small", description = "These problems might seem small, but they will eat away at the Horde over time if they remain unaddressed. \n\nWe must offer our help. \n\nThe vulpera are skilled at solving problems, no matter their size.\n\nI will investigate the outpost. Nisha and Meerah will see to the others.\n\nMeet me in the Twilight Highlands when you're ready.", objectives = "Meet Kiro in Twilight Highlands.", completion = "Abandoned, just like Commander Dresh said." }
WordHunterWoW_QuestEN[53892] = { title = "Where Are the Workers?", description = "Look at this axe, {name}. There's still sweat on the hilt. The workers were here not too long ago. \n\nLet's see if Sasha can track their scent.", objectives = "Find out where the Crushblow Peons went.", progress = "This must be the place.", completion = "The peons are revolting? I'm surprised it took this long..." }
WordHunterWoW_QuestEN[53893] = { title = "A Little Goodwill", description = "It sounds like the peons are feeling undervalued. They do important work for the Horde, but their diligence is often overlooked. A little goodwill would go a long way. \n\nLet's plan a feast in their honor. We'll need quite a bit of meat to sate their enormous appetites, luckily, I have a totem that can help with that.   \n\nYou acquire the ingredients, and I will make a meal guaranteed to boost morale.", objectives = "Collect 100 Saber Flanks, 100 Worg Meat, and 100 Clucker Tidbits.", progress = "Did you bring the meat?", completion = "We'll be eating well tonight, <name>." }
WordHunterWoW_QuestEN[53894] = { title = "Worthwhile Repairs", description = "The peons are right. These tools are inexcusable. \n\nHow can they be expected to complete a job without the proper tools for their trade?\n\nI can make the needed repairs, but I'll need some ore first.", objectives = "Collect 15 Twilight Ore so Kiro can repair the peon's tools.", progress = "Have you found any ore?", completion = "I can work with this." }
WordHunterWoW_QuestEN[53895] = { title = "Peon Promotions!", description = "I agree with the plight of the peons. They should be rewarded for the work they do.\n\nIt's unlikely that the Horde will agree to increase their wages, but there's no reason they can't be given a promotion. \n\nAny title other than peon would help build some confidence.", objectives = "Give promotions to a few of the Crushblow Peons at Peon Hideout.", progress = "Have the peons been promoted yet?", completion = "I am sure your praise means a lot to the peons." }
WordHunterWoW_QuestEN[53896] = { title = "Stand Fast", description = "The Horde will pay for what it has done, but first I have to attend to the people here. \n\n{name}, I need to hold a portal open so the injured can evacuate to Boralus.\n\nKeep the Horde's forces off me while the wounded get to safety. We can deal with them once the civilians are safe.", objectives = "Protect Jaina Proudmoore.", progress = "That's the last of the wounded.", completion = "If the attackers didn't know we were here before, they know now." }
WordHunterWoW_QuestEN[53897] = { title = "A Party in Your Honor", description = "I think I have everything needed to make tonight a success. \n\nWe just need to make sure the peons show up.\n\nTell their leader that the Horde is throwing a party in their honor. \n\nI'm sure they won't decline a night of free food and drink.", objectives = "Inform Foreman Magrok that the Horde is throwing a party for the peons.", completion = "It's a success, wouldn't you say?" }
WordHunterWoW_QuestEN[53898] = { title = "Strength and Honor", description = "Those peons certainly look happy, don't they? I have no doubt they'll return to work in the morning. \n\nHowever, if their leader goes unchallenged, there will always be risk of revolt. \n\nYou need to face him to battle. \n\nShow him the true strength of the Horde, but also the honor that comes with showing mercy.", objectives = "Battle Foreman Magrok, showing both strength and honor.", progress = "Why don't you go show Foreman Magrok the true strength of your Horde?", completion = "As the peons would say: job's done." }
WordHunterWoW_QuestEN[53899] = { title = "On the Outskirts", description = "If things are settled for the Commander, you should check in on Nisha. \n\nI'm sure she could use your help.", objectives = "Find Nisha on the southern coast of Zuldazar.", completion = "Sonji was right to be worried. \n\nThe naga are planning an attack, but I've got a plan to stop them in their tracks.\n\nWe need to work fast, though." }
WordHunterWoW_QuestEN[53900] = { title = "We'll Use Their Weapons", description = "We're going to need special weapons to take down Tidecaller Nezara. Good thing it looks like the naga have plenty. \n\nWe'll use their weapons against them. You and I know a thing or two about that. \n\nGrab an assortment. We'll need more than one.", objectives = "Collect 10 Nazeshi Weaponry from forces within Dreadpearl Shallows.", progress = "You got those weapons?", completion = "Plenty to choose from. Perfect." }
WordHunterWoW_QuestEN[53901] = { title = "Explosions Always Work", description = "The area surrounding Tidecaller Nezara is heavily guarded, so I'll need you to create a distraction. \n\nTake these explosives. Plant them on the naga's harpoon launchers. Once they've been detonated, the blast should be more than enough to send the guards running!", objectives = "Place Volatile Explosives on naga Harpoon Launchers, and then detonate them to create a distraction.", progress = "A fiery distraction is just what we need!", completion = "You sure do excel at blowing things up!" }
WordHunterWoW_QuestEN[53902] = { title = "Taking Out the Tidecaller", description = "Nezara's shield might be down, but that doesn't mean she's defenseless. \n\nThere's a brute by her side that may cause trouble. I'll take a stab at him so you can take down the Tidecaller.", objectives = "Kill Tidecaller Nezara.", completion = "You do good work, <name>. Always a pleasure." }
WordHunterWoW_QuestEN[53903] = { title = "Meet with Meerah", description = "It appears we're making good progress.\n\nWould you meet up with Meerah?\n\nI want to be sure she's found her way to the vintner in Suramar.", objectives = "Find Meerah within Suramar's Twilight Vineyards.", completion = "Vintner Iltheux has some serious staffing issues." }
WordHunterWoW_QuestEN[53904] = { title = "The Vintner's Assistants", description = "Vintner Iltheux oversees all arcwine production for the Horde. \n\nHe's used to making wine himself, but the Horde sent in help to speed up the process. \n\nIt's had the opposite effect. \n\nWe need to get to the bottom of this. \n\nHow about you tour the vineyards and see how things are running? I have a few more questions for the vintner.", objectives = "Speak to Micah Broadhoof, Boss Mida, and Nomi.", progress = "Have you had a chance to see how things are running?", completion = "It sounds to me like we've found our problem." }
WordHunterWoW_QuestEN[53905] = { title = "Playing to Their Strengths", description = "Iltheux isn't properly utilizing the help he's been given.\n\nLet's fix that.\n\nAssign new roles to the workers, ones more suited to their strengths.\n\nIf you need suggestions, I'm happy to help.", objectives = "Assign new roles to Micah Broadhoof, Boss Mida, and Nomi.", completion = "Vintner Iltheux seems pleased. You've really got a knack for this, <name>!" }
WordHunterWoW_QuestEN[53906] = { title = "Fermented for the Horde", description = "Vintner Iltheux's recipe doesn't need much improvement. \n\nSome unique ingredients and slight modifications to the winemaking process is all that's needed. \n\nI'm thinking adding fermented firebloom should do the trick. Then, filter it though a special cloth made from silkwing fibers. \n\nThere are plenty of silkwings roaming the vineyard, and I have no doubt that Boss Mida can acquire the flowers, for a price.", objectives = "Collect the needed ingredients to create a wine worthy of the Horde.", progress = "Together, we will make a wine worthy of the Horde.", completion = "Excellent work, <name>. This will do just the trick." }
WordHunterWoW_QuestEN[53907] = { title = "Sip and Savor", description = "I think we're making wine, {name}!\n\nLet's see if the vintner approves of our vintage. \n\nTake a sample to Iltheux and see what he thinks.", objectives = "Deliver a sample of Nomi's Wine to Vintner Iltheux and gain his approval.", progress = "I hope he likes the wine.", completion = "I think our work here is done!" }
WordHunterWoW_QuestEN[53908] = { title = "Awaiting Our Arrival", description = "Let's head back to Orgrimmar.\n\nI'm sure Kiro's expecting us. \n\nWe really shouldn't make him wait.", objectives = "Return to Grommash Hold within Orgrimmar.", completion = "<name>, I have done the vulpera a disservice. \n\nI am afraid my oversight may have cost the Horde a notable ally." }
WordHunterWoW_QuestEN[53909] = { title = "Besieged Allies", description = "Seawalls can be rebuilt, but lives are lost for good. We need to secure the rest of the people here first.\n\nThe Outriggers have been known as some of the fiercest hunters in these waters. Find their leader, Rosaline Madison, and enlist her aid in liberating Anglepoint. Together, clear the north shore of the Horde, save anyone in danger, and rally the dock workers.\n\nYou handle the north shore, {name}. I will handle the south. We'll meet in the middle and crush the Horde between us.", objectives = "Find Rosaline Madison.", completion = "You and the Lord Admiral are a sight for sore eyes, <name>." }
WordHunterWoW_QuestEN[53910] = { title = "Repel the Horde!", description = "The Horde has overrun Anglepoint, killing my people and destroying their livelihoods. Its raiders have come to Kul Tiras with killing on their minds. I cannot allow that to happen.\n\nSlay any Horde Axe Throwers or Berserkers you see on the north shore. I will do the same on the south. Together we will stop this invasion.", objectives = "Defeat Horde Axe Throwers or Berserkers on the north shore of Anglepoint Wharf.", completion = "I can see the Horde's ranks have thinned quite a bit.\n\nI'm sure the Lord Admiral will be pleased. I know I am. Not bad, mainlander." }
WordHunterWoW_QuestEN[53912] = { title = "The Hunt Never Ends", description = "We have our victory, but we must move quickly to take the remaining Azerite from the estate.\n\nOur forces should already be moving the Azerite from the manor into our gyrocopter support.\n\nLet us move and ensure we get every ounce of Azerite away from the Alliance.", objectives = "Travel to the Norwington manor.", completion = "We have our Azerite, but something doesn't feel right. The cannoneers should have been here by now." }
WordHunterWoW_QuestEN[53913] = { title = "With Honor", description = "The Alliance and Kul Tiran forces are in disarray. I can hear the Azerite tank powering up.\n\nLieutenant Cole intends to fight us... now that his forces are destroyed.\n\nLet me know when you are ready to fight. The three of us shall destroy this tank while our warriors watch on!", objectives = "Defeat Lieutenant Cole.", progress = "Are you ready?", completion = "It is over. Cole, at least, died with some honor." }
WordHunterWoW_QuestEN[53914] = { title = "Murder at the Brawl'gar Arena", description = "The Brawl'gar quartermaster lies dead in front of you. He was murdered in broad daylight!\n\nHe must have been assassinated while someone was fighting in the arena. Maybe even during one of your fights.\n\nPerhaps there are some clues nearby as to who might have killed him.", objectives = "Investigate the scene of the crime.", completion = "So, you took it upon yourself to investigate the murder? Interesting...\n\n<Commander Ravenhide jots something down, looks up at you, and then finishes writing his notes.>" }
WordHunterWoW_QuestEN[53915] = { title = "Put Up Your Dukes", description = "You know what?\n\n<The commander puts his notebook away.>\n\nI COULD use a good {class} on my investigations team. We've had some personnel issues lately and, frankly, I can use all the help I can get.\n\nBut first: why don't you go hop into the arena for a few fights so I can get a good look at your skills?", objectives = "Win any 3 fights in the Brawl'gar Arena.", completion = "While you were fighting, I took the liberty of looking into your background a bit, <name>. Quite impressive, I must say.\n\nI apologize for my earlier suspicions. Welcome to the team." }
WordHunterWoW_QuestEN[53916] = { title = "Outrigger Outfitters", description = "My people met the Horde head on when they arrived, but we've been scattered over the wharf. The Horde has been relentless. We haven't been able to form a solid resistance force using just our fists as weapons.\n\nBut now the Lord Admiral is here with the champion of the Alliance. That's just the spark we need to rise up and kick these sorry mongrels out of our lands. If you can get my men some weapons, they'll join the fight!\n\nFind those weapons and meet me back here. I'm working on a plan.", objectives = "Recover 10 Outrigger Weapons.", progress = "For Kul Tiras! For the Lord Admiral!", completion = "Now that my people are able to fight back, I have a plan to help stop more of these savages from fouling up my nice wharf." }
WordHunterWoW_QuestEN[53917] = { title = "Undercover Agent: Sharisanda", description = "Pit Boss Buxdoggle is one of our primary suspects in this case. Buxdoggle is an infamously aggressive speculator, and has a list of debts a mile long.\n\nHe may be in need of money, which is consistent with the evidence you found earlier.\n\nSharisanda has taken point on the case. I'd like you to assist her. I think you'll work well together.", objectives = "Report to Sharisanda in the Brawl'gar Arena.", completion = "<name>? Sharisanda. Pleased to make your acquaintance.\n\nBuxdoggle is over dere, with de ridiculous hat on him.\n\nNo, no... don't just stare right at him! We're undercover, bonehead." }
WordHunterWoW_QuestEN[53918] = { title = "The Financial Participation Incentive", description = "I see Buxdoggle running some sort of game over dere. Getting people to guess de fight's winner in exchange for Brawler's Gold.\n\nSee if you can figure out how his game works. If you win enough money from him, he might start talking...", objectives = "Win 100 Brawler's Gold from Pit Boss Buxdoggle's guessing game.\n\nIf the game is not currently active, anyone can activate it by purchasing a High Roller's Contract from Tiana Nevermorn.", progress = "Lookin' to make some gold, bub?", completion = "Say, <name>, was it? You're not half bad at this! You'll put me in the poor house if you keep this up!" }
WordHunterWoW_QuestEN[53919] = { title = "Shots Fired", description = "Horde invaders keep sailing in through the seagate, but we have a nasty surprise for them!\n\nThe Outriggers are good at fighting monsters of any sort, the Horde included. We'll keep them off you while you take out their boats.\n\nSend 'em to the bottom of the harbor!\n\nFor Kul Tiras! For the Lord Admiral!", objectives = "Destroy Horde Motorboats.", progress = "That will hold the Horde for now.", completion = "We've stopped the tide of Horde. Now we can address the goblin sappers." }
WordHunterWoW_QuestEN[53920] = { title = "A Favor for Your Ol' Pal Buxdoggle", description = "Hey, listen, I was thinkin' about somethin'...\n\nYou know how you won all that money from me? Well, funny story, that may have been slightly more money than I actually have, and now some very powerful people want to break my elbows and my knees.\n\nI can't pay 'em! I'm broke! Heh heh!\n\nAll I need to get out of this hole is for you to lose your next fight. Flop like a fish. Please.", objectives = "Lose a fight in Brawl'gar Arena.", progress = "Please, ya gotta help me! They said they're gonna break my money bone! I don't even know where that is!", completion = "Thanks, <name>. You're a real pal." }
WordHunterWoW_QuestEN[53921] = { title = "The Pit Boss's Debts", description = "I'm not too proud to commit a few acts of violence to set a wrong right. And you know what's wrong? I'm out of money!\n\nOnly one person's won more gold from me than you have, and his name's Lord Sylysthrel. Real skeezy guy. I think he was cheating.\n\nSure would be nice if I could get that gold back...", objectives = "Obtain a Huge Pile of Legitimately-Earned Brawler's Gold from Lord Sylysthrel.\n\nYou can challenge Lord Sylysthrel by purchasing his Challenge Card from Card Trader Ami.", progress = "Once I get back the gold I lost, then I can REALLY start gambling!", completion = "<Buxdoggle stares, misty-eyed, at the huge pile of money.>\n\nI just love gold. There ain't NOTHIN' I wouldn't do to get my hands on gold. Ya hear me? Nothin'." }
WordHunterWoW_QuestEN[53922] = { title = "Evidence Packet: Pit Boss Buxdoggle", description = "I heard everything. That goblin sure does talk loudly about his crimes and debts, doesn't he?\n\nIt sounds like we have enough to bring him in for questioning. I've put together a packet of evidence for Commander Ravenhide to review.\n\nGood job out dere.", objectives = "Bring the Evidence Packet to Commander Arlu Ravenhide.", progress = "Find anything on Buxdoggle?", completion = "<Commander Ravenhide looks over the evidence.>\n\nThis is more than enough to get a warrant. Excellent work, <name>. But your job's not over yet." }
WordHunterWoW_QuestEN[53923] = { title = "Undercover Agent: Stone Guard Mollivox", description = "I believe you've met one of my other agents: Stone Guard Mollivox. She's investigating our second suspect: Shadowmaster Skrizzik.\n\nYou'll find Mollivox near the arena's entrance.", objectives = "Speak with Stone Guard Mollivox at the Brawl'gar Arena.", completion = "<name>? Mollivox. Nice to meet you. Again.\n\nSkrizzik's over there. You go take point, I'll hang back and jump in if things get ugly." }
WordHunterWoW_QuestEN[53924] = { title = "Soul Splinters", description = "<Skrizzik mumbles to himself.>\n\nOh dear, oh dear... it's getting hungry again. Where am I going to find enough souls to feed it? Ohh... if only I could get my hands on some of those brawler's purses...\n\n<He notices you.>\n\nOh! Hello there! Pay no attention to the mindless babbling of an innocent warlock. Nothing suspicious going on here!", objectives = "Search inside Brawler's Purses for something \"soul\"-related.\n\nBrawler's Purses are awarded to victors in the Brawl'gar Arena. Some types of purses may be more lucrative than others.", progress = "Oh dear, oh dear... must not let it get too hungry...", completion = "These... these might help! They'll help me with... my problem that I have. That I can't tell you about." }
WordHunterWoW_QuestEN[53925] = { title = "Super Soul Splinters", description = "<Skrizzik mutters to himself again:>\n\nWill these be big enough, though? It gets SO hungry for souls, and when it doesn't get enough, it gets angry, and we definitely don't want to trigger a void apocalypse in the middle of Orgrimmar. Oh dear, oh dear...\n\n<He notices you lingering.>\n\nOh! The {race} is still here! Heh heh. Never mind me! Nothing evil going on here!!", objectives = "Obtain 3 Super Soul Splinters from Rumbler's Purses, which are rewarded from winning rumbles.\n\nRumbles are large group fights that pit all players in the Brawl'gar Arena queue against a challenging enemy. Anyone can start a rumble by purchasing a Rumble Card from Tiana Nevermorn.", progress = "<Skrizzik looks around the arena in a panic.>\n\nWhere can I find more souls? Maybe the quartermaster sells some? Oh, right, he's dead. Hmm...", completion = "These... are... PERFECT!\n\nNow if you'll please give me some privacy, I have some completely harmless |cFF0000FFshadow magic|r to perform. Goodbye!" }
WordHunterWoW_QuestEN[53926] = { title = "Cause for Concern", description = "Shadowmaster Skrizzik's behavior was unusual.\n\nHis repeated mutterings about \"shadow magic\" and \"void apocalypses\" and \"ancient creatures hungering for the souls of the living\" certainly warrant further investigation.\n\nYou should report back to Stone Guard Mollivox.", objectives = "Report to Stone Guard Mollivox.", completion = "<Mollivox listens to your report.>\n\nHmm. Yes. I think I know what's going on. It looks like we're going to have to solve this problem with science." }
WordHunterWoW_QuestEN[53927] = { title = "The Precious 13-Tooth Gogglegear", description = "We're going to have to invent something. Something capable of seeing into alternate dimensions. Something explosive that you strap directly onto your eyes.\n\nThat's right, I'm talking about goggles.\n\nI already have all the goggle parts except for one: a 13-tooth gear. They're nearly impossible to find, but I KNOW that the G.G. Engineering boys have one, and Card Trader Ami has their challenge card.", objectives = "Obtain a 13-Tooth Gogglegear from G.G. Engineering. You can purchase their challenge card from Card Trader Ami.", progress = "Are you ready to goggle up?", completion = "<Mollivox forcefully smashes the gear into a pair of goggles.>\n\nThere! Goggles done." }
WordHunterWoW_QuestEN[53928] = { title = "The Mollivox Goggle Experiment", description = "Okay, before we start, I've got a few rules:\n\nFirst, these goggles will only work at close range. We're looking for something INSIDE the arena, so you'll have to be inside the arena to use them.\n\nSecond rule: if you feel something starting to explode, try to blink real hard.\n\nLastly, remember, we're looking for an evil shadow monster. You don't need to kill it, we just need you to see it so we can report it as evidence.\n\nAlright, go get in that arena and try them out!", objectives = "Put on Mollivox's Goggles while fighting in the Brawl'gar Arena and look for evidence against Shadowmaster Skrizzik.", completion = "<Mollivox listens intently as you recount the horror that you witnessed within the arena.>" }
WordHunterWoW_QuestEN[53929] = { title = "Evidence Packet: Shadowmaster Skrizzik", description = "Sounds like we've found our perp, {name}. This guy's sketchy, desperate, and his shadow magic is consistent with that shadowy scroll you found earlier.\n\nBring this packet to Arlu, and we can bring him in. Good work out there!", objectives = "Bring the Evidence Packet to Commander Arlu Ravenhide.", progress = "Any news on Skrizzik?", completion = "<The commander looks over the notes.>\n\nWow. It's worse than I thought. We'd better bring him in soon, because this guy's a nut job." }
WordHunterWoW_QuestEN[53930] = { title = "Undercover Agent: Nugg Lumbo", description = "I've got one more suspect I'm investigating: Libbiara Blightrunner. She's a wealthy blood elf death knight socialite who spends most of her time spectating the arena from the zeppelin up above.\n\nI've got my best agent on the case: Nugg Lumbo. Check in with him to see how his report is coming along.", objectives = "Report to Nugg Lumbo aboard the Skybag, the zeppelin above Brawl'gar Arena.\n\nThe Skybag teleporter is located just outside of the Brawl'gar Arena bar.\n\nTo use the teleporter, you must either be Rank 6 in Brawl'gar Arena, or someone must purchase a Zeppelin Rental Form from Tiana Nevermorn.", completion = "Shh! No blow Nugg cover.\n\nShe over there. You go talk. Nugg watch." }
WordHunterWoW_QuestEN[53931] = { title = "Flaunt It If You Got It", description = "Sigh... so dull...\n\nOh, it's you! {name}, was it? I've seen a few of your fights. They're slightly less tedious than the standard humdrum bloodsport this arena has been producing lately.\n\nLet's spice things up a bit. Maybe buy some expensive drinks for ourselves? Buy a round of the cheap stuff for the riffraff below? Maybe even toss a few amberseed buns off the boat?", objectives = "Drink a bottle of Moneybrau, purchase a round of drinks at the bar in Brawl'gar Arena, and hit a fighting player with an Amberseed Bun while standing on the deck of the Skybag.", progress = "<The death knight socialite sighs.>", completion = "Ha hah! I KNEW you knew how to party.\n\nI'm in a much better mood now. This is the most entertained I've been since that quartermaster was murdered!" }
WordHunterWoW_QuestEN[53932] = { title = "Evidence Packet: Libbiara Blightrunner", description = "Nugg got what Nugg need. Give stupid blood elf one drink and she start getting all self-incriminatey.\n\nYou bring packet to Commander. Nugg gonna buy some expensive snacks.", objectives = "Bring the Evidence Packet to Commander Arlu Ravenhide.\n\nProvided item:", completion = "Hmm... I wouldn't be surprised if she killed the quartermaster just for her own entertainment.\n\nFor now, we can bring her in on counterfeiting charges, and get more details in court. Good work." }
WordHunterWoW_QuestEN[53933] = { title = "The Brawl'gar Trial", description = "I've issued three warrants. Nugg, Mollivox, and Sharisanda are apprehending the suspects as we speak.\n\nIt's time to go to court.\n\nYou may be called on to testify. Just answer as honestly as you can, and let the wheels of justice do the rest.", objectives = "Reach a verdict in the Brawl'gar Trial.", completion = "I really think things were going well there... up to the point where it didn't.\n\nLuckily for us, we've got a new lead. Listen up, <name> - your job isn't done yet." }
WordHunterWoW_QuestEN[53934] = { title = "A Clue from Area 52", description = "We've received a letter from Area 52, the goblin outpost in Netherstorm. The author claims to know details about what they call \"the situation in Brawl'gar\".\n\nThey don't say more than that.\n\nI'm tied to my paperwork here. Go check out this lead and see if anything turns up.", objectives = "Investigate Area 52 in Netherstorm for a sign of the letter's writer.", completion = "These mysterious impostors may have gotten the better of me, and they may have gotten away with murder, but little do they know... I hold the trump card!" }
WordHunterWoW_QuestEN[53935] = { title = "Solving the Mystery", description = "<Bazzelflange produces a challenge card from her pocket.>\n\nI grabbed this challenge card from my attackers while we were fighting each other! I'm sure that you can use it to challenge my attacker to some sort of ultimate showdown!", objectives = "Bring the Mysterious Challenge Card to Brawl'gar Arena to confront Boss Bazzelflange's captor.", completion = "I was there, <name>. I saw your fight.\n\nWe've had our suspicions about this \"Watcher\" character since the incident in Quel'Danas. It seems the rumors are true. They are watching us.\n\nI'll relay the information to the correct authorities. Meanwhile, Boss Bazzelflange and I have arranged for a suitable reward for you. I hope you find it to your liking." }
WordHunterWoW_QuestEN[53936] = { title = "Stopping the Sappers", description = "The ice should keep the Horde out while we handle the sapper teams gathered on the beach.\n\nI'm going to keep those Horde galleons busy. I need you to handle whoever is in charge and bring all the Azerite bombs you find back to me.\n\nThen we'll handle disposing of their weapons.", objectives = "Kill Nebbik Megafuel, collect Azerite bombs, and bring them to Jaina on top of the seagate.", progress = "Were you able to recover the bombs?", completion = "The seagates have protected the heart of Tiragarde Sound for generations. Today is not the day Anglepoint falls.\n\nAs for those Azerite bombs... I have an idea." }
WordHunterWoW_QuestEN[53937] = { title = "The Ub3r-Spanner", description = "It's a shame that Gryzix had to die. Those Venture Co. make all of us enterprising types look bad!\n\nAt least we can still decode the Ub3r-Spanner schematic. Here, hand me that schematic and his decoder and I'll get this whipped up in just a second.", objectives = "Wait for Shuga Blastcaps to decode the schematic.", completion = "Here you go, <name>. Go forth and unleash your creations!" }
WordHunterWoW_QuestEN[53938] = { title = "A Friend in Needle", description = "You can see me?\n\nOh, thank goodness! I thought I was lost in the folds of time...again!\n\nBut for one to see through the folds of time's fabric... you must be a very talented tailor, indeed.\n\nWould you bring me some cloth, then, tailor? I believe I'll be able to place just when I am with your help and right myself.", objectives = "Collect 5 Tidespray Linen and 5 Deep Sea Satin.", progress = "When in Azeroth am I...?", completion = "You're back! That was fast--or, was it?" }
WordHunterWoW_QuestEN[53939] = { title = "Breaching Boralus", description = "Finally! There's no place on Kul Tiras with a stronger Alliance presence. We must be bold and unrelenting if we're going to drive them out here.\n\nLok-tar ogar!", objectives = "Lead the Horde assault into Tiragarde Sound.", progress = "What are you doing here? The Horde needs you in Tiragarde Sound!", completion = "I heard you made quite an impression on Boralus, <name>... Particularly its front gate! Ha!\n\nFor the Horde!" }
WordHunterWoW_QuestEN[53940] = { title = "A Stitch in Time", description = "Hm...I don't know that I've ever been to this time, before.\n\nI suppose I should explain myself. My name is Delormi, and I'm the last remaining member of the Synchronous Tailors.\n\nWe make sure the fabric of time stays, well, mended. But I've found a number of new tears cropping up.\n\nIn fact, I believe that's why I've arrived here in this time. Perhaps you could assist me in tracking them down and repairing them?", objectives = "Assist Delormi in repairing the Tears in Time.", progress = "Something strange is happening. These tears have become too frequent as of late.", completion = "And that takes care of those, although...Something's still wrong..." }
WordHunterWoW_QuestEN[53941] = { title = "A Mech for a Goblin", description = "Gallywix has a plan to deal with the Alliance and has requested your help. It involves the Azerite you reclaimed.\n\nSpeak with him down at Bilgewater Bonanza, and do whatever you can to help him... when it comes to the interest of the Horde.\n\nOh, and make sure Gallywix stays alive. The Alliance already tried to kill him.", objectives = "Meet Gallywix at Bilgewater Bonanza.", completion = "You're here! Good, 'cause we got ourselves problems." }
WordHunterWoW_QuestEN[53942] = { title = "The Right Mech for the Job", description = "Okay, {name}, we're good to go. The G.M.O.D has plenty of Azerite to cause some trouble!\n\nWe gotta head to my, er, OUR base in Drustvar. Mekkatorque, that freakin' king of the gnomes, is attacking our Azerite supply!\n\nAfter we take care of the base, we're gonna take care of him! You get what I'm sayin'?", objectives = "Fly in the G.M.O.D to Drustvar and defend Krazzlefrazz Outpost.", completion = "You and Gallywix saved us! Never thought I'd say something nice about that chin waggler." }
WordHunterWoW_QuestEN[53943] = { title = "Modular Construction", description = "The Abandoned Junkheap is home to some seriously deadly gnomish constructs. These constructs contain Mecha-Cores which could come in handy for crafting the Ub3r-Spanner. Legend has it that it could forge creations unlike anything we've ever seen!\n\nYou look like the adventurous type, {name}. Can you go scrap up some mechs?\n\nDon't forget your Arclight Spanner!", objectives = "Kill mechanical constructs in the Abandoned Junkheap and salvage 8 Mecha-Cores with an Arclight Spanner." }
WordHunterWoW_QuestEN[53945] = { title = "Naga Attack!", description = "", objectives = "" }
WordHunterWoW_QuestEN[53947] = { title = "In the Dunes", description = "This schematic you found is encrypted. My tools are no good on it, not without risking the integrity of the data.\n\nHowever, I do know a guy who can definitely crack this cookie: Mr. Dataguru Gryzix.\n\nIf I remember correctly, he's been vacationing on a beach in Vol'dun since the war broke out. Something about not getting the recognition he deserves. \n\nAnyways, I am sure you can convince him to help you.", objectives = "Find Dataguru Gryzix at The Forgotten Marsh in Vol'dun.\n\nProvided item:", completion = "Ugh, what do you want?" }
WordHunterWoW_QuestEN[53948] = { title = "Vengeful Venture", description = "<You pick up the note and deduce that the Venture Co. are the killers of Dataguru Gryzix. You search his corpse, and find that his decoder and the Ub3r-Spanner schematic have been stolen.\n\nYou need to retrieve his decoder and the schematic and bring them back to Layla Evenkeel to have any hope of crafting the Ub3r-Spanner.\n\nThat mech you have following you should prove itself useful.>", objectives = "Locate the Venture Co. camp, then retrieve Gryzix's Decoder and the Encrypted Ub3r-Spanner Schematic.", progress = "What's up, <name>? Did Gryzix handle that schematic for you?", completion = "He's dead? Poor sap, he was a damn fine engineer.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[53949] = { title = "The Ub3r-Spanner", description = "It's a shame that Gryzix had to die. Those Venture Co. make all of us enterprising types look bad!\n\nAt least we can still decode the Ub3r-Spanner schematic. Here, hand me that recipe and his decoder and I'll get this whipped up in just a second.", objectives = "Wait for Layla Evenkeel to decode the schematic.", completion = "Here you go, <name>. Go forth and unleash your creations!" }
WordHunterWoW_QuestEN[53950] = { title = "Explosive Relief", description = "", objectives = "" }
WordHunterWoW_QuestEN[53951] = { title = "Explosive Relief", description = "", objectives = "" }
WordHunterWoW_QuestEN[53952] = { title = "Simply Dying of Boredom", description = "Up until now, I've been dying of boredom up here. I think maybe we need some new blood here in the arena. Boss Bazzelflange can be so stingy with her invitations, can't she?\n\nI've had one of my servants write up a few slightly-counterfeit invitations to hand out. Maybe you could help me get them distributed? There's always plenty of tough-looking characters hanging out in front of the auction house near Grommash Hold...", objectives = "Use the Brawl'gar Arena Sign in Orgrimmar's Valley of Strength.", completion = "You placed the sign? Good. Now we just wait for the newbies to show up.\n\nI like you, <name>. You're like me: willing to |cFF0000FFcommit a crime|r or two in the name of self-entertainment." }
WordHunterWoW_QuestEN[53953] = { title = "Brawl'gar Awaits!", description = "Tired of standing around in the boring old Valley of Strength? Come on over to the Brawl'gar Arena, and fight for the amusement of others!\n\nYou might win, or you might get killed, but either way, you're going to have a great time.\n\nGrab an invitation and bring it to Skuglor, near the front door. Brawl'gar awaits!", objectives = "Bring an invitation to the Brawl'gar Arena.\n\nProvided item:", completion = "<Skuglor inspects the invitation intently.>\n\nHmph. Looks good enough to me. Come on in." }
WordHunterWoW_QuestEN[53955] = { title = "Warfront: The Battle for Darkshore", description = "Darkshore belongs to the Horde! We must hold that ground to maintain our dominance over Kalimdor.\n\nPrepare yourselves. Battle awaits!", objectives = "Defeat the Alliance at the Battle for Darkshore.", progress = "We must do what we can to claim Darkshore for the Horde.", completion = "Well fought, <name>, though I'm sure it won't be long before the Alliance try to reclaim Darkshore. When they do, we will be ready to fight!" }
WordHunterWoW_QuestEN[53957] = { title = "Darkshore Recruits", description = "We've got a few recruits that can help us take back Darkshore!\n\nBut first, we need our Ancient of War to be back up to good health. To help him, contribute resources to him and he'll perk right up!\n\nOnce the Ancient of War is restored, talk to Jarod Shadowsong and recruit a troop. I'm sure they could learn a lot from fighting alongside you.", objectives = "Restore the Ancient of War, then speak with Jarod Shadowsong to recruit an ally.", progress = "Did you get those recruits?", completion = "Isn't it nice to have people follow you around sometimes?" }
WordHunterWoW_QuestEN[53959] = { title = "Armor for Armies", description = "We need to make sure our soldiers have the best equipment possible in the battle against the Horde. \n\nOnce the Hunter's Hall is constructed, speak with Cordressa Briarbow about how to improve the weapons and armor of our troops.", objectives = "Speak with Cordressa Briarbow to learn what the Hunter's Hall has to offer.", progress = "I regret many things that took us to this moment, but we will do what needs to be done.", completion = "How are our armaments looking?" }
WordHunterWoW_QuestEN[53960] = { title = "The Altar of Elders", description = "Now that contributions are in full swing, the Altar of Elders has been rebuilt.\n\nGo, speak with Moon Priestess Lasara to see what the Altar has to offer.", objectives = "Speak with Moon Priestess Lasara to learn what the Altar of Elders has to offer.", progress = "Have you visited the Altar of Elders yet?", completion = "With that kind of power at our call, we may just stand a chance." }
WordHunterWoW_QuestEN[53961] = { title = "Glaiveworks For Me", description = "We've all been on edge since Teldrassil, but Erion took it hard. He jumped at the chance to help out.\n\nWhy don't you talk to him and see what he's got going at the Glaiveworks?", objectives = "Speak with Erion to learn what the Glaiveworks has to offer.", progress = "How may I help?", completion = "Those glaives will make quick work of those Azerite-mech monstrosities." }
WordHunterWoW_QuestEN[53962] = { title = "Cut from the Same Cloth", description = "My Infinite self was right--I can no longer mend time.\n\nToo many of my threads have been purged. I can feel no others.\n\nI'm alone now. And my thread is gone. But not you.\n\nTake this recipe. You've proven yourself a talented tailor in your own time, and a savior in so many more.\n\nThe fabric of time needs your hands to mend it. I trust you with that responsibility.\n\nTalk to me when you're ready. I'll take you back to when this all began.", objectives = "Ask Timeweaver Delormi to return you to your time." }
WordHunterWoW_QuestEN[53963] = { title = "Naga Attack!", description = "", objectives = "" }
WordHunterWoW_QuestEN[53965] = { title = "Children's Week", description = "Thank you for offering your help with Children's Week, {name}. We have a little girl who is excited to explore Zandalar!\n\nTake dis whistle. With it, you will be able to call de child you have agreed to take care of dis week. It will serve no use after Children's Week ends.\n\nWhen you are ready, use de whistle and meet your new ward! She is a feisty one.", objectives = "Use the Zandalari Orphan Whistle to call for the ward that you will be looking after during Children's Week.\n\nProvided item:", completion = "Who are you? My name's Azala.\n\nMy ma'da and fa'da died when I was little. I've been living here since den, with de other casteless kids. \n\nSince we don't have castes, we gotta try real hard to have good lives when we're grown. If we don't got a connection to de loa or skills dat we can use in battle, we're on our own.\n\nI'm not much of a fighter, but I like de loa. Take me around Zandalar to meet de different loa so dat I can make a connection to dem!" }
WordHunterWoW_QuestEN[53966] = { title = "Loa of Winds", description = "I heard dat Pa'ku lives somewhere in Zuldazar. Her priests tell stories about her when dey come to de Hall of Castes.\n\nShe's a pretty popular loa. I mean, she's in charge of de sky AND de sea! Dat's a lot of blue, and blue is my favorite color!\n\nMaybe I could be one of her followers?", objectives = "Take Azala to Pterror Rise in Zuldazar. Make sure to call for her if she is not present when you get there.", progress = "Do you think dat I'll get wings if I follow Pa'ku?", completion = "I don't know about dis, <name>. De pterrorchicks are pretty cute, but I'm not sure how I feel about heights." }
WordHunterWoW_QuestEN[53967] = { title = "The Frogmarsh", description = "De caretakers are always telling us stories in de Hall of Castes. Sometimes dey warn us about danger, sometimes dey're about de loa... dere's usually a point to dem.\n\nOne time, dey told us about Krag'wa, and how blood trolls killed his followers, and how he hasn't been seen since.\n\nBut I heard dat he's back! He's in Nazmir again, and he's plotting his revenge against de blood trolls.\n\nCan we go see him?", objectives = "Take Azala to Krag'wa's Burrow in the Frogmarsh in Nazmir. Make sure to call for her if she is not present when you get there.", progress = "Where do loa go when dey don't have followers? I hope dey aren't too sad.", completion = "If I followed Krag'wa, would he eat me? Or not eat me?\n\nI don't want to find out." }
WordHunterWoW_QuestEN[53968] = { title = "The Shifting Pack", description = "Dere's one loa I'm extra interested in seeing: Gonk! I've heard de priests say dat he's de most welcoming of de loa. He even lets his followers worship other loa as well!\n\nBut de best thing about him is dat he and his followers can change into many forms. I want to do dat!\n\nWill you take me to meet him?", objectives = "Take Azala to the Lair of Gonk at the Garden of the Loa in Zuldazar. Make sure to call for her if she is not present when you get there.", progress = "Gonk's followers can turn into lots of different things. I think dey're pretty great.", completion = "Did you see how Gonk changed me into all dose shapes?\n\nMaybe one day I can do dat by myself!" }
WordHunterWoW_QuestEN[53969] = { title = "Hunting for Gold", description = "I know dis trip is supposed to focus on de loa...\n\nBut I want to see de island of gold!\n\nI heard stories of undead pirates and an island covered in gold coins and treasure! Can we go see it?! \n\nPleeeease?", objectives = "Take Azala to The Golden Isle in Vol'dun. Make sure to call for her if she is not present when you get there.", progress = "An island made entirely of gold? I gotta see it!", completion = "It's hard to leave so many shinies behind, but curses are some nasty voodoo!" }
WordHunterWoW_QuestEN[53970] = { title = "The Sethrak Queen", description = "De caretakers are always talking about how de sethrak attack caravans... but dey say dat de sethrak and de Zandalari used to be friends!\n\nI heard dat dere are some sethrak who still want to be friends, and dat dey have a loa who wants peace more dan anything!\n\nCan you take me to meet de sethrak and deir loa? I want to meet dem for myself!", objectives = "Take Azala to the Terrace of the Devoted in Vol'dun. Make sure to call for her if she is not present when you get there.", progress = "Do you think de sethrak queen is pretty? Do you think she has shinies?", completion = "Sethraliss seems wise... but very scary, too.\n\n...Are you sure we can't go back for de shiny?" }
WordHunterWoW_QuestEN[53971] = { title = "Return to the Hall of Castes", description = "I can't believe I got to visit so many places. I've never even left Zuldazar before!\n\nI may be casteless, but now dat I've met so many loa, maybe I can follow one and have a future off of de streets.\n\nBut for now, we should go back to de Hall of Castes. De caretakers must be waiting for me.", objectives = "Take Azala back to the Hall of Castes in Zuldazar. Make sure to call for her if she is not present when you get there.", progress = "Wait til de others hear about my trip!", completion = "You know, I kinda missed dis place." }
WordHunterWoW_QuestEN[53973] = { title = "Ride Out to Meet Them", description = "We must defend our warriors from the Alliance army while we recover this Azerite.\n\nTake the Azerite weapons you stole and load them onto one of these gyrocopters.\n\nMisha and I will ride out and fight the reinforcements from the ground, while you provide air support.\n\nWe need to hold them off until our warriors can retreat with the Azerite.", objectives = "Ride the Goblin Gyrocopter and fend off the Alliance army.", completion = "You fought well! The day is won, and the Alliance has been weakened." }
WordHunterWoW_QuestEN[53974] = { title = "Druids of Gloomtide", description = "The latent power at Gloomtide Strand presents us with an opportunity to harness great power. One of our allies, Edgard, has great knowledge into what this might mean for our efforts.\n\nSeek him out and discover the power of nature.", objectives = "Capture Gloomtide Strand, then speak with Edgard to learn what he has to offer.", progress = "Discover anything?", completion = "The enemy stands little chance with this kind of power on our side." }
WordHunterWoW_QuestEN[53975] = { title = "Flying at Night", description = "Now that we control Ashwood Depot, it will be much more convenient to travel about the battlefield.\n\nI've drafted plans for a flight network. It's a rather brilliant plan, if I do say so myself. You don't seem busy. Take my notes and deliver them to our commander at once.\n\nSpeak to Fidelio and he will provide you with a hippogryph.", objectives = "Deliver Evenshade's Note to your commander in Bashal'Aran.", completion = "Excellent work. Though we did not need Mordent's hyperbolic account of his own role in opening the skies for us." }
WordHunterWoW_QuestEN[53976] = { title = "Iron in Hand", description = "This won't work at all! We need to gather iron if we want to make any kind of headway against the Horde.\n\nGo down to the ruins at Lornesta and grab that iron. We need it!", objectives = "Gather Iron from a nearby Ore Crate.", progress = "We need to collect that iron!", completion = "Now we're in business!" }
WordHunterWoW_QuestEN[53977] = { title = "The War Chest", description = "Welcome to the warfront, {name}! We finally get to see some action. \n\nAny resources we've collected will go to the War Chest. Once enough has been gathered there, you can grab it!\n\nWhy don't you pay it a visit and see what you get?", objectives = "Collect resources from the War Chest in Bashal'Aran.", progress = "Got any of those resources from the War Chest?", completion = "Now we're in business!" }
WordHunterWoW_QuestEN[53978] = { title = "Gunpowder Plots", description = "Since the Lord Admiral iced all of their zeppelins, the Horde are rowing in through the seagate.\n\nThe nice, narrow seagate entrance that makes for a great choke point.\n\nI'll have my people haul over a cannon and some ammunition. If you collect some gunpowder, we'll set up behind the gate where they won't expect the attack.\n\nWe'll blast the Horde to the bottom of the harbor!", objectives = "Collect 6 Kegs of Gunpowder.", progress = "Did you find enough gunpowder?", completion = "Excellent! We're all set up here to take out the Horde's boats." }
WordHunterWoW_QuestEN[53979] = { title = "Naga Attack!", description = "", objectives = "" }
WordHunterWoW_QuestEN[53981] = { title = "The Day is Won", description = "The majority of our warriors survived and we have the Alliance's Azerite and weapons.\n\nBe proud of yourself, {name}. You fought with honor today.\n\nGo and inform Nathanos of our victory here. The Azerite should reach them shortly.", objectives = "Return to Nathanos Blightcaller on the Banshee's Wail.", completion = "I've heard of your victory. Well done. The Alliance will be reeling from this defeat.\n\nThe Azerite is being prepared as we speak for our next attack. The Dark Lady trusts you will be willing to aid, when the time comes." }
WordHunterWoW_QuestEN[53982] = { title = "Supplies From The Unshackled", description = "Your aid has given us hope. Your courage has given us strength.\n\nYou have given us an entirely new vision of our future, <name>.\n\nFor that we will be forever grateful.\n\nI hope we can continue to repay you for all you have done!", objectives = "Speak with Atolia Seapearl in Newhome for your reward.", completion = "You're doing great, friend! \n\nTogether we are stronger!" }
WordHunterWoW_QuestEN[53983] = { title = "Wet Work: Fort Knight", description = "", objectives = "" }
WordHunterWoW_QuestEN[53986] = { title = "The Calm Before", description = "A word, {name}.\n\nThere was a raid on the Norwington Estate, where we were testing some new designs of Azerite systems. Lady Jaina asked SI:7 to look into the matter. I have the report here.\n\nI know the Proudmoore family wants a moment together before they're pulled apart again, but the war is still ongoing.\n\nYou have been a friend to her family. Take the report to Jaina. I believe they went to pay respects at the family memorial.", objectives = "Take the SI:7 report to Lady Jaina", progress = "The Horde cannot be allowed to think it can come to our lands without resistence.", completion = "Another attack! The Horde is growing bold. I cannot let this stand." }
WordHunterWoW_QuestEN[53987] = { title = "Wonders of Goblin Technology", description = "Our base has been attacked by all kinds of mechs. Tigers, gorillas, you name it, the Alliance is throwin' it at us.\n\nWe know now that someone is controllin' all of these things, but we don't know from where or how.\n\nWe need you and Gallywix to get out there and blow up those machines before they tear us apart!", objectives = "" }
WordHunterWoW_QuestEN[53988] = { title = "Shores of Fate", description = "So be it. You are more trustworthy an ally than any army Wrynn would have sent.\n\nWe will reclaim Darkshore together, but first we must find Tyrande. Without her at the front, our forces will crumble against the Horde.\n\nShe left for the Zoram Strand with a small force not long ago. If we move now, we may be able to find her before the Horde does.", objectives = "Take the Stormwind portal to Darnassus and meet Maiev Shadowsong at the Zoram Strand in Ashenvale.", completion = "It seems our wayward priestess has been busy." }
WordHunterWoW_QuestEN[53989] = { title = "Hope", description = "No... it is not possible. She would not have died like this!\n\nSearch for signs of her departure along the strand. Personal effects. Weapons. Anything!\n\nTyrande is still out there, {name}. We must not lose hope.", objectives = "Search for signs of Tyrande.", progress = "Anything?", completion = "These would not have been set aside so carefully had she been slain. She is alive!" }
WordHunterWoW_QuestEN[53990] = { title = "In Darkest Night", description = "{name}, I will not mince words. Tyrande foolishly risks her life with the ritual she intends to perform. If she falls, our entire war effort will fall with her.\n\nWe must set off for Darkshore and come to her aid. Only then can we march forward and reclaim our homeland.\n\nWe have lost Teldrassil. Fool or not, our people cannot afford to lose Tyrande as well.", objectives = "Find Tyrande in Darkshore and lend her aid.", completion = "Our vengeance has just begun." }
WordHunterWoW_QuestEN[53992] = { title = "Warfront: The Battle for Darkshore", description = "We will not tolerate further Horde aggression in our territories.\n\nThe night elves will not stand alone this day. Darkshore will be theirs once more.\n\nFor the Alliance!", objectives = "Defeat the Horde at the Battle for Darkshore.", progress = "Darkshore will be ours.", completion = "The day is ours thanks to you, but this war is far from over.\n\nFor the Alliance!" }
WordHunterWoW_QuestEN[53993] = { title = "A Voice on the Wind", description = "<A distant, mysterious voice fills your mind.>\n\nMy enchantments are not lost...\n\nFind me...\n\nDrustvar...\n\nFallhaven...", objectives = "Seek out the source of the mysterious voice in Drustvar.", completion = "Be at ease, friend. I don't want to hurt you. Instead, I have a proposition for you.\n\nYou see, I was a druid once and the only thing I loved more than tending to the forests and creatures within them was enchanting. \n\nThen I was murdered and cursed to wander this peninsula, unable to cross river nor mountain so long as my body still exists. \n\nIf you destroy my old body and help me make a new one, I will teach you how I made the rod you disenchanted." }
WordHunterWoW_QuestEN[53994] = { title = "Naga Attack!", description = "", objectives = "" }
WordHunterWoW_QuestEN[53995] = { title = "The Tauren Tanner", description = "Hey, rich mon.\n\nOne of ya Tauren stopped by and asked who was de best leatherworker I knew who doesn't mind gettin' their hands dirty.\n\nI give 'im ya name, and he asked for an introduction. Said dat he would be in de Bazaar, by de docks.\n\nHe did not say what he needed ma best student for, but de way he was actin' makes me think it is somedin' big.\n\nHead on down to de docks and find dis Tauren. Show 'im what I taught ya.\n\nAnd focus! Needn't be havin' ya make me look bad!", objectives = "Meet the Tauren Leatherworker in the Port of Zandalar.", completion = "Earth Mother be praised!\n\nWe have much to discuss." }
WordHunterWoW_QuestEN[53996] = { title = "Pick Up Sticks", description = "In order for my enchantment to work, we'll need wood from these forests.\n\nWhen I was alive, I would wander these woods and tend to the trees. While those trees are long gone, perhaps their grandseeds have heard their stories and would be willing to help me.\n\nBut don't cut down any of the trees! Please! There are loggers that cut and hew without care for the wilds. Take their hard work so that they will think twice before felling another tree.\n\nBring me as much wood as you can muster.", objectives = "Collect 9 Bundles of Hard Wood", progress = "I miss the voices of the old forest.", completion = "Excellent! The wood appears devoid of pests and rot. Not too long or short. They look thick enough to bend, but only under stress. This will work perfectly!" }
WordHunterWoW_QuestEN[53997] = { title = "The Sixth Sense", description = "For my plan to work, we need to break the spell on my body that is anchoring my spirit to this place.\n\nHowever, my mortal remains are buried deep within this forest. There are wards within it that are designed to trap spirits who are still attached to the material world. Once my remains are cleansed, I will be able to move freely through the woods.\n\nUntil then, I'll need you to disenchant the wards we come across.\n\nSpeak to me when you are ready, and I will lead you to my grave.", objectives = "Escort Sef Iwen to her grave.", completion = "Good work!\n\n<Sef looks introspective for a moment.>\n\nI just realized I never told you my plan." }
WordHunterWoW_QuestEN[53998] = { title = "Exhumed", description = "As I've said, I'm unable to interact with the material world.\n\nI am able to dominate a creature to control its body, but I find it deplorable. In essence, it is enslaving the poor creature.\n\nWhat I want is a body of my own. If you build and animate a golem, it would be devoid of intelligence. A shell. One that I could inhabit without issue.\n\nDoing so will require that my soul is not anchored to anything else in this world, so I need you to remove the spell binding my spirit to my physical remains.", objectives = "Cleanse Sef Iwen's remains.", progress = "Seeing my old self brings back memories.", completion = "I feel... different.\n\nIt's like I'm in the middle of an enormous pitch black room. Not literally, but there is a sensation that there is something lurking just outside of my sight that is... unsettling.\n\nAt least I don't have to worry about the spirit traps any longer, which is nice.\n\nRegardless, with the spell tying me to my remains broken, there is nothing more for us here. Let us continue our journey south." }
WordHunterWoW_QuestEN[53999] = { title = "The Threads That Bind", description = "Our destination is near Gol Koval, but there is something else you could pick up along the way.\n\nI don't want to ask because I hate them, but you cannot dispute the resilience of that horrible webbing that they manage to get everywhere.\n\n<Sef grimaces at the thought.>\n\nThere are spiders to the southeast. As a guardian of nature, I don't want to say kill them, but if you could... 'obtain' some fresh silk from their bodies, we could use it to bind the limbs of the golem together.", objectives = "Collect 55 Durable Spider Silk.", progress = "Did you get the silk?", completion = "<She shivers in disgust.>\n\nBlech! The thought of that being part of my body makes me regret asking.\n\nAs a druid, I was told that there is beauty in all of nature, but I still see none in those spindly legged monstrosities.\n\nLet's keep going. I don't like being near them." }
WordHunterWoW_QuestEN[54000] = { title = "The Beat Goes On", description = "We have most of the materials we need, but we require one final item. A heart.\n\nDon't worry. I don't mean one of flesh, but of stone; to bind the materials of the body into a single form.\n\nFind a smooth stone, and enchant it to hold a life force. It will require some reagents, but I would expect a powerful enchanter such as yourself to have some on hand or know where to find them.\n\nOnce that's done, it will need to be powered. The souls animating the elementals and undead here should do the trick.", objectives = "Create a runic power core and charge it from the corpses of Awoken Guardians and Vengeful Bones.", completion = "That was the last item we needed.\n\nNow we just need to go to my sanctum so we can assemble it undisturbed." }
WordHunterWoW_QuestEN[54001] = { title = "We're Going In", description = "This used to be a Drust shrine. There is a series of sigils that, once invoked, will allow us to teleport to my old sanctum.\n\n<Sef looks around somewhat confused and clears her throat.>\n\nIt has been centuries since I've been here, I'm having a bit of trouble remembering the order in which the sigils need to be activated to open the portal.\n\nI hope you're feeling adventurous. Oh, and be cautious. I enchanted the runes to keep would be intruders out by force.", objectives = "Activate the teleportation runes to enter Sef's Retreat.", completion = "Home sweet home!" }
WordHunterWoW_QuestEN[54002] = { title = "Putting It All Together", description = "Hmm... Everything seems untouched.\n\nWe can begin construction of my new body over here. Afterwards, I'll teach you how to make my enchanting rod.\n\n<Sef smiles at you, beaming with joy.>", objectives = "Assemble the golem for Sef Iwen.", progress = "This has been a long time coming.", completion = "<Sef looks at you, distressed and heartbroken.>\n\nI'm... We could try again, but... I think this is a sign... You seem more than capable of defending those who need it. Maybe it's time for me to move on. \n\n<Sef's frown turns into a half smile.>\n\nI'm eternally grateful for what you did. I may not have a body, but because of you, I don't need one anymore.\n\nBefore I go, let me show you how I made my enchanting rod." }
WordHunterWoW_QuestEN[54004] = { title = "Test Case #1; Mech vs. Mekkatorque", description = "Alright, we got PLENTY of Azerite in this baby to blow up Mekkatorque and his airship.\n\nThat radioactive freak is gonna pay for sendin' his toys to attack one of MY, er, OUR bases!\n\nHop in, {name}. We got a gnome to blow up.", objectives = "Ride the G.M.O.D with Gallywix to face Mekkatorque.", completion = "This ain't over until the fat goblin sings, and buddy, I ain't singing!" }
WordHunterWoW_QuestEN[54005] = { title = "What the Drust Knew", description = "Ahoy, {name}!\n\nIf you have a moment, I could use your assistance. I've recently received a large shipment of Drust relics that I've been processing.\n\nMost of them have been nothing out of the ordinary, but there is this one that is special. Just holding it makes my hair stand on end. \n\nWith you being my best pupil, I was thinking that it would be fun if we disenchanted it together, to see how it was made.\n\nWhat do you say?", objectives = "Carefully remove the enchantment from the Ancient Drust relic to learn about its construction.", completion = "I'm sorry, <name>, I didn't think that enchantment would be so complex. I thought I could maintain the incantation.\n\n\n\nI guess that's it. With the relic destroyed the technique behind its construction is lost.\n\nA shame, really. It's not often that I'm left dumbfounded by another enchanter." }
WordHunterWoW_QuestEN[54006] = { title = "A New Hope", description = "Darkshore belongs to our people once more, in no small part due to your efforts. And, while I disagree with her methods, we would not have succeeded without Tyrande as well.\n\nDifferences aside, she is our leader--and an incarnation of the Night Warrior herself.\n\nShe is about to begin. You may stand here beside me.", objectives = "Witness Tyrande's address to the kaldorei.", completion = "Dori'thur laid this egg when Elune's shadow fell over us. If you are willing, I would entrust her offspring to your care as a token of my gratitude." }
WordHunterWoW_QuestEN[54007] = { title = "Insurance Policy", description = "Mekkatorque called us idiots, can you believe that? Well, if I'm an idiot, then why did I buy an insurance policy on my mech, huh?\n\nI bet that radioactive dimwit doesn't have an insurance policy on HIS mech!\n\nWe're gonna be outta here in no time. I just gotta give a quick call for roadside assistance to come out and fix this thing up.\n\nI need you to go hit the button for roadside assistance on my mech.\n\nJust, uh, don't hit the wrong one.", objectives = "Activate the roadside assistance button on the G.M.O.D.", progress = "You gonna call these guys up or what?", completion = "Maybe I shoulda bought an insurance policy for my insurance policy. \n\nWait, what am I talkin' about? YOU'RE the insurance policy for the insurance policy!" }
WordHunterWoW_QuestEN[54008] = { title = "Insurance Renewal", description = "You know, all I wanna do is blow up Mekkatorque and whatever airship he's ridin' in. Of course it ain't gonna be easy!\n\nI need you to go rescue my roadside assistance so they can fix this mech! They're probably in the Alliance camp near here.\n\nMeanwhile, I'm gonna cook us up a plan. We're gonna give Mekkatorque a real nice surprise!\n\nAnd by real nice surprise, I mean we're gonna blow him up. Oh, and also his airship.", objectives = "Rescue Gallywix's Roadside Assistance", completion = "These guys work fast, look at this thing, it's almost brand new!\n\nAlmost." }
WordHunterWoW_QuestEN[54009] = { title = "Killing on the Side", description = "Those annoying Alliance nearby are definitely takin' orders from Mekkatorque.\n\nThat means they gotta die! And any of their Kul Tiran friends, too. They gotta know the Horde is number one.\n\nAnd that you don't kidnap someone's roadside assistance!", objectives = "Kill 15 Alliance and Kul Tiran soldiers in Vigil Hill.", completion = "Good work mopping up those guys, that'll show 'em to mess with the Horde! \n\nWhat? They weren't messin' with us? Of course they were, they kidnapped my insurance policy!" }
WordHunterWoW_QuestEN[54011] = { title = "Wet Work: Arom's Stand", description = "", objectives = "" }
WordHunterWoW_QuestEN[54012] = { title = "Fortunate Souls", description = "{name}, I am glad to see that you survived the wreck. Many were not as fortunate...\n\nI am capable of stalling the enemy here for now, but this position is not defensible long term.\n\nWe need to find somewhere safe for our forces.\n\nOnce we have taken measure of the wounded we will push on. In the meantime, find as many survivors as you can.\n\nNazjatar will claim no more Horde lives today!", objectives = "Rescue 7 captive soldiers in Spears of Azshara.", progress = "Save as many as you can. We are sorely outnumbered here.", completion = "So few.... It will have to suffice. Without you, we would be even fewer." }
WordHunterWoW_QuestEN[54014] = { title = "Wet Work: Blood in the Sand", description = "", objectives = "" }
WordHunterWoW_QuestEN[54015] = { title = "In Deep", description = "I can keep this barrier up here for a time after our departure, but we cannot remain here.\n\nThese soldiers will not be safe for long.\n\nWe must go deeper into this place to seek a more defensible position.", objectives = "Meet Thalyssra and Lor'themar in Nazjatar.", completion = "Careful! Don't draw attention." }
WordHunterWoW_QuestEN[54016] = { title = "Azerite Transport", description = "", objectives = "" }
WordHunterWoW_QuestEN[54017] = { title = "Wet Work: Warbeast Kraal", description = "", objectives = "" }
WordHunterWoW_QuestEN[54018] = { title = "Descent", description = "What has transpired! That is to say, what has transpired?! Yes, that is the appropriate response, is it not?\n\nI find our circumstances enthralling! Yet, tragic.\n\nI prattle on... Yes, Lor'themar asked me to send you to him at once. He is in need of your expertise, {name}.\n\nI'll lower you down the falls safely. Good luck!", objectives = "Meet with Lor'themar Theron in Nazjatar.", completion = "We have already suffered great losses, <name>. Let us work together to prevent even more." }
WordHunterWoW_QuestEN[54020] = { title = "Wet Work: Gloomwater Span", description = "", objectives = "" }
WordHunterWoW_QuestEN[54021] = { title = "The First Arcanist", description = "Our situation is dire, {name}.\n\nThe Horde fleet was decimated by the attack on Dazar'alor. This naga trap has claimed much of what we had left.\n\nSurvivors report seeing the naga taking captives. Thalyssra has gone on ahead to see what she can do to help them. \n\nI will finish up here while you aid the First Arcanist's efforts. My rangers will provide what little aid they can.", objectives = "Meet with First Arcanist Thalyssra in Nazjatar.", completion = "Ah, <name>. I am glad you survived the attack." }
WordHunterWoW_QuestEN[54022] = { title = "Mekkatorque's Battle Plans", description = "<You find part of plans that indicate where Mekkatorque will be in Tiragarde Sound, along with his airship.\n\nIf you could find the other half of these plans, you would be able to launch an ambush against the gnomish king.>", objectives = "Recover Mekkatorque's Battle Plans", progress = "What're you lookin' into?", completion = "What do ya got there?\n\n... WHAT?! This is perfect!" }
WordHunterWoW_QuestEN[54026] = { title = "Job's Done", description = "I'll stick around here a bit longer to ensure the peons get back to work. \n\nYou should return to Orgrimmar and let Commander Dresh know that he does not need to fret about the outpost any longer.", objectives = "Return to Commander Dresh at Grommash Hold in Orgrimmar.", completion = "The peons have returned? That is good news, indeed.\n\nLet us hope this doesn't happen again, for their sake." }
WordHunterWoW_QuestEN[54027] = { title = "Threat Contained", description = "That should keep those naga down!\n\nYou can have the honor of telling Bladeguard Sonji that the threat to Zuldazar's coast has been contained.", objectives = "Return to Bladeguard Sonji at Grommash Hold in Orgrimmar.", completion = "The naga threat has been contained? I'll trust your word on this, <name>." }
WordHunterWoW_QuestEN[54028] = { title = "Mech versus Airship", description = "We're all set to go, thanks to them battle plans ya found. Looks like Mekko ain't gonna be at his airship right now.\n\nHere's the plan. We're gonna go seriously mess up his ship, then Mekko is gonna swing by to try to save his friends.\n\nBut instead, he's gonna find you and me standin' on the deck of his burnin' ship, waitin' to take him out!\n\nGet in to the mech, {name}, we're blowin' up an airship and a gnome!", objectives = "Ride the G.M.O.D to blow up an Alliance airship and confront Mekkatorque.", completion = "What a ride, huh?" }
WordHunterWoW_QuestEN[54031] = { title = "Gaze of the Loa: Krag'wa", description = "Hello again, small one.\n\nI see Talanji has chosen a worthy witness. I must test Talanji's willingness to sacrifice for her people. I will weigh her commitment to defending the weak. Many great rulers have failed this challenge and still gone on to make powerful monarchs.\n\nBut the most beloved, those that find themselves surrounded by loyal followers, always understand the value of devotion to their people.\n\nYou will help me with this trial. Speak to me when you are ready to begin.", objectives = "\"Witness\" Krag'wa's trial.", progress = "It is my hope that Talanji will honor your faith in her this day.", completion = "I would allow no harm to come to you, <name>. Fortunately for you, an intervention was not needed." }
WordHunterWoW_QuestEN[54032] = { title = "Gaze of the Loa: Pa'ku", description = "Two more loa have declared their intent to test Talanji. The next is Pa'ku. She awaits you both at the top of these steps.\n\nI need not warn you about her tempestuous nature, nor her love for watching others fall from great heights.\n\nGood luck, {name}.", objectives = "Complete Pa'ku's trial.", progress = "I am not yet satisfied, <name>.", completion = "<Pa'ku wipes a tear from her eye using her wing-claw.>\n\nThat was a beautiful demonstration of commitment. Your hair looks lovely.\n\n<Pa'ku cackles.>" }
WordHunterWoW_QuestEN[54033] = { title = "Gaze of the Loa: Gonk", description = "The Lord of the Pack has requested to be the next to speak to Talanji. He is just up the steps on the next terrace.\n\nI do not think he will require quite as much of you as I did, but I believe his words will be relevant to your purposes here.\n\n<Krag'wa winks one massive eye.>\n\nDo not think we are not aware of your intentions, {name}.", objectives = "Complete Gonk's trial.", progress = "Hello again, <name>.", completion = "<The raptor god eyes you speculatively.>\n\nYou will serve to remind Talanji of her priorities, if she is to answer the question I have posed to her." }
WordHunterWoW_QuestEN[54034] = { title = "Gaze of the Loa: Bwonsamdi", description = "<Pa'ku's levity subsides.>\n\nOrdinarily the final trial would be given by Rezan. But the loa of kings is no more.\n\nIt seems ol' Rastakhan picked a new favorite to take his place.\n\n<Pa'ku sneers.>\n\nEnjoy that. Bwonsamdi waits for you in the temple.", objectives = "Complete Bwonsamdi's trial.", completion = "<Talanji nods to you.>\n\nThank you for standing beside me through all of this. Some choices were easier than others, but I am confident in all of them." }
WordHunterWoW_QuestEN[54036] = { title = "A Particular Process", description = "As you might have noticed, Vintner Iltheux is very particular about his wine making process, but his ancient recipe was crafted with only the Nightborne in mind. \n\nWe need something different to please the diverse palates of the Horde!\n\nTalk to Nomi and see what he has in mind to spice things up.", objectives = "Speak to Nomi.", completion = "Good to see you again, <name>. I've already made improvements to the vintner's recipe." }
WordHunterWoW_QuestEN[54041] = { title = "No Survivors", description = "Do you see the encampment on the beach below?\n\nThe Horde followed Tyrande here.\n\nNo doubt some of them have remained here in the shadows in case she returned.\n\nKill them.", objectives = "Kill 8 Veiled Deathstalkers.", progress = "The Horde will pay the ultimate price for crossing the kaldorei.", completion = "These Forsaken still fight, even beyond death. What drives their wicked hearts?" }
WordHunterWoW_QuestEN[54042] = { title = "Trouble in Darkshore", description = "We have received some disturbing reports from Darkshore.\n\nWhat was once a secure stronghold for the Horde is now beset by an unnatural darkness. The moon has turned completely black.\n\nThe outposts there have yet to be reinforced with our main force and we are suddenly outnumbered. Nathanos wants you to meet him in Darkshore and find out what happened.", objectives = "Speak with Dread-Admiral Tattersail to travel to Darkshore and report to Nathanos.", progress = "Have you traveled to Darkshore?", completion = "Your arrival is timely. We have a problem." }
WordHunterWoW_QuestEN[54043] = { title = "Dark Ranger Round-Up", description = "These night elf ambushes have left us undermanned. We need reinforcements if we are to hold Darkshore.\n\nBrynja, one of the Dark Lady's val'kyr, can provide us with those reinforcements. Slay the night elves and command her to raise them into our service. Should any prove unwilling... deal with them.\n\nDid I not make myself clear? Go. The Dark Lady has plans for these dark rangers.", objectives = "Slay Vindictive Sentinels and Archers and command Brynja to raise them as Dark Rangers.", completion = "How quickly they turn against their own goddess." }
WordHunterWoW_QuestEN[54044] = { title = "Black Moon Rising", description = "Darkshore has never been known for being bright and sunny, but something strange has happened here. A black moon hangs over everything.\n\nNone of the scouts I sent into the forest have returned. The night elves are up to something. And I need to know what it is.\n\nTheir rank-and-file won't have the information we seek. Hunt down their lieutenants and get them to talk by any means necessary.", objectives = "Interrogate Lieutenants Golras, Ivyth, and Maliyra.", progress = "<The wisp appears lost and disoriented. It follows you.>", completion = "<The wisp bobs up and down, as if in a daze.>" }
WordHunterWoW_QuestEN[54045] = { title = "Quit Vining!", description = "This is terrible, {name}! We got harvesters that ain't harvestin'!\n\nWe've been busting our rumps chopping down all these trees, but someone keeps tangling up our machines in the vines! I ain't going out there with those night elves stalkin' around.\n\nSee if you can get in there and free up my equipment!", objectives = "Free Goblin Harvesters from vines.", completion = "Now that's more like it! As soon as the boss gets rid of those night elves, we won't have ourselves a lumber problem anymore!" }
WordHunterWoW_QuestEN[54046] = { title = "We're Not Out of the Woods Yet", description = "<The wisp flickers at you in a confused manner. It seems to want to follow you.\n\nPerhaps it has the information Nathanos seeks.>", objectives = "Bring the Lost Wisp to Nathanos Blightcaller in Lor'danel Landing.", progress = "Have you found anything useful?", completion = "That is not exactly what I meant when I said to bring back something useful." }
WordHunterWoW_QuestEN[54047] = { title = "Where Hope Dies", description = "We must carry out the Dark Lady's orders before we are overrun by these newly-invigorated elves.\n\nThere is one night elf in particular that we seek. You may remember her from our last venture into Darkshore. Lucky for you, she is already dead... so she should prove less troublesome than the living ones you've already encountered.\n\nSignal me when you find her corpse.", objectives = "Find the body of Delaryn Summermoon.", progress = "Have you found her yet?", completion = "I sent you to find one dead night elf. It would appear you have outdone yourself." }
WordHunterWoW_QuestEN[54048] = { title = "To Kill A Warden", description = "<The oppressive feeling of being hunted has reached a peak.\n\nYou know there is someone behind you.>", objectives = "Defeat Sira Moonwarden." }
WordHunterWoW_QuestEN[54049] = { title = "The Dead of Night", description = "This is the crux of the Dark Lady's plan for Darkshore. We will raise new champions for the Forsaken and the Horde on this very spot.\n\nGuard the val'kyr. We cannot allow anything or anyone to interrupt them.", objectives = "Protect the val'kyr as they resurrect Delaryn and Sira.", completion = "You made it out. Good.\n\nSo did I." }
WordHunterWoW_QuestEN[54050] = { title = "Aftermath", description = "We all have our reasons for accepting the val'kyr's gift. But now is not the time for those discussions.\n\nSylvanas has been dealt a heavy blow today with the loss of Brynja. We will have no time to rest before the Alliance descends on this place.\n\nNathanos has summoned you. There is something you must see.", objectives = "Speak to Nathanos Blightcaller.", progress = "Have you spoken with Nathanos?", completion = "What happens now? We prepare for battle.\n\nThey will all pay." }
WordHunterWoW_QuestEN[54051] = { title = "Naga Attack!", description = "", objectives = "" }
WordHunterWoW_QuestEN[54052] = { title = "Questfall", description = "Me apologies, matey! New to the bow! More of a sword arm, yeah?!\n\nDidn't mean ta give ya such a start! It's just that we're in a bit of a bind, me an' the crew here!\n\nCan ya give us a bit of a hand?! Some upright dogs attacked us in the dead of night! Chased us out of camp in our skivvies!\n\nMaybe ya can help?! They had some sort of big one as their boss! We've been callin' him Barkpaw on account of he was barkin' at us and had big ol' paws!", objectives = "Slay 8 Riverpaw Gnolls and defeat Barkpaw." }
WordHunterWoW_QuestEN[54058] = { title = "Unintended Consequences", description = "<Xal'atath speaks once more.>\n\nThe servants of N'Zoth prepare for their master's return. They intend to conjure a scouring storm to wash away all unbelievers.\n\nThe particular ritual they will invoke requires three ancient artifacts. One of void, one of storm, and one of ocean.\n\nEven now, I hear the void relic calling to me. It is being empowered... or corrupted, I am not sure which. I see it upon a cliff, overlooking a vast sea.\n\nCome, priest. We can find a much better use for such a prize.", objectives = "Find the Void Stone in Drustvar.", progress = "A change of pace can be invigorating, eh, High Priest?", completion = "Do not be distracted. We have more to do." }
WordHunterWoW_QuestEN[54059] = { title = "The Night Warrior", description = "It appears these night elves won't give up the information easily... but perhaps that wisp you captured will.\n\nSee if you can get it to reveal what happened here. I don't care how you do it.\n\nFather Norlath will handle the wisp from there.", objectives = "Speak with the Lost Wisp to find out why the moon turned dark.", progress = "Have you made that wisp cooperate?", completion = "This is unsettling. We will have to accelerate our plans." }
