WordHunterWoW_QuestEN[54082] = { title = "More Power", description = "Welcome back, dear test subject.\n\nMy dear sister has kindly asked me to administer today's experiment, which falls below our typical standards of legality...\n\nYou may, as always, choose not to participate and we will acquire sufficient replacement test subjects.\n\nOur new project requires more energy than our generator can manage. We must supercharge it with a jolt of power from the outside.\n\nBondo's Yard has the best power line in Mechagon, so we shall siphon what we need from those rapscallions.", objectives = "Connect power lines from Bondo's Yard to the Quickcharge laboratory.", completion = "Our generator is bristling with power... I've never felt so alive!" }
WordHunterWoW_QuestEN[54083] = { title = "Grease The Wheels", description = "Kerchunk said you guys was working on getting that mechaspider running again. Well I'm not gonna let you have all the fun!\n\nThat rusty old thing's gonna need a lot of grease to get moving again. So I jury-rigged a special Grease Trap to help you gather grease from the slimes nearby.", objectives = "Use the Grease Trap to collect 12 Cog Grease from slimes around The Outflow.", completion = "That was greasy work, glad it wasn't me doing it!" }
WordHunterWoW_QuestEN[54084] = { title = "[DNT] Test Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[54085] = { title = "Accessories Sold Separately", description = "", objectives = "" }
WordHunterWoW_QuestEN[54086] = { title = "Right Bot for the Job", description = "We don't waste anything around here. Every defeated bot gets a second chance! \n\nIf I'm going to fix this mechaspider, I'm going to need a few extra wrenchbots working with me. \n\nUse my Bot Re-Energizer on three dead Repeating Wrenchbots and bring them to me, and I'll put them to work.", objectives = "Bring three Repeating Wrenchbots to Recycler Kerchunk", progress = "Did you find those Repeating Wrenchbots yet?", completion = "These bots will work round the clock fixing this mount!" }
WordHunterWoW_QuestEN[54087] = { title = "You Must be This Height", description = "The moment is here {name}. \n\nFor such a historic moment I feel a gnome, such as myself, should be the one to activate the device.\n\nLet me know when you think we should begin.", objectives = "Let me know when I can activate the device.", progress = "This is quite an important discovery!", completion = "I'm sure the king didn't mean any harm to YOU champion. Please don't let this incident deter you. I need your help!" }
WordHunterWoW_QuestEN[54088] = { title = "The Legend of Mechagon", description = "I came as soon as I heard!  A mysterious vault has been discovered in Tiragarde. \n\nCenturies ago, the last king of the gnomes, King Mechagon, led his followers in search of a mythical land of technology. He left no clue as to where he was headed, and over time his legend faded into history. This vault could be the first step to discovering King Mechagon's true fate! \n\nI must examine it firsthand. Meet me there, Champion. I could use your assistance.", objectives = "Meet Tinkmaster Overspark outside the mysterious vault.", completion = "It's as promising as I had hoped! Now that you're here we shall begin the investigation." }
WordHunterWoW_QuestEN[54089] = { title = "Omgar Doombow", description = "", objectives = "" }
WordHunterWoW_QuestEN[54090] = { title = "Toys For Destruction", description = "Ricket sent word that she was here in Mechagon, so I came right away to help with the uh... research.\n\nI had the peons scour the island for any technology they could find. With da stuff we got here, we gonna make some amazing weapons to fight King Mechagon. Then afterwards, we get rich selling 'em!\n\nHelp me wrangle everyone's ideas into one perfect weapon!", objectives = "Help Rocket-Chief Fuselage build the perfect weapon.", progress = "You build an amazing weapon yet?", completion = "Something as beautiful as that, needs to be put to good use!" }
WordHunterWoW_QuestEN[54091] = { title = "Strong Arm John", description = "", objectives = "" }
WordHunterWoW_QuestEN[54094] = { title = "A Goblin's Definition of Success", description = "I'm all set here, I'm just gonna play around with the mech, I think I got a good idea how it works thanks to ya.\n\nNathanos \"prince of all that's death and destruction\" Blightcaller is gonna want you back on that boat, the Banshee's Scream or whatever it is.\n\nHe'll be happy to know we took care of business. Then again, I got no idea if he even feels happy anymore.", objectives = "Meet with Nathanos on the Banshee's Wail.", completion = "Good work. We can breath a little easier knowing our major supply of Azerite is safe.\n\nThe Dark Lady has further plans that will require your aid. We have a promising lead on someone who can help us destroy Kul Tiras from within.\n\nKeep up the fight against the Alliance in the meantime. We cannot afford to let down our guard." }
WordHunterWoW_QuestEN[54096] = { title = "The Fall of the Sunwell", description = "The flame of the lantern dims. Your final task is to rekindle it.\n\nIn order to do so, you must walk one remaining path. While we are fortunate to hold the Sunwell once again, we must always remember that it was yet another part of us that Arthas took away... and that our late prince was forced to find us a new way of life.\n\nEnter the Sunwell Plateau, and witness its fall.", objectives = "Complete the Fall of the Sunwell scenario.", completion = "<The Regent Lord takes the lantern from you.>\n \nIt is done." }
WordHunterWoW_QuestEN[54097] = { title = "The Dark Lady Calls", description = "Champion, the Dark Lady has need of you.\n\nWe cannot speak more of this here. Make haste to Orgrimmar at once.\n\nBest not to keep her waiting.", objectives = "Meet with Lady Sylvanas Windrunner in Orgrimmar.", completion = "My guards are stationed at the door to ensure that this meeting stays private.\n\nNow, let us discuss Varok Saurfang." }
WordHunterWoW_QuestEN[54099] = { title = "The High Overlord", description = "I have asked you here to discuss a matter of great importance to the Horde.\n\nVarok Saurfang is no longer in Stormwind.\n\nLet us discuss this turn of events.", objectives = "Discuss Saurfang's fate with Lady Sylvanas Windrunner in Orgrimmar.", progress = "I trust your discretion in this matter.", completion = "I hope you understand how grave of a situation this is, champion.\n\nThe Alliance will surely kill him on sight. Some members of the Horde consider him a traitor for his willing surrender at the Battle for Lordaeron.\n\nIf Varok Saurfang is to make it back to us alive, it will be up to you. Be discreet." }
WordHunterWoW_QuestEN[54100] = { title = "A Way Out", description = "My spies report that our High Overlord did not leave the way he entered, nor any other way we know of. No signs of him were seen at any of the known exits from the Stockades or the sewers. He simply was in his cell one moment, and gone the next.\n\nBegin your investigation around the city of Stormwind. There must be another way out that we do not know of.\n\nDark Ranger Lyana will meet you there. Her tracking skills are second to none.\n\nDo not fail me, my champion.", objectives = "Meet with Dark Ranger Lyana in Elwynn Forest.", completion = "There is no time to waste. Let us begin our investigation." }
WordHunterWoW_QuestEN[54101] = { title = "On Track", description = "Keep your head down. We do not want to be seen out here.\n\nOur spies keep watch over Stormwind day and night, and saw no signs of Saurfang. \n\nNor did we notice any oddly-oversized carts or strange ships in the night, if that was what you were thinking.\n\nHow then, did he make his escape?\n\nLet's look around.", objectives = "Follow the trail of Varok Saurfang in Elwynn Forest.", progress = "Let us keep investigating.", completion = "SI:7 lurking around Stormwind? Hmm, probably after the same thing we are.\n\nWe need to keep moving." }
WordHunterWoW_QuestEN[54102] = { title = "Eastern Escape", description = "It's not unusual to see SI:7 spies lurking around the city, but something about this doesn't feel right.\n\nWe need to find where Saurfang's trail picks up. The last tracks were heading east, towards Redridge.\n\nThe path to Redridge crosses the Three Corners, one of the Alliance's more well-defended towers.\n\nI have an idea. Meet me there.", objectives = "Meet Dark Ranger Lyana at Three Corners in Redridge Mountains.", completion = "There are few paths through Redridge, save this one.\n\nWe should start the next stage of our investigation here." }
WordHunterWoW_QuestEN[54103] = { title = "Corner Crossing", description = "If Saurfang was headed in this direction, it would have been difficult for him to avoid the Three Corners watchpost. \n\nWe could simply walk in there and demand information, but I have a feeling that they would not part with it willingly.\n\nSo we will take another approach.\n\nI have procured this potion from our alchemists. It will turn us into--ugh--humans for a while.\n\nWe can then question the guards. Perhaps someone saw something.", objectives = "Drink the Humanizing Potion, then question the citizens of Redridge Mountains.", progress = "Let's find out everything we can.", completion = "So, Shaw was involved? SI:7... again.\n\nPerhaps a coincidence, perhaps not. \n\nWe have little to go off of. Let us assume Saurfang continued his path eastward, off of the main trails." }
WordHunterWoW_QuestEN[54104] = { title = "Signs of Saurfang", description = "With the guards drunk at their posts, and others out of position, Saurfang would have had little trouble passing Three Corners undetected.\n\nThe path splits just south of town. The back roads of Redridge are poorly patrolled, and are infested with gnolls and spiders. In other words, perfect for an orc trying not to be noticed.\n\nHis most likely path is Lakeridge Highway. We should continue our investigation there.", objectives = "Follow the trail of Varok Saurfang in Redridge.", progress = "Well? What are you waiting for?", completion = "Well, that was invigorating. \n\nBased on the size of that spider and how injured it was, I'd venture a guess that we are on the right track.\n\nAnd I think I know where to head next." }
WordHunterWoW_QuestEN[54105] = { title = "Ever Eastward", description = "All signs point to our quarry heading farther east. \n\nTo what end, I am not sure. But I have my suspicions.\n\nI am going to scout the area from the air. Let's meet up at Redridge Pass.", objectives = "Find Dark Ranger Lyana at Redridge Pass in Redridge Mountains.", completion = "This is one of the few pathways through the Redridge Mountains. If Saurfang came this direction, it was through this pass." }
WordHunterWoW_QuestEN[54106] = { title = "Tracking Tipoff", description = "Look there, down the hill. One of the Alliance hunters that roam the area.\n\nNo one knows these pathways like them. If our quarry passed through here, that hunter would certainly have seen the tracks. His dogs may even have caught Saurfang's scent.\n\nHere is another dose of the potion. Let us question this one while he is alone.", objectives = "Drink the Humanizing Potion, then question Hunter McAlister at Redridge Pass in Redridge Mountains.", progress = "Let's find out everything we can.", completion = "Thank you for your assistance in this investigation, champion. We have all but confirmed Saurfang's current location.\n\nI must report back to the warchief before we make any further moves. We will summon you if we require your assistance again." }
WordHunterWoW_QuestEN[54107] = { title = "Grim Tidings", description = "Ey mon, dat dark ranger, she be lyin' to ya!\n\nSaurfang knew dey'd be comin' for him. He sent me to watch da pass, see who his assassins be. Try to warn him if I could.\n\nShe not be reportin' back nothin'... she gonna kill him. Most likely got a whole buncha deathguards just waitin' for her signal.\n\nWe gotta stop dem! Ya wit' me?", objectives = "Meet with Zekhan in Swamp of Sorrows.", completion = "It be too late! Dey beat us here!" }
WordHunterWoW_QuestEN[54108] = { title = "A Warrior's Death", description = "She gonna try an' take him in, and den no one ever gonna see Varok Saurfang again.\n\nDis was never a rescue mission. Dis be about power, an' control, an' Sylvanas think she be holdin' all da cards.\n\nBut she didn't count on us!\n\nLet's go!", objectives = "Defend Varok Saurfang in Swamp of Sorrows.", progress = "Will you stand with us?", completion = "I thank you and young Zekhan for your assistance. I knew she would come for me. It was only a matter of time. \n\nAnd I do not think she will give up.\n\nNow I have something I must ask of you." }
WordHunterWoW_QuestEN[54109] = { title = "Queen's Favor", description = "I have two things to ask of you, and I do not ask them lightly.\n\nFirst, I need you to retain the favor of the warchief. She will undoubtedly have questions, and seeds of distrust may begin to grow, but she cannot lose you as an ally. Not now. She would not so willingly part with one of her greatest champions.\n\nIn order to do so, it will have to look like you faced me in combat, and lost. I trust you can take a hit.\n\nSecond, I ask you not to follow me further. I must make this journey alone.", objectives = "Take a hit from Varok Saurfang, then report to Warchief Sylvanas Windrunner in Orgrimmar.", completion = "I have not heard back from Lyana since I sent her on her last mission.\n\nAre you here to complete her report?" }
WordHunterWoW_QuestEN[54112] = { title = "Mistweaver Nian", description = "", objectives = "" }
WordHunterWoW_QuestEN[54113] = { title = "Every Little Death Helps", description = "<The whispers are faint, but grow louder as you hold the blade in your hand.>\n\nSo weak... need... blood... souls...\n\n<The voice trails off, but you can still sense the dagger urging you on.>", objectives = "Assist Xal'atath in recovering its strength.", completion = "Ah... much better. How cruel of that priest to leave me in such a state!\n\nBut enough about me. No doubt you have many questions. I can offer countless answers." }
WordHunterWoW_QuestEN[54114] = { title = "Every Little Death Helps", description = "<The whispers are faint, but grow louder as you hold the blade in your hand.>\n\nSo weak... need... blood... souls...\n\n<The voice trails off, but you can still sense the dagger urging you on.\n\nIt is a familiar sensation.>", objectives = "Assist Xal'atath in recovering its strength.", completion = "Ah... much better. How cruel of you to leave me in such a state!\n\nBut we can reminisce later. No doubt you have many questions. As you know, I can offer countless answers." }
WordHunterWoW_QuestEN[54117] = { title = "Every Little Death Helps", description = "<The whispers are faint, but grow louder as you hold the blade in your hand.>\n\nSo weak... need... blood... souls...\n\n<The voice trails off, but you can still sense the dagger urging you on.>", objectives = "Assist Xal'atath in recovering its strength.", completion = "Ah... much better. How cruel of that priest to leave me in such a state!\n\nBut enough about me. No doubt you have many questions. I can offer countless answers." }
WordHunterWoW_QuestEN[54118] = { title = "Every Little Death Helps", description = "<The whispers are faint, but grow louder as you hold the blade in your hand.>\n\nSo weak... need... blood... souls...\n\n<The voice trails off, but you can still sense the dagger urging you on.\n\nIt is a familiar sensation.>", objectives = "Assist Xal'atath in recovering its strength.", completion = "Ah... much better. How cruel of you to leave me in such a state!\n\nBut we can reminisce later. No doubt you have many questions. As you know, I can offer countless answers." }
WordHunterWoW_QuestEN[54119] = { title = "Hartford Sternbach", description = "", objectives = "" }
WordHunterWoW_QuestEN[54120] = { title = "To Orgrimmar", description = "A darkness in me mind be keeping me from remembering what happened da day I named Sylvanas warchief.\n\nTake me glaive and travel to da pyre where I was cremated in Orgrimmar.\n\nMaster Gadrin be packin' enough juju to call me to dat place.\n\nGo, and I be seein' ya dere.", objectives = "Take the Glaive of Vol'jin to Master Gadrin at Drannosh'ar Blockade, Durotar.\n\nProvided item:", completion = "Vol'jin might be havin' confidence in me skill, but I asked some allies to come aid us. Dis not be an easy task. Talanji be da better choice for such a ritual, but I will do me best." }
WordHunterWoW_QuestEN[54121] = { title = "Breaking Out Ashvane", description = "The Dark Lady wishes to gain another potential ally in the fight against the Alliance.\n\nLady Ashvane, head of the Ashvane Company, was one of the greatest enemies of Kul Tiras until her capture.\n\nWe are going to release her.\n\nMeet Valtrois in Tiragarde Sound. She and Rexxar are working out a plan to break Ashvane out.", objectives = "Meet Valtrois in Tiragarde Sound.", completion = "Your arrival is timely. We have much to do." }
WordHunterWoW_QuestEN[54123] = { title = "It Belongs in My Mech!", description = "Check this out! It's my latest creation that someone else came up with and built, Gallywix's Mech of Death!\n\nI got it fueled with all that Azerite you found, but I still need more of the stuff to give it that extra kick.\n\nI was SUPPOSED to have the stuff from our operations here, but there's some sorta Azerite goop causin' a mess!\n\nMy guy Patch made an Azerite vacuum device. I want you to suck the Azerite outta these slimes!", objectives = "Recover Azerite from Azerite slimes using the Azerite Vacuumizer.", completion = "That's what I'm talkin' about! This bad boy is gonna be fueled up in no time." }
WordHunterWoW_QuestEN[54124] = { title = "Avoiding Lawsuits 101", description = "Yo, {name}! I leave the A.M.O.D. for two seconds to deal with old Gallywix and now I'm knee-deep in Azerite goo!\n\nListen, here's the deal. I need ya to rescue some of these goblins from these monsters.\n\nI'll be honest, I skimped on the money that covers their insurance in the event of Azerite-monster-related injuries.\n\nWhat? Who knew that these slimes would appear and attack these guys!\n\nDo me a solid and get these goblins outta there!", objectives = "Rescue 6 Uninsured Goblin Workers.", progress = "Ya help those guys?", completion = "You're a real life saver! Well, life for them, gold for me.\n\nIf anyone asks, we never talked about this. Ya catching my drift?" }
WordHunterWoW_QuestEN[54126] = { title = "Twist the Knife", description = "The relics are ours... as it was meant to be.\n\nThere is but one more step needed for the great truths to be revealed.\n\nThe naga sought to summon their storm from a place that echoes with ancient power. Though this site has had countless names over the ages, you mortals know it as the Precipice of Oblivion.\n\nI will go on ahead and begin preparations. Join me there.", objectives = "Meet Xal'atath at the Precipice of Oblivion.", completion = "<Brother Pike listens to your tale of Xal'atath and N'Zoth.>\n\nDark tidings indeed, <name>.\n\nI could sense something stirring beneath the waves. If the Old God is on the rise, we must make ready." }
WordHunterWoW_QuestEN[54127] = { title = "Rocket Hop", description = "Horde forces are attacking Tiragarde Sound. Make them regret every footstep upon our soil!Upon completion of this quest you will gain:", objectives = "Repel the Hordes forces attacking Tiragarde Sound." }
WordHunterWoW_QuestEN[54128] = { title = "Necessary Precautions", description = "That was freakin' awesome! We decimated Mekkatorque's puny little army.\n\nWe got a location on where that little punk and his airship is. That's where he's controllin' all his FORMER mechs.\n\nHere's the plan, we're gonna fly over there, blow up that freak, then destroy his airship!\n\nNow, I ain't no idiot, {name}, I'm the smartest goblin alive. First, we gotta take what they call necessary precautions.\n\nTake this manual, I want you to make sure the G.M.O.D is ready to go!", objectives = "Review the G.M.O.D's systems.", progress = "Well? This thing ain't gonna double check itself! Although... maybe it should.", completion = "I don't care what the meter says, I say we're good to go!" }
WordHunterWoW_QuestEN[54129] = { title = "First Mate Malone", description = "", objectives = "" }
WordHunterWoW_QuestEN[54130] = { title = "Our New Friends", description = "I heard that the Alliance is growing! More and more different kinds of people are joining all the time to fight the mean Horde.\n\nI'm not sure where the embassy is, but I heard it's somewhere here in Stormwind. Can you show me how to get there? I want to see all our new friends!", objectives = "Take your Human Orphan to the Stormwind Embassy. If your orphan is not present when you arrive, call for him.", progress = "I bet all of our new friends came from really far away!", completion = "We have so many new friends in the city now! I hope they'll play with me!" }
WordHunterWoW_QuestEN[54132] = { title = "Horde of Heroes", description = "The Alliance has begun a coordinated assault against our forces in Stormsong Valley. Attack the enemy forces and drive them back!", objectives = "Lead the Horde assault into Stormsong Valley.", completion = "I heard Usha spoke highly of your actions in Stormsong in her report... You must have done well, because she hates everyone!" }
WordHunterWoW_QuestEN[54134] = { title = "Many Fine Heroes", description = "The Alliance has the upper hand in Vol'dun.  We strike now!  You will lead our forces to victory!", objectives = "Lead the Alliance assault into Vol'dun.", progress = "Have we pushed the Horde out of Vol'dun?", completion = "I wish I could've seen that final battle in Vol'dun myself! I heard it was incredible... If we had more soldiers like you, this war would be over tomorrow." }
WordHunterWoW_QuestEN[54135] = { title = "Romp in the Swamp", description = "Alliance armies are landing on the shores of Nazmir. Drive them back to the sea. Zandalar is ours!", objectives = "Repel the Alliance forces assaulting Nazmir.", progress = "Nazmir belongs to the Zandalari, and the Horde!", completion = "Thank you, <name>. We cannot allow anyone to take dis land from us.\n\nNot de blood trolls. Not de Alliance. Not any outsiders.\n\nDis land belong to de Zandalari... and de Horde. Forever." }
WordHunterWoW_QuestEN[54136] = { title = "March on the Marsh", description = "The Alliance has begun a coordinated assault against the Horde in Nazmir. Defeat the enemy forces and drive them out!", objectives = "Lead the Alliance assault into Nazmir.", progress = "What news do you bring from the front lines of Drustvar?", completion = "Nazmir may not look like much, but every territory we control opens up strategic options for the future.\n\nPlus, I hear you made quite a dent in the Horde's fleet out there. Ha! That alone was worth the trip." }
WordHunterWoW_QuestEN[54137] = { title = "In Every Dark Corner", description = "The Alliance's hold on Drustvar is weak. We will conquer it for the Horde!", objectives = "Lead the Horde assault into Drustvar.", progress = "What news do you bring from the front lines of Drustvar?", completion = "Wherever the Alliance hides... we will find them.\n\nI'm glad Rokhan and the Darkspear are on our side." }
WordHunterWoW_QuestEN[54138] = { title = "Ritual Rampage", description = "The Alliance has launched an assault into the very heart of the Zandalari empire. Defeat the Horde on their own soil to show them our strength!", objectives = "Lead the Alliance assault into Zuldazar.", completion = "I read Magister Umbric's report... It sounded like quite an impressive display over there. The Horde must know now that we can control powers far beyond theirs." }
WordHunterWoW_QuestEN[54139] = { title = "War Is Here", description = "We need to move, {name}. We've received word that the Alliance have mounted an attack through Nazmir.\n\nMake for the Great Seal. King Rastakhan and Princess Talanji are there forming a plan of attack.\n\nMake no mistake, we will crush the Alliance. They are fools to attack us through Nazmir.", objectives = "Meet King Rastakhan within the Great Seal.", progress = "Let's get moving.", completion = "Let us move, we do not have time." }
WordHunterWoW_QuestEN[54140] = { title = "Ride of the Zandalari", description = "It is time de Alliance see de full fury of de Zandalari. Dey are fools to try an attack in Nazmir.\n\nWe must tell de fleet, our warriors, and our flyers dat dey must move out and go to Nazmir at once.\n\nI will go aid our forces at de Blood Gate. Here is a list of dose you must speak with to mobilize our forces.\n\nMove as fast as you can, we must stop de Alliance as quickly as possible.", objectives = "Mobilize the Zandalari fleet, warriors, and flyers.", completion = "The Zandalari and Horde are engaging the Alliance. We must move!" }
WordHunterWoW_QuestEN[54141] = { title = "The Azsharan Medallion", description = "<On the naga's body you find an ornate metal disc. The writing on its surface resembles elven script, but you cannot decipher it. You suspect the words are written in the Nazja tongue.\n\nPerhaps someone with a knowledge of naga artifacts could translate the text.>", objectives = "Take the Medallion to Collector Kojo.", completion = "A medallion, you say? Well, let's have a look at it.\n\nI don't have all day, you know." }
WordHunterWoW_QuestEN[54143] = { title = "Bird's-Eye View", description = "", objectives = "" }
WordHunterWoW_QuestEN[54144] = { title = "Orders from Azshara", description = "<Kojo studies the medallion and grimaces.>\n\nUgh... naga.\n\nThis medallion is inscribed with orders. Looks like naga have been commanded to invade our shores and seize artifacts of great power.\n\nYou know, I recently came upon one such object. See that dagger over there? Nasty thing. Gives me the willies. I swear I hear it whispering to me.\n\nI found it on an island in Stormsong Valley, on a makeshift altar. Maybe if you take it there, you'll get an idea of how the naga intended to use it.", objectives = "Take the Dagger to the Makeshift Altar.", progress = "<As you place the dagger upon the altar, it seems to shudder and blink at you.>", completion = "<You are filled with a sense of dread and foreboding.\n\nThis is probably a very bad idea.>" }
WordHunterWoW_QuestEN[54145] = { title = "The Loa of Death", description = "Bwonsamdi is a dangerous loa, but even I do not believe he whispered to Vol'jin on his deathbed. To appoint Sylvanas sounds, well... he is not fond of de undead. And from what I have seen of de warchief, she is no fan of death.\n\nWe must be respectful when we speak to Bwonsamdi, or dere will be consequences. Come, stay close.", objectives = "Confront Bwonsamdi.", completion = "Now listen here, mon. Usually, ya disrespectul actions would be mighty irritatin' to Ol' Bwonsamdi. But I be lettin' dis one slide. For now.\n\nWhat ya be talkin' about sounds like some bad mojo. I gonna need ya to find out more from some of me... \"old friends.\"" }
WordHunterWoW_QuestEN[54146] = { title = "Strong New Allies", description = "I heard some adventurers saying that there are new members of the Horde, unlike all the rest! And the best part? They're right here in Orgrimmar!\n\nI don't know where the embassy is... but I bet you do! Can you take me? I heard there are orcs from another planet!", objectives = "Take your Orcish Orphan to the Orgrimmar Embassy. If your orphan is not present when you arrive, call for him.", progress = "New friends in Orgrimmar! That means I can come back and visit them all the time.", completion = "Our new friends are so cool! I can't wait to come back and visit all the time." }
WordHunterWoW_QuestEN[54147] = { title = "Confront The Val'kyr", description = "Vol'jin's spirit is growing in power. I should no longer have to maintain a ritual to keep him here.\n\nDis is fortunate, since Bwonsamdi warned me dat Eyir will likely not be pleased with my presence. Apparently she and Bwonsamdi have a past de loa was unwilling to discuss.\n\nWe can proceed when you are ready.", objectives = "Escort the Spirit of Vol'jin to Eyir.", completion = "Ah... Eyir. Lots of anger and pride in dat one. She not be speakin' ta me for centuries now. I thought for sure she be da one behind Vol'jin's return." }
WordHunterWoW_QuestEN[54154] = { title = "The Hills Have Spies", description = "", objectives = "" }
WordHunterWoW_QuestEN[54156] = { title = "A Path of Blood", description = "De main fleet of de Alliance and Kul Tirans are off de coast in Nazmir. But we cannot ignore de forces here.\n\nDere seems to be a strange fog coming in from Nazmir. De Kul Tirans must be using some of their voodoo to weaken us.\n\nWe must carve a path of blood through dese Alliance fools. Help our forces by weakening de Alliance.", objectives = "Slay 15 Alliance soldiers within the Blood Gate.", completion = "Good, my forces can handle de remnants. You need to keep moving." }
WordHunterWoW_QuestEN[54157] = { title = "No One Left Behind", description = "De warriors here tell me Rokhan made a heroic stand, holding off de Alliance and their champions before being defeated.\n\nRokhan is still here within de Blood Gate, held captive by some strange creature called a Lightforged.\n\nI must stay here and help hold de line. I need you to rescue Rokhan!", objectives = "Rescue Rokhan.", completion = "Thank you, <name>. Rokhan will prove valuable in our fight against de Alliance." }
WordHunterWoW_QuestEN[54161] = { title = "What the Drust Knew", description = "Bal'a dash, {name}.\n\nIf you have a moment, I could use your assistance. I've recently received a shipment of Drust relics that were smuggled out of Kul Tiras.\n\nMost have our usual enchantments, but there is one that is unique. Just holding it makes my hair stand on end. \n\nWith you being my best pupil, I was thinking that it would be enlightening if we disenchanted it together, to see how it was made.\n\nWhat do you say?", objectives = "Carefully remove the enchantment from the Ancient Drust relic to learn about its construction.", completion = "I'm sorry, <name>, I didn't think that the enchantment would be so complex. I thought I could maintain the incantation.\n\n\n\nI guess that's it. With the relic destroyed the technique behind its construction is lost.\n\nA shame, really. It's not often that I'm left dumbfounded by another enchanter." }
WordHunterWoW_QuestEN[54162] = { title = "Hard Landing", description = "", objectives = "" }
WordHunterWoW_QuestEN[54163] = { title = "As the Dust Settles", description = "We have achieved a great victory, {name}, though at a cost.\n\nKing Wrynn is gathering the Alliance leadership in Unity Square to discuss matters. He has requested our presence as well. \n\nGo to Unity Square. I'll meet you there shortly.", objectives = "Meet with Anduin Wrynn in Unity Square.", completion = "Thank you for coming, <name>." }
WordHunterWoW_QuestEN[54164] = { title = "The King's Death", description = "King Rastakhan is dead, the Zandalari fleet has been decimated, and we have lost valuable soldiers.\n\nThe Dark Lady is on her way from Orgrimmar to assess the situation. We must figure out our next move before the Alliance strike again.\n\nI believe protocol now would be to pay respects to the fallen king. We will determine our next move afterwards.", objectives = "Pay respects to King Rastakhan.", completion = "Good, you're all here. Let's begin our discussions." }
WordHunterWoW_QuestEN[54165] = { title = "The Return of Derek Proudmoore", description = "I'll admit, I did not think the Little Lion had it in him to kill King Rastakhan. Blood has been spilled, and vengeance must be had.\n\nGive me a moment to express my condolences, then come with me. We have more to do to win this war.", objectives = "Observe Sylvanas's discussion with Princess Talanji.", completion = "Derek Proudmoore will be twisted to become a weapon against Katherine and Jaina Proudmoore.\n\nThe Allliance brought an army to kill Rastakhan. All we'll need is one Forsaken to kill their leaders.\n\nI will contact you when your aid is further needed. In the meantime, continue the fight against the Alliance, we must survive until this plan is ready." }
WordHunterWoW_QuestEN[54166] = { title = "Set Sail", description = "Assist the Horde by collecting Azerite on Island Expeditions.You will receive:", objectives = "Collect Azerite on Island Expeditions." }
WordHunterWoW_QuestEN[54167] = { title = "Set Sail", description = "Assist the Alliance by collecting Azerite on Island Expeditions.You will receive:", objectives = "Collect Azerite on Island Expeditions." }
WordHunterWoW_QuestEN[54169] = { title = "The Treasury Heist", description = "The Abyssal Scepter is a powerful tidesage artifact and a serious threat to the fleet. The Horde stole it, but it is being held by the Zandalari in their treasury.\n\nThe Storm's Wake has crafted a fake Scepter. Your first job is to obtain the real one without alerting suspicion.\n\nSpeak to me when you are ready to go over the plan.", objectives = "Retrieve the Abyssal Scepter from the Zandalari Treasury.", progress = "Were you successful?", completion = "Mission accomplished on all fronts, it seems. I will ensure that the High Tinker gets the data you collected.\n\nI remember hearing stories of the Abyssal Scepter when I was young. Aside from being a tactical victory, it is good to have this relic back in our hands. Thank you." }
WordHunterWoW_QuestEN[54170] = { title = "Ormin Rocketbop", description = "", objectives = "" }
WordHunterWoW_QuestEN[54171] = { title = "The Abyssal Scepter", description = "The Lord Admiral has proposed our next move. It's something we don't think the Horde will expect, but it's dangerous: We're going to steal back the Abyssal Scepter.\n\nYour name came up as someone who could see it through, if you're willing to take the chance.\n\nMeet Lady Jaina at our base in Xibala. She'll have more information for you there.", objectives = "Meet with Jaina Proudmoore in Xibala in Zuldazar.", completion = "<Jaina looks up from her consultation with Magister Umbric as you approach.>\n\nThis mission will be dangerous, but it's necessary to ensure our victory here in Zandalar." }
WordHunterWoW_QuestEN[54172] = { title = "The Azsharan Medallion", description = "<On the naga's body you find an ornate metal disc. The writing on its surface resembles elven script, but you cannot decipher it. You suspect the words are written in the Nazja tongue.\n\nPerhaps someone with a knowledge of naga artifacts could translate the text.>", objectives = "Take the Medallion to Collector Kojo.", completion = "A medallion, you say? Well, let's have a look at it.\n\nI don't have all day, you know." }
WordHunterWoW_QuestEN[54174] = { title = "Orders from Azshara", description = "<Kojo studies the medallion and grimaces.>\n\nUgh... naga.\n\nThis medallion is inscribed with orders. Looks like naga have been commanded to invade our shores and seize artifacts of great power.\n\nYou know, I recently came upon one such object. See that dagger over there? Nasty thing. Gives me the willies. I swear I hear it whispering to me.\n\nI found it nearby at Atal'Gral, on a makeshift altar. Maybe if you take it there, you'll get an idea of how the naga intended to use it.", objectives = "Take the Dagger to the Makeshift Altar.", progress = "<As you place the dagger upon the altar, it seems to shudder and blink at you.>", completion = "<You are filled with a sense of dread and foreboding.\n\nThis is probably a very bad idea.>" }
WordHunterWoW_QuestEN[54175] = { title = "Face Your Enemy", description = "We have decided that our best course of action would be to enter the prison disguised as Proudmoore military. Rexxar will be our prisoner.\n\nWe want to keep a low profile until we break Ashvane out.\n\nI find that I work better with reference when undertaking this type of endeavor.\n\nI have chosen some humans that interest me. I would like to examine their faces.\n\nUse the Shard of Vesara on them, and they will be... encouraged to find their way to me.", objectives = "Send the targets chosen by Valtrois back for examination.", completion = "Humans can be so malleable." }
WordHunterWoW_QuestEN[54176] = { title = "Be More Uniform", description = "Head into the foundry. Proudmoore's guards have taken over there. They will provide excellent accessories for our disguises.\n\nI can recreate their faces, but without the clothing, we won't make it far.\n\nGather enough gear to cover us. \n\nWe'll need the Captain's jacket as well. \n\nThere will be less of a challenge at the gate if we outrank them.", objectives = "Collect gear from Proudmoore forces in the foundry.", progress = "Was the harvest successful?", completion = "Well done, <name>. This is going better than I expected." }
WordHunterWoW_QuestEN[54177] = { title = "A Brilliant Distraction", description = "We plan to be cautious on entry to Tol Dagor.\n\nI imagine our exit will not be as... subtle.\n\nThat foundry to the west... I hear they made Azerite explosives there.\n\nStock up, we will need them.", objectives = "Retrieve the Volatile Azerite.", progress = "Did you find them all?", completion = "Gently...\n\nMaybe Valtrois should take charge of these. She may be able to stabilize them another way." }
WordHunterWoW_QuestEN[54178] = { title = "Catching a Ride", description = "Nathanos should have found a boat by now.\n\nLet us hasten to meet him in the harbor.\n\nIt behooves us to take care of this business quickly.\n\nThere are better ways for us to support the Horde's effort here.", objectives = "Find Nathanos at the dock in Plunder Harbor.", completion = "This should be adequate." }
WordHunterWoW_QuestEN[54179] = { title = "Through the Front Door", description = "We would like the least amount of risk during your retrieval of Priscilla Ashvane.\n\nYou will arrive on the docks during a shift change. From there, you will prepare and enter the prison. \n\nFind me in Zuldazar when you are successful.", objectives = "Complete \"Escape from Tol Dagor\".", completion = "Your success bodes well for our future endeavors." }
WordHunterWoW_QuestEN[54180] = { title = "Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[54182] = { title = "Bilgewater Bash Brothers", description = "", objectives = "" }
WordHunterWoW_QuestEN[54183] = { title = "Dead Reckoning", description = "While I have some concerns, I cannot deny the bravery, heroism and sacrifices we have made. That you have made, {name}. Thank you for all the aid you have given to the Alliance.\n\nThe future of our ongoing war campaign is why I have asked everyone here. I wish to look at what we've done, so we can decide on the best way forward.", objectives = "Attend the discussion in Unity Square.", progress = "This war may have been necessary, but it is my hope it will be over soon. Then we can begin rebuilding.", completion = "We may be on the cusp of winning but we cannot lose sight of ourselves or we will have lost what is most important and our victories will be for nothing.\n\nI hope it will be as High Commander Wyrmbane and Master Shaw say it is and we will see a conclusion soon. Then... Then we can begin the process of rebuilding and healing - Ourselves as well as Azeroth and the Horde." }
WordHunterWoW_QuestEN[54184] = { title = "Trouble in Gnomeregan", description = "Some strange spikes of electric usage have been happening in Gnomeregan recently. We need you to investigate what is going in there as soon as possible.\n\nWe've received contact from one of the chief engineers in charge of keeping things in Gnomeregan under control, and he has offered to assist us in getting inside to see what's going on.", objectives = "Find Micro Zoox outside of Gnomeregan in Dun Morogh.", completion = "I don't know how this is possible! What is going on in there?! I don't have time to answer your questions or send you off on trivial tasks, there's work to be done! \n\nOh, you want to go in Gnomeregan and find out what's going on? Why didn't you say so?" }
WordHunterWoW_QuestEN[54185] = { title = "Gnomeregan's New Guardians", description = "My personally-modified Mayhem Detection Device has been giving readings off the charts for the last few days. You might be thinking that mayhem and Gnomeregan are synonymous, and to an extent they are, but these readings are beyond anything I've seen before!\n\nI'm not totally sure what's going on inside of Gnomeregan, but something is different. If you are feeling brave enough, I can teleport you deep in there and you can see for yourself.\n\nLet me know when you are ready.", objectives = "Defeat Pulverizer Bot Mk 6001 in Gnomeregan.", progress = "I can teleport you in. Getting out might be more of a challenge.", completion = "Someone stole a schematic from one of Thermaplugg's inventions?  This isn't good, we've heard that a mischievous group has been collecting odd parts from the Wailing Caverns and the Deadmines as well. What crazy thing could they be doing? Who is this group? We better start finding some answers, and soon." }
WordHunterWoW_QuestEN[54186] = { title = "Pet Battle Challenge: Gnomeregan", description = "Gnomeregan's at Mayhem Level Maximum again. Those machines just don't give up, and keep coming back.\n\nI can teleport us in there again, but all of those crazy robots are back. You sure you want this? I don't.  I mean, maybe I want to watch robots smash things for some entertainment.  I'm sure you will be fine. Lets go!", objectives = "Defeat Pulverizer Bot Mk 6001 in Gnomeregan.", progress = "I can teleport you in. Getting out might be more of a challenge.", completion = "Someone stole a schematic from one of Thermaplugg's inventions?  This isn't good, we've heard that a mischievous group has been collecting odd parts from the Wailing Caverns and the Deadmines as well. What crazy thing could they be doing? Who is this group? We better start finding some answers, and soon." }
WordHunterWoW_QuestEN[54187] = { title = "Tea for Two", description = "", objectives = "" }
WordHunterWoW_QuestEN[54188] = { title = "Scrambled Bots", description = "", objectives = "" }
WordHunterWoW_QuestEN[54189] = { title = "Desert Crawl", description = "", objectives = "" }
WordHunterWoW_QuestEN[54190] = { title = "Tea for Two", description = "", objectives = "" }
WordHunterWoW_QuestEN[54191] = { title = "Changing Course", description = "Champion, the time for action is upon us. \n\nDevelopments are underway that will change the course of this war. \n\nReport to me aboard Wind's Redemption as soon as possible.", objectives = "Report to Halford Wyrmbane aboard Wind's Redemption in Boralus Harbor.", completion = "I have news from our allies." }
WordHunterWoW_QuestEN[54192] = { title = "Sensitive Intel", description = "I've received a report from Kelsey Steelspark. She claims to have discovered something that will aid our war effort.\n\nShe's refused to go into specifics, citing a need for secrecy with such sensitive intel.\n\nIt looks like you'll need to speak to her in person. \n\nShe's expecting you in Xibala.", objectives = "Meet Kelsey Steelspark in Zuldazar.", completion = "Take a moment to prepare yourself. I've got huge news!" }
WordHunterWoW_QuestEN[54193] = { title = "This is Huge!", description = "{name}, allow me to introduce Megs and Morton, the gnomes who are going to shake things up for the Alliance in a big way!\n\nThey've been perfecting a device that can take any ordinary animal and turn it into a humongous, unstoppable beast that we can then unleash on our enemies!\n\nI'll let Megs and Morton fill you in on the specifics, but I promise you, this tech is a game changer!", objectives = "Listen to Megs and Morton's plan.", progress = "Wait until you hear their big plan. It's perfect!", completion = "All up to speed, then?" }
WordHunterWoW_QuestEN[54194] = { title = "Real Big Power", description = "We're still building a harness for the Embiggifier, but we need to test its core first. That's where the real power is!\n\nThis technology is years ahead of the Horde's, but it's so easy to use that even an orc could do it!\n\nJust point and click!", objectives = "Test the Embiggifier on a Kul Tiran Clucker.", progress = "I love this part! When we get to see all our hard work pay off in a big way!", completion = "I thought that might happen. \n\nThat poor clucker's mind wasn't strong enough to withstand the Embiggifier, but otherwise, it's working as intended!" }
WordHunterWoW_QuestEN[54195] = { title = "A Beast with Brains", description = "For optimal results, the Embiggifier should be used on someone with substantial intellect. \n\nGood thing our partner is as smart as they come. \n\nHe and his kind have been empowered by kaja'mite, granting them exceptional intelligence! \n\nHead up to the gorge and let Grong know we're ready to begin the embiggifying!", objectives = "Find Grong within Gorilla Gorge.", completion = "So the time has finally come! \n\nI have been awaiting this day--the day my ideas would be brought to life!\n\nBut first, I must see that the gorge will be safe after my departure." }
WordHunterWoW_QuestEN[54196] = { title = "Out of Options", description = "My kind are hunted like animals.\n\nWe've tried to reach a resolution through civil discourse, but these poachers recoil from rational thought. They revel in brutality.\n\nI ask you, {name}: Who are the real animals?\n\nIt pains me to descend to their level, but I fear I've exhausted all other options.", objectives = "Kill 12 Bilgewater goblins within Gorilla Gorge.", progress = "It pains me to descend to their level, but I fear I've exhausted all other options.", completion = "It's a shame we had to resort to violence, but I believe this was the only way." }
WordHunterWoW_QuestEN[54197] = { title = "Freedom for the Da'kani", description = "Have you seen the barbaric conditions to which the Da'kani are subjected? Corralled and caged, awaiting slaughter, or worse...\n\nI cannot leave here in good faith without first seeing that my kind are liberated.", objectives = "Free 8 Da'kani Highbrows within Gorilla Gorge.", completion = "You are a true friend of the Da'kani." }
WordHunterWoW_QuestEN[54198] = { title = "Bittersweet Goodbyes", description = "You've helped me prepare my village for my departure, but now I must prepare myself. \n\nMeet me within the grotto, where I will say my farewells.", objectives = "Meet Grong within Grong's Grotto.", completion = "I am ready." }
WordHunterWoW_QuestEN[54199] = { title = "The Needs of the Many", description = "Ever since the kaja'mite began bubbling around the gorge, I have been searching for meaning. Why was I burdened with intelligence? What is my purpose?\n\nI have found my answers in the Embiggifier.\n\nI was meant to help the Alliance defeat the Horde.\n\nIf I can save lives by volunteering, then my choice is clear.\n\nThe needs of the many outweigh the needs of one.\n\nI am ready, {name}.", objectives = "Accompany Grong to Xibala.", completion = "You don't disappoint, <name>. Grong is the answer to all our problems.\n\nI'll just need him to sign a few dozen documents before we get started. All standard stuff, I assure you." }
WordHunterWoW_QuestEN[54200] = { title = "Bring the Base", description = "We'll need to collect some baseline statistics before we use the Embiggifier.\n\nGrong will be asked to perform basic tasks pertaining to speed, intelligence, and strength. \n\nThis will help us measure the increase once he's been embiggified.", objectives = "Help collect baseline stats for Grong's speed, intelligence, and strength.", completion = "Quite impressive, really! Grong's in superb condition." }
WordHunterWoW_QuestEN[54201] = { title = "Fit for Grong", description = "Grong is already impressively large. In fact, I don't think our Embiggifier is going to fit around his noggin without some modification. \n\nI'll require an ample supply of ore to make the necessary adjustments, but we're in luck. The goblins nearby have already done the work of mining it; we just need to take it off their hands!\n\nSecure an ample amount of Azerite-infused ore, and we'll be back in business!", objectives = "Collect 12 Azerite Infused Ore.", progress = "Have you acquired the ore?", completion = "This should help ensure the Embiggifier is a perfect fit!" }
WordHunterWoW_QuestEN[54202] = { title = "Calibrate the Core", description = "The Embiggifier is nearly ready! All that's left to do is calibrate its core. \n\nThe best way to do that without catastrophic results is to use it on things that are already dead.\n\nThis should be a simple task!\n\nI have a hunch you excel at making things dead.", objectives = "Calibrate the Embiggifier's core by using it on dead things within Bilgewater Bonanza.", progress = "Have you calibrated the core yet?", completion = "The calibration is complete? Splendid!" }
WordHunterWoW_QuestEN[54203] = { title = "The Embiggining", description = "I'll give you the quick rundown before we get started.\n\nThe Embiggifier is remotely controlled. \n\nSee this big red button?\n\n<Megs gestures to the device in her hand.> \n\nThis jolts the wearer with a surge of power, making them bigger.\n\nFor safety reasons, you should remain here at camp. \n\nI think that's it! Are you ready to science?", objectives = "Test Grong's stats while embiggified.", progress = "Let's see what Grong can do once he's been embiggified!", completion = "Grong exceeded all our expectations. I'd say this is a resounding success." }
WordHunterWoW_QuestEN[54204] = { title = "Total Temple Destruction", description = "Grong is our greatest achievement, and he's ready to be unleashed!\n\nThe Horde is staging its troops at a temple to the north. \n\nMagister Umbric's portal will get you there fast. Then Grong can get to work!", objectives = "Command Grong to defeat the Horde at Temple of the Prophet.", completion = "I'm not sure how I feel, <name>. \n\nThe Embiggifier worked, but Grong won't ever be the same.\n\nI suppose it's what he wanted, and what we need if we hope to win this war." }
WordHunterWoW_QuestEN[54205] = { title = "A Nice Nap", description = "I'm not sure how much longer those chains will hold. \n\nGrong's going to have to take a little nap until he's ready to be deployed.\n\nUse this dart. It's been double-dipped in something potent enough to take down a direhorn, so it should do the trick. \n\nGrong would want you to be the one to do it.", objectives = "Use the Tranquilizer Dart on Grong.", progress = "Go ahead, use the dart on Grong. He won't feel a thing, I promise.", completion = "Grong will go down in history as a true hero of the Alliance." }
WordHunterWoW_QuestEN[54206] = { title = "The Sleeper Agent", description = "Your work here is done, {name}. Morton and Megs can take it from here. \n\nHead back to Boralus and let Halford know we've secured the weapon. \n\nDon't you worry one wink about Grong. Morton and Megs will make sure he's well looked after.", objectives = "Report back to Halford Wyrmbane in Boralus Harbor.", completion = "Are you certain about this? Our secret weapon is a gorilla? \n\nI suppose I'll just have to trust that the gnomes know what they're doing. \n\nThank you for your report, <name>." }
WordHunterWoW_QuestEN[54207] = { title = "Retaking the Outpost", description = "We can handle de rest of de Alliance. I received a report that Hexlord Raal's forces are having issues up ahead.\n\nHe claims dat dere is an even thicker fog enveloping Nazmir. De Alliance must be using some tricks to slow us down.\n\nGo to Nazmir to see what can be done to help Hexlord Raal. We must reach dat fleet and destroy de Alliance!", objectives = "Meet Hexlord Raal in Nazmir.", completion = "I wish I had better news to tell you and Princess Talanji." }
WordHunterWoW_QuestEN[54208] = { title = "Minesweeper", description = "The Alliance are stalling our efforts here with this irritating fog, as well as layering the entire area with traps.\n\nWe will suffer too many casualties if we try marching our army through this trap-infested area.\n\nI've heard you're good at sneaking around. Use your talents to disarm the traps in this area.\n\nI'll deal with getting the goblin's parts back from the Alliance while you disarm those traps.", objectives = "Disarm 10 traps within the Fallen Outpost.", completion = "Good, we should be able to march our army now. Rokhan and I recovered enough parts for these goblins to rebuild their machine." }
